quests[9888] = { id = 9888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unfähige Anführer", description = "Ich bin dem sicheren Tode entronnen, habe einen feigen Angriff bei Nacht von den Felsfäusten auf mein Dorf überlebt.\n\nAber ich frage Euch, Fremder, wozu?\n\n<Jorin zeigt auf Garrosh.>\n\nEr hat uns jegliche Unterstützung verweigert. Oger toben durch meine Stadt und er sitzt nur da und heult den Mond an. Was ist aus uns geworden? Was wird aus uns werden?\n\nIch habe einen Späher, Kilrath, zum Dorf, den jetzigen Ruinen des Blutenden Auges, geschickt. Könnt Ihr ihn bitte suchen und unterstützen? Er versteckt sich an der Grenze zwischen Nagrand und Terokkar.", sourceObjective = "Jorin Totauge möchte, dass Ihr Kilrath sucht und mit ihm sprecht.", completion = "<Kilrath flüstert.>\n\nDiese Oger sind extrem sonderbar. Und auch extrem dumm. Schaut nur, wie der fette den, äh, weniger fetten zum Tanzen zwingt. Es ist faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[9889] = { id = 9889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht den Fetten töten!", description = "Ich beobachte diese Kreaturen nun schon seit Tagen. Der Fette sagt, dass er auf etwas wartet. Worauf bleibt jedoch ein Geheimnis.\n\nIch habe einen Plan, aber er erfordert ein wenig Brutalität von Eurer Seite. Ihr werdet einige seiner Untertanen töten müssen und ihn dann fast tot schlagen. Wenn Ihr das tut, bin ich sicher, dass er uns alles erzählen wird, was wir wissen wollen.", sourceObjective = "Kilrath in den Wäldern von Terokkar möchte, dass Ihr 10 Eindringlinge der Felsfäuste tötet und Unkor den Rücksichtslosen so lange schlagt, bis er redet.", progress = "Ich gebe auf! Ich gebe auf!", completion = "Lasst mich leben und ich sage Euch alles, was Ihr wissen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9890] = { id = 9890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolg!", description = "Seit vielen Jahren hatten die Felsfäuste die Herrschaft über alle Oger der Scherbenwelt. Die Oger waren unter Krol vereint und zufrieden mit den Ländereien, die sie erhalten hatten. In den letzten Monaten haben wir jedoch viele Oger an einen Klan namens Totschläger verloren. Die Totschläger haben den größten Teil unseres Landes in Nagrand in Beschlag genommen und viele unserer Leute getötet.\n\nWir hatten keine andere Wahl als dieses Dorf einzunehmen. Wir werden ausgerottet...\n\nKrol ist verschollen und die Felsfäuste sind in Aufruhr. Lantresor von der Klinge hat in seiner Abwesenheit die Führung übernommen.", sourceObjective = "Teilt Kilrath in den Wäldern von Terokkar die Informationen, die Ihr aus dem Oger geprügelt habt, mit.", completion = "Ganz ruhig, {name}. Ich bin nur ein kleiner Schurke. Ich habe keine Ahnung, was ich mit solch einer Information anfangen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[9891] = { id = 9891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weil Kilrath ein Feigling ist", description = "Erzählt Jorin in Garadar, was Ihr gehört habt. Ich bin mir sicher, dass er nicht erfreut sein wird zu hören, dass unser Dorf zerstört und viele unserer Leute getötet wurden, weil die Oger mehr Platz brauchen.\n\nMögen die Ahnen über Euch wachen... Ich werde mich in den Büschen verstecken, falls Ihr mich noch braucht.", sourceObjective = "Erzählt Jorin Totauge in Garadar in Nagrand, was Ihr aus Unkor herausprügeln konntet.", completion = "Sie denken also, dass sie uns Orcs nach Lust und Laune vertreiben und abschlachten können, was? Ich bin mir sicher, dass das nichts damit zu tun hat, dass unser Anführer ein unfähiger Jammerlappen ist... Wenn er doch nur einen Bruchteil der Leidenschaft seines Vaters geerbt hätte...", sourceObjectiveStatus = "unverified-source-field" }
quests[9892] = { id = 9892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Obsidiankriegsperlen", progress = "Habt Ihr noch mehr Kriegsperlen? Ihr findet genügend Oger weit im Norden, an der Grenze zu den Zangarmarschen.", completion = "Wir werden gut an diesen Perlen verdienen, {name}. Ich werde Khoraazi ganz sicher von Eurer Arbeit hier erzählen." }
quests[9893] = { id = 9893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidiankriegsperlen", description = "Während wir hier darauf warten, dass wir endlich am Oshu'gun graben können, verlieren wir so viel Gewinn, {name}.\n\nZum Glück habe ich eine andere Einkommensquelle entdeckt. Die Oger von Nagrand tragen Kriegsperlen aus Obsidian, ein Gestein, das in vielen anderen Welten sehr wertvoll ist.\n\nZerid musste sich aus Sicherheitsgründen bereits mit diesen Rohlingen auseinandersetzen. Betrachtet die Kriegsperlen also als kleinen Bonus. Oder noch besser, betrachtet sie gar nicht und bringt sie mir einfach.", sourceObjective = "Bringt 10 Obsidiankriegsperlen zu Gezhe beim Aerissteg in Nagrand.", progress = "Wie führen die Oger sich auf, {name}? Harte Nuss, was?", completion = "Ausgezeichnet. Das wird uns über Wasser halten bis die Sha'tar fertig sind mit was immer sie auch im Oshu'gun tun mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9894] = { id = 9894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützt die Behüter", description = "Während Eurer Reisen habt Ihr vielleicht ein paar der Behüter der Expedition getroffen. Sie kümmern sich hauptsächlich um die Feldstudien, das heißt die Dokumentation der einzigartigen Bewohner der Marschen, das Sammeln von Proben und die Kontaktaufnahme mit den vernunftbegabten Arten.\n\nDie Sicherheit der Behüter ist von äußerster Wichtigkeit, {class}. Wir mussten die Behüter, die sich aufgemacht haben, um die Funggorhöhle im Süden zu erkunden, wegen Angriffen von Sumpfmonstern zurückrufen. Aufseher Hamuht ist der Meinung, dass wir ihren Angriffen ein schnelles Ende machen könnten, wenn wir ihren Anführer, Lord Klaq, töten.", sourceObjective = "Tötet Lord Klaq und kehrt danach zu Windruferin Schwarzhuf in der Zuflucht des Cenarius zurück.", completion = "Ihr habt meinen Dank, {name}, und den der Behüter. Sie werden sich freuen zu hören, dass sie ihre Arbeit im Süden nun ohne Angst vor weiteren Angriffen fortsetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9895] = { id = 9895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Gleichgewicht geraten", description = "Habt Ihr die Umgebung genau betrachtet, {name}? Dies ist eine dahinsiechende Landschaft, die verzweifelt versucht ihr Gleichgewicht zu halten und den Kampf verliert.\n\nWenn man weiß, worauf man achten muss, kann man die Symptome deutlich erkennen. Einige Vertreter bestimmter Gattungen überholen ihre Artgenossen, was das Wachstum angeht, bereits und werden aggressiv.\n\nEin gutes Beispiel für so ein unkontrolliertes Wachstum ist der Marschenläufer Sumpfschläger. Wenn Ihr ihn selbst sehen wollt, müsst Ihr nur zu den Wasserwegen südlich der Zuflucht gehen.\n\nAber haltet Euch bereit, Euch zu verteidigen. Diese Kreatur kennt kein Erbarmen.", sourceObjective = "Sucht und vernichtet Sumpfschläger und kehrt dann zu Lethyn Mondfeuer in der Zuflucht des Cenarius zurück.", completion = "Jetzt, da Ihr die Anzeichen der Unausgeglichenheit mit eigenen Augen gesehen habt, achtet bei Euren weiteren Reisen darauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[9896] = { id = 9896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzsichels Fluch", description = "Bei Khaz'goroths brennendem Nabel, ist das heiß hier! Ich kann es der ersten Gruppe nicht verübeln, dass sie abgereist sind, aber wisst Ihr, es war nicht die Hitze, die sie verjagt hat. Nein, es war Schwarzsichel, auch wenn sie das natürlich nicht zugeben möchten.\n\nSie hatten ihr Lager südlich von den leuchtenden Draeneitürmen im Westen aufgeschlagen, gleich nördlich von Wildfenn, als die riesige Wespe aus dem Nichts auftauchte und sie angriff! Ich kann es kaum erwarten, ihre Gesichter zu sehen, wenn ich den Stachel des Biests nach Eisenschmiede bringe!", sourceObjective = "Bringt Schwarzsichels Stachel zu Ausgrabungsleiter Conall in Telredor.", progress = "Habt Ihr den Stachel bekommen können? Denkt daran, wenn er beschädigt ist, ist er wertlos für mich!", completion = "Ich kann Euch gar nicht genug danken, Kumpel. Ich werde es genießen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9897] = { id = 9897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin gerettet!", description = "Es macht mir nichts aus zu teilen. Ich bin nur froh, dass ich vor diesem Widerling Diebus sicher bin! Und ich habe Tonnen von Tierhäuten in den Zangarmarschen gesammelt, es ist also überhaupt kein Problem!", sourceObjective = "Gebt Harold Fährten bei Nesingwarys Safari in Nagrand das Bündel mit Tierhäuten.", progress = "Es ist sehr...<hust>...nett von Kristen, dass sie ihre Tierhäute teilt, meint Ihr nicht?", completion = "Nun, ich konnte nicht wissen, ob Ihr Kristen helfen konntet oder nicht. Aber wenn sie Euch eines ihrer Bündel mit Tierhäuten gegeben hat, müsst Ihr wohl in Ordnung sein.\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9898] = { id = 9898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respekt erlangen", description = "Magasha ist die wildeste Trollfrau im Sumpf, aber sie respektiert nur mächtige Jäger.\n\nIch hab schon versucht, mich ihr zu beweisen, aber die einzige Bestie, mit der mir das gelingen könnte, ist mindestens eine Nummer zu groß für mich. Wärt Ihr vielleicht so nett, mir zu helfen? Es gibt da eine riesige Sumpfwespe namens Schwarzsichel, die sich in der Gegend südlich der leuchtenden Draeneitürme im Westen herumtreibt. Wenn Ihr mir ihren Stachel bringen könnt, gibt Magasha mir vielleicht eine Chance, mich ihren Jägern anzuschließen.\n\nIch weiß, das ist nicht ganz ehrlich, aber ich verspreche Euch, dass ich von ihr lernen und Euch beide stolz machen werde.", sourceObjective = "Bringt Schwarzsichels Stachel zu Reavij im Sumpfrattenposten.", progress = "Ich werde Glück haben - ich fühle es.", completion = "Fantastisch! Ich werde nie vergessen, dass Ihr mir geholfen habt, ihr Herz zu gewinnen. Ihr sollt der Ehrengast auf unserer Hochzeit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9899] = { id = 9899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerledigte Arbeit", description = "Jemand muss Reavij zur Vernunft bringen! Er vernachlässigt seine Pflichten und verschwendet stattdessen all seine Energie darauf, meine Aufmerksamkeit zu erlangen. Ich habe versucht, ihn zu ignorieren und ihm gesagt, dass er damit aufhören soll. Aber nichts scheint zu helfen.\n\nBis er es endlich sein lässt, muss ich ständig hinter ihm aufräumen. Er hätte sich eigentlich um Sporenschwinge kümmern sollen, aber das Monster ist immer noch wohlauf. Wenn Ihr Zeit habt, könntet Ihr vielleicht in den westlichen Teil des Todesmoors gehen und den Segler töten? Ich kümmere mich in der Zwischenzeit um Reavij.", sourceObjective = "Magasha im Sumpfrattenposten möchte, dass Ihr Sporenschwinge tötet.", completion = "Wenigstens einer hier erfüllt seine Pflicht. Vielen Dank, dass Ihr Euch um diese Angelegenheit gekümmert habt, {name}. Ich muss einmal mit Zurai über Reavij sprechen. Seine Tagträumereien müssen langsam ein Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9900] = { id = 9900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gava'xi", description = "Die Anwesenheit von astralen Schurken in dieser Gegend mag Gezhe, der in allem eine Möglichkeit sieht, vielleicht erheitern, aber sie sind eine wirkliche Bedrohung für die Sicherheit unserer Unternehmung.\n\nIhr Anführer, Gava'xi, ist ein gefährlicher Krimineller, und ich habe es zu meinem höchsten Anliegen gemacht, ihn zur Strecke zu bringen.\n\nWenn Ihr Euch nützlich machen wollt, dann zieht los und kümmert euch um Gava'xi. Ich werde mich darum kümmern, dass Ihr angemessen entlohnt werdet.", sourceObjective = "Tötet Gava'xi in der Nähe des Oshu'gun und kehrt dann zu Zerid beim Aerissteg in Nagrand zurück.", completion = "Dank Euch müssen wir uns nun nicht mehr vor Gava'xi fürchten. Wollen wir uns nun um eure Belohnung kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9901] = { id = 9901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Die erste Expedition, die die Liga losgeschickt hatte, berichtete von einem riesigen Sporensegler namens Sporenschwinge. Sie mussten sehr hastig aufbrechen, deshalb hatten sie keine Gelegenheit, das Tier umzubringen. Deshalb dachte ich mir, ich erledige das für sie.\n\nIn ihrem Bericht stand, dass die Kreatur sich im südwestlichen Teil des Todesmoors aufhält. Ich glaube, Verteidiger Idaar erwähnte einmal, dass es sich nordöstlich von Telredor befindet.", sourceObjective = "Ausgrabungsleiter Conall in Telredor möchte, dass Ihr Sporenschwinge tötet.", completion = "Gut gemacht, {name}. Ich glaube, wir beide lassen ein ganzes Team von Ausgrabungsleitern neben uns blass aussehen. Wenn ich zurück in Eisenschmiede bin, werde ich mir meine Einsatzorte sicher selbst aussuchen dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9902] = { id = 9902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrecken des Sumpflichtsees", description = "Meine Reisen durch das Gebiet der Naga haben mir einen Eindruck vermittelt, wie schlimm es meinen unglücklichen Brüdern und Schwestern gehen muss. Am Sumpflichtsee im Südwesten habe ich beobachtet, welch tödliches Spiel einer der besonders bösartigen Zuchtmeister treibt. Er jagt seine Sklaven ins Wasser, wenn er weiß, dass Terrorklaue, ein riesiger Sumpfstrok, Hunger hat.\n\nDie Folgen brauche ich nicht weiter erläutern. Wir sind zu wenige, um die Naga direkt anzugreifen, aber wir können ihnen den Spaß verderben, indem wir ihr Haustier umbringen.", sourceObjective = "Tötet Terrorklaue und kehrt dann zu Puluu in der Oreborzuflucht zurück.", completion = "Habt Dank, {name}. Vielleicht werden diese Marschen mit der Hilfe der Draenei eines Tages frei von Naga sein. Ich kann mir gar nicht vorstellen, wie schlimm es sein muss, ihnen dienen zu müssen.\n\nEr spricht nicht oft darüber, aber Maktu war einst ihr Sklave.", sourceObjectiveStatus = "unverified-source-field" }
quests[9903] = { id = 9903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Größte von allen", description = "Ihr seid zwar mit den meisten der kleineren Hydras fertiggeworden, aber ich glaube kaum, dass Mragesh von Eurer Vorstellung beeindruckt war. Er ist eine gerissene, grausame Bestie und hat schon so manchen Angler auf dem Gewissen.\n\nIch habe mir vorgenommen, die Letzte zu sein, die er je belästigt. Er soll sich tief im Schlangensee im Nordosten verstecken. Er ist schon Geschichte, aber das weiß er noch nicht.", sourceObjective = "Tötet Mragesh und kehrt dann zu Zurjaya in Zabra'jin zurück.", completion = "Ich bin mir sicher, der alte Knabe hat das Ende seiner Tage schon vorausgesehen. Bei all diesen Neuankömmlingen musste die alte Rangfolge sich einfach ändern. Es ist nur recht, dass sein Geist nun zu Ruhe kommen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9904] = { id = 9904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf Terrorklaue", description = "Ich habe jeden erdenklichen Fisch in den Marschen gefangen, aber einer ist mir bisher entkommen. Sicher habe ich auch Aale und Morastflossenfrenzys gefangen. Aber als ich das letzte Mal am Sumpflichtsee war, hat einer angebissen, meine Schnur zerrissen und ist abgehauen.\n\nTerrorklaue wird er genannt, und ich werde nicht ruhen, bis er tot ist. Er ist zu groß um ihn mit einer Angel zu fangen, also müssen wir ihn wohl auf die altmodische Art umbringen.", sourceObjective = "Tötet Terrorklaue und kehrt dann zu Zurjaya in Zabra'jin zurück.", completion = "Endlich! Wahrscheinlich hat jeder Angler eine Geschichte über \"den, der mir entkommen ist\". Aber ich habe noch keinen Fisch getroffen, den man nicht auf die eine oder andere Art bezwingen konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9905] = { id = 9905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maktus Rache", description = "Als Maktu letztes Mal auf Hydrajagd am Schlangensee war, wurde er von größter Hydra, die er jemals gesehen hat, angegriffen. Maktu hat nach seinem Speer gegriffen, aber es war schon zu spät. Er konnte gerade noch entkommen, bevor er zu Hydrafutter wurde.\n\nWer weiß? Vielleicht hat Maktu nächstes Mal nicht mehr so viel Glück. Maktu will, dass es kein nächstes Mal gibt. Werdet Ihr Maktu helfen, sich an Mragesh zu rächen?", sourceObjective = "Sucht und tötet Mragesh und kehrt dann zu Maktu in der Oreborzuflucht zurück.", completion = "<Maktu nickt anerkennend.>\n\nMaktu ist dankbar für Eure Hilfe. Maktus Stolz ist befriedigt. Er wird nicht mehr so unvorsichtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9906] = { id = 9906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sag's mit Fäusten", description = "Oger interessieren sich nur für das Eine: Macht. Wenn wir ihnen gegenüber Schwäche zeigen, werden sie sich das zum Vorteil machen und uns ausrotten.\n\nGarrosh ist vielleicht bereit dazu, die Hände in den Schoß zu legen und diese Hunde unser Land übernehmen zu lassen, aber ich bin es nicht! Ich möchte, dass Ihr den Totschlägern eine Nachricht zukommen lasst, die sie verstehen: Gewalt.\n\nReist zu den Ruinen der Brennenden Klinge südöstlich von hier und zeigt ihnen die Macht der Mag'har.\n\nUnd {name}, schaut bei den anderen vorbei, bevor Ihr geht.", sourceObjective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr 8 Zermalmer der Felsfäuste und 8 Mystiker der Felsfäuste tötet.", completion = "Unser Auftrag ist noch nicht zu Ende. Es gibt noch andere, die einer Lektion bedürfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9907] = { id = 9907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kühner Angriff", description = "Direkt im Westen von hier findet Ihr das Halaanibecken. Im Becken befinden sich die Zwillingsschluchten von Nagrand: Nordwind und Südwind. Die Schocktruppen der Felsfäuste benutzen die Schluchten, um ihre Ogerhorte zu verstecken.\n\nIch möchte, dass Ihr diese Truppen aufspürt und sie alle im Namen der Mag'har tötet.", sourceObjective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr 10 Krieger der Felsfäuste und 10 Magier der Felsfäuste tötet.", completion = "Wenn dies das Blut in ihren Adern nicht zum Gefrieren bringt, dann wird es nichts schaffen. Ihr habt den Mag'har zu Gerechtigkeit verholfen, {name}. Und für Gerechtigkeit zahlen die Mag'har gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[9908] = { id = 9908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abzeichen der Ehrenfeste" }
quests[9909] = { id = 9909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abzeichen von Thrallmar" }
quests[9910] = { id = 9910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standarten", description = "Wenn Ihr in die Ruinen der Brennenden Klinge reist, habe ich eine Aufgabe für Euch. Stellt diese Schlachtstandarten der Mag'har an drei verschiedenen Orten in der Ogersiedlung auf. Vorzugsweise Orte, an denen man sie gut sehen kann. Haltet nach den großen lodernden Scheiterhaufen in den oberen Bereichen Ausschau. Stellt eine Standarte neben dem ersten, zweiten und dritten Scheiterhaufen der Brennenden Klinge auf.\n\nDie Standarten werden einen bleibenden Eindruck bei den Ogern hinterlassen, die die Schlacht verpasst haben.", sourceObjective = "Mystiker Elakay'gan in Garadar in Nagrand möchte, dass Ihr eine Schlachtstandarte der Mag'har am ersten, zweiten und dritten Scheiterhaufen der Brennenden Klinge aufstellt. Bringt die übrigen Schlachtstandarten zurück, wenn Ihr fertig seid.", progress = "Ehrfurcht aus Angst! Das ist so gut wie jeder andere Grund.", completion = "Vielleicht wollt Ihr noch eine andere Aufgabe? Eine etwas heiklere?", sourceObjectiveStatus = "unverified-source-field" }
quests[9911] = { id = 9911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Graf der Marschen", description = "Dieses blutige Beißwerkzeug stammt von einem unglaublich großen Insekt. Der Netherrochen, zu dem es gehörte, war der größte, der je in den Zangarmarschen gesichtet wurde. Wenn man den Zustand der Beißwerkzeuge betrachtet, muss der Graf seine Nahrung von Aas auf frisches Fleisch umgestellt haben.\n\nDie Expedition des Cenarius wäre an einem solchen Objekt sicher sehr interessiert. Behüterin Leesa'oh hat ein kleines Lager im Westen des Quaggkamms.", sourceObjective = "Bringt \"Graf\" Ungulas Beißwerkzeug zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen.", progress = "<Die Behüterin blinzelt ein paar Mal überrascht.>\n\nWoher habt Ihr dieses... Ding?", completion = "Seid Ihr sicher, dass es echt ist? Ich meine, ich wusste schon, dass es riesige Kreaturen in den Marschen gibt, aber es gibt einen Unterschied zwischen riesigen Kreaturen und RIESIGEN Kreaturen.\n\nDa fällt mir ein, dass die Sporlinge einmal etwas von einem furchterregenden Netherrochen erzählt haben, der sie vor den Angriffen der Sumpflords bedroht hatte.\n\nWas ist, wenn diese Geschichten wahr sind? Oh je. Ich hebe das hier mal lieber auf. Die Expedition wird sicher davon erfahren wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9912] = { id = 9912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Expedition des Cenarius", description = "Die Hauptexpedition des Zirkels des Cenarius in der Scherbenwelt ist als Expedition des Cenarius bekannt. Sie fing als kleines Projekt unter der direkten Kontrolle des Zirkels an, aber inzwischen ist sie zu einer großen und ziemlich unabhängigen Organisation herangewachsen.\n\nDie Anführerin der Expedition, Ysiel Windsänger, hat uns gebeten, Freiwillige zur Zuflucht des Cenarius in den östlichen Zangarmarschen zu schicken. Nehmt den Pfad nach Westen und Ihr werdet direkt dorthin gelangen.", sourceObjective = "Sprecht mit Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.", completion = "Willkommen in der Zuflucht des Cenarius, {name}. Ich hoffe, Ihr könnt uns bei unserer Aufgabe behilflich sein. Wir haben viel Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[9913] = { id = 9913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Konsortium braucht Euch!", description = "Meine Organisation, das Konsortium, sucht nach talentierten Personen, wie Ihr es seid. Ihr werdet kaum ehrlichere und härter arbeitende Astrale als uns in dieser Gegend hier finden.\n\nAlles, was wir Verlangen ist Loyalität, Einsatz und ein vernünftiges Maß an moralischer Flexibilität. Wenn Ihr Interesse habt, sprecht mit Gezhe, unserem Anführer hier. Ihr findet ihn beim Aerissteg, nördlich des Oshu'guns.", sourceObjective = "Meldet Euch bei Gezhe beim Aerissteg in Nagrand.", completion = "Seid Ihr bereit für ein wenig Arbeit, {race}? Ich habe die perfekte Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9914] = { id = 9914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganzer Kopf voll Elfenbein", description = "Elfenbein ist ein heißbegehrtes Material. Ich habe Kunden von weither, die Schlange stehen, um es zu kaufen. Ich würde mich überreden lassen, meinen Gewinn mit Euch zu teilen.\n\nDie Stoßzähne der wilden Elekks in Nagrand haben genau die Qualität, die ich brauche. Bleibt jedoch von den Bullen fern, ihre Stoßzähne sind zu minderwertig.\n\nOh, und keine Sorge, das ist keine Wilderei, ich habe ein Abkommen mit den Orcs und den Draenei.\n\nAlso, sind wir uns einig?", sourceObjective = "Sammelt 3 Paar Elfenbeinstoßzähne und kehrt dann zu Shadrek beim Aerissteg in Nagrand zurück.", progress = "Ich brauche Elfenbein, keine Entschuldigungen. Wir können natürlich Euren Anteil am Gewinn neu verhandeln. Ich glaube aber kaum, dass Ihr mit dem Ergebnis zufrieden sein werdet.", completion = "Ich habe keine Sekunde an Euch gezweifelt, mein Freund. Die meisten hiervon sehen gut aus. Ein bisschen dreckig und verkratzt vielleicht. Aber ich denke, sie sind den Preis, den wir vereinbart hatten, wert.\n\nIch hoffe, das wir auch in Zukunft ins Geschäft kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9915] = { id = 9915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Elfenbein", progress = "Ich habe immer noch Bedarf an Elfenbeinstoßzähnen von den wilden Elekks in Nagrand. Unglücklicherweise kann ich es mir nicht mehr leisten, Euch dafür zu bezahlen. Wenn Ihr mir aber trotzdem weiter Stoßzähne bringt, werdet Ihr Euch beim Konsortium sehr beliebt machen.", completion = "Ausgezeichnet, noch mehr hochwertige Stoßzähne. Auch wenn ein paar davon etwas schäbig aussehen.\n\nIhr habt den Dank des Konsortiums, {name}." }
quests[9916] = { id = 9916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorratskisten des Blutenden Auges", description = "Die Felsfäuste haben die Vorräte, die sie aus unserem Dorf gestohlen haben, zu den Zwillingsschluchten von Nagrand gebracht, die sich westlich von hier im Halaanibecken befinden.\n\nWenn Ihr Euch dort aufhalten solltet, haltet Ausschau nach den Vorratskisten. Wenn wir sie zurückbekommen könnten, würde das die Last, die die Matronen von Garadar zu tragen haben, erheblich mindern.", sourceObjective = "Mystiker Elkay'gan in Garadar in Nagrand möchte, dass Ihr 10 Vorratskisten des Blutenden Auges wiederbesorgt.", progress = "Vielleicht können unserer Kinder eines Tages ohne Hunger leben.", completion = "Die meisten unserer Besitztümer wurden bei Angriffen zerstört oder gestohlen. Ich kann euch nicht viel bieten, aber hier sind ein paar Dinge, die Ihr vielleicht als nützlich empfinden könntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9917] = { id = 9917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann ich meinen Augen trauen?", description = "Kann ich meinen Augen trauen? Ist das da drüben tatsächlich eine Jagdgesellschaft von Ogern? Was treiben Oger denn so weit von Ihrem Hügel entfernt? Mir gefällt das gar nicht, <Fremder/Fremde>. Zuerst die Finsterblut und jetzt die Oger. Wir haben einfach nicht genug Leute, um mit all diesen Gefahren fertigzuwerden.\n\nKönntet Ihr die Ogersiedlung im Osten untersuchen? Ihr Lager ist etwa 200 Schritte östlich von hier. Wenn Ihr die Jäger der Felsfäuste seht, seid Ihr richtig. Tötet sie um an ihre Pläne zu kommen!", sourceObjective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr die Pläne der Felsfäuste besorgt.", progress = "Habt Ihr Neuigkeiten erfahren?", completion = "<Bintook liest die Pläne.>\n\nBEIM LICHT! Diese Handschrift ist grauenvoll! So wie ich das sehe, planen sie \"die blauen Häute zu essen und ihr Dorf einzunehmen\" oder einen Blaubeerkuchen zu backen. Es könnte wirklich beides heißen. Wir müssen der Sache auf den Grund gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9918] = { id = 9918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht solange ich hier wache!", description = "Die Schlachtpläne wurden von einem Leutnant der Oger geschrieben. Sein Name ist entweder Trocken oder Brocken.\n\n<Bintook dreht das Pergament und legt den Kopf schief.>\n\nEs könnte auch Billy sein.\n\nWie auch immer, ich denke, Ihr solltet dorthin zurückgehen und ein paar Takte mit Billy oder Trocken oder Brocken oder was weiß ich reden! Versucht diplomatisch zu sein. Wenn das nichts nützt, dann setzt eben etwas Muskelkraft ein.", sourceObjective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr mit Brocken sprecht. Kehrt zu Jägerin Bintook zurück, wenn Ihr die geforderten Informationen gesammelt habt.", completion = "Oh je, das war nur eine kleine Jagdgesellschaft? Ihr müsst Mo'mor erzählen, was Ihr herausgefunden habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9919] = { id = 9919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporeggar", description = "Ihr seid <ein sehr netter/eine sehr nette:r> {race}, {name}. Nicht wie die anderen, die ich getroffen habe.\n\nIhr solltet den Rest meines Volkes kennenlernen, sie wären Euch für Eure Hilfe sehr dankbar. Bringt diese Sporenbeutel zu meinem Anführer, Msshi'fn. Ihr findet ihn in Sporeggar, nördlich von hier.", sourceObjective = "Geht nach Sporeggar, nördlich vom Pilzgeflecht in den Zangarmarschen, und bringt die geborgenen Sporensäcke zu Msshi'fn.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet, {name}?", completion = "Ihr habt uns geholfen, die nächste Generation Sporlinge zu sichern, {race}. Das können wir Euch nur mit einem Willkommen in unserer Stadt vergelten. Bleibt doch ein wenig und lernt die anderen Sporlinge kennen. Sie werden viele Fragen an Euch haben, ich hoffe, das macht Euch nichts aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9920] = { id = 9920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo'mor der Brecher", description = "Ihr müsst sofort zu Mo'mor! Ihr könnt ihn in der Mitte von Telaar finden, beim Springbrunnen. Erzählt ihm genau, was der Oger Euch gesagt hat!", sourceObjective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr mit Mo'mor dem Brecher redet.", completion = "<Mo'mor schaut verdutzt drein.>\n\nEin neuer Ogerstamm drängt die Felsfäuste immer weiter nach Süden? Das klingt beunruhigend. Wir müssen mit der Situation in der Nähe unseres Zuhauses fertigwerden...", sourceObjectiveStatus = "unverified-source-field" }
quests[9921] = { id = 9921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen der Brennenden Klinge", description = "Die Jagdgesellschaften der Oger sind Vorboten für einen Angriff. Wir müssen sie schlagen, bevor sie eine Chance haben, genug Leute zu sammeln, um unsere Stadt einzunehmen.\n\nIhr werdet Euch wohl Eure Hände schmutzig machen müssen, {race}.\n\nDie größte Ansammlung von Felsfäusten in dieser Gegend befindet sich in den Ruinen der Brennenden Klinge, direkt im Osten von Telaar, an der Grenze zu Terokkar. Geht dort hin und zeigt den Felsfäusten, dass Telaar sich niemals ihrem Willen beugen wird!", sourceObjective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr 8 Zermalmer der Felsfäuste und 8 Mystiker der Felsfäuste tötet.", completion = "Ausgezeichnet. Konntet Ihr diesen Lantresor, der in dem Brief dieses Dummkopfs erwähnt wurde, ausfindig machen?\n\nEgal, wir müssen weitermachen. Ich habe Berichte über weitere Ogeraktivitäten erhalten, um die sich sofort jemand kümmern muss!", sourceObjectiveStatus = "unverified-source-field" }
quests[9922] = { id = 9922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zwillingsschluchten von Nagrand", description = "Ihr habt eine gute Arbeit geleistet, {name}. Seid Ihr bereit für noch mehr davon?\n\nIch habe Berichte über eine große Ansammlung von Felsfäusten in den zwei Schluchten von Nagrand, nordwestlich von hier im Halaanibecken.\n\nBegebt Euch zu den Schluchten und werdet mit den übrig gebliebenen Felsfäusten fertig.", sourceObjective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr 10 Krieger der Felsfäuste und 10 Magier der Felsfäuste tötet.", completion = "Ausgezeichnete Arbeit! Ich stelle im Augenblick Nachforschungen über den Totschlägerstamm an, den der Leutnant der Felsfäuste erwähnt hat. Jetzt müssen die Aufgaben, die Ihr erledigt habt, getestet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9923] = { id = 9923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HILFE!", description = "HILFE! Sie werden mich fressen! Ich weiß es!\n\nFindet den Schlüssel, einer dieser Oger muss ihn haben.\n\nWenn Ihr mir hier raushelft, wird mein Vater Euch fürstlich entlohnen! Er ist der Anführer von Telaar, Arechron.", sourceObjective = "Findet den Schlüssel der Felsfäuste und befreit Corki. Sprecht mit Arechron in Telaar, wenn Ihr Erfolg hattet.", completion = "Es tut mir wirklich sehr leid, {race}. Er gerät immer in Schwierigkeiten. Manchmal wünschte ich, ich könnte ihn anleinen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9924] = { id = 9924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corki wird schon wieder vermisst!", description = "<Arechron seufzt.>\n\nDas ist mir so peinlich. Erinnert Ihr Euch noch an meinen Sohn Corki? Ihr habt ihn vor Kurzem aus den Ruinen der Brennenden Klinge gerettet. Nun ja, seine Neugier hat ihn mal wieder gepackt. Er sagte, er wolle die Felsfaustbedrohung für Onkel Mo'mor untersuchen, und ist zu den Ogerhügeln im Halaanibecken gerannt, nördlich von hier.\n\nKönntet Ihr ihn vielleicht für mich ausfindig machen? Ich wäre Euch ewig dankbar.", sourceObjective = "Arechron in Telaar bittet Euch, Corki zu suchen und zu befreien.", completion = "Ich bin Euch so dankbar, {name}. Seine Mutter wird sich in Zukunft um ihn kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9925] = { id = 9925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Sicherheit", description = "Gezhe hat beschlossen, unsere Operation so nahe wie möglich am Oshu'gun zu postieren, ohne dabei einen Gedanken an die Sicherheit der Gruppe zu verschwenden. Warum? Weil er eine Erhöhung unserer Produktivität um zehn Prozent vorausgesehen hat, wenn er uns hier anstatt in den Bergen im Süden ansiedelt.\n\nUngeachtet der durchgedrehten Ausgeburten der Leere, die sich gerade mal 10 Fuß von uns weg aufhalten. Aber das ist das Problem des Sicherheitsoffiziers, nicht Gezhes.\n\nTötet ein paar dieser Ausgeburten für mich, und ich gebe Euch ein Zehntel meines Sicherheitsetats. Freut Euch nicht zu früh, viel Geld steht mir nicht zur Verfügung.", sourceObjective = "Zerid beim Aerissteg in Nagrand möchte, dass Ihr 8 Ausgeburten der Leere in der Nähe des Oshu'gun tötet.", completion = "Ihr zaubert ein Lächeln auf mein Gesicht, {name}. Zumindest würdet Ihr das, wenn ich noch ein Gesicht hätte.\n\nWenn Ihr so weiter macht werden wir noch beste Freunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9926] = { id = 9926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG Shadow Council/Warmaul Questline" }
quests[9927] = { id = 9927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbarmungslose Gerissenheit", description = "<Lantresor reicht Euch einen Stapel Banner.>\n\nDies sind die Ogerbanner der Totschläger, die ich kürzlich erworben habe.\n\nIch möchte, dass Ihr zur Festung Kil'sorge im Süden reist und so viele wie möglich von diesem Abschaum von Kil'sorge tötet, wie Ihr nur könnt. Rammt ein Totschlägerbanner durch das Herz jedes gefallen Soldaten von Kil'sorge. Kehrt zu mir zurück wenn Ihr diese und die beiden anderen Aufgaben, die zu meinem Plan gehören, erledigt habt.", sourceObjective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge möchte, dass Ihr 10 Ogerbanner der Totschläger in die Körper von Bewohnern von Kil'sorge in der Festung Kil'sorge rammt.\n\nBringt unbenutzte Ogerbanner der Totschläger zu ihm zurück.", progress = "<Lantresor schaut Euch entgeistert an.>\n\nSchon fertig?", completion = "Könnt Ihr Euch vorstellen, wie verwirrt sie darüber sein werden, {race}? Das wird wundervoll.", sourceObjectiveStatus = "unverified-source-field" }
quests[9928] = { id = 9928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen zur Täuschung", description = "Wenn mein Plan gelingen soll, müsst Ihr ein paar Waffen von Kil'sorge in der Festung Kil'sorge stehlen.\n\nDurchsucht die Festung nach Kisten mit Waffen von Kil'sorge. Bringt mir alle, die Ihr finden könnt.\n\nDie Festung Kil'sorge liegt im Süden, etwas westlich von den Ruinen der Brennenden Klinge.", sourceObjective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge Nagrand möchte, dass Ihr 10 Waffen von Kil'sorge besorgt.", progress = "Wir werden einen nie dagewesenen Hass zwischen den beiden Klans säen!", completion = "Ausgezeichnet! Unser nächstes Ziel sind die Ruinen des Lachenden Schädels.", sourceObjectiveStatus = "unverified-source-field" }
quests[9929] = { id = 9929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Händler", description = "Ich nehme an, Ihr seid noch nicht lange genug hier um Dugar zu kennen, oder? Er ist ein Händler mit Kontakten zu den verschiedenen Fraktionen hier in Shattrath.\n\nFragt mich nicht, wie er das anstellt, aber er schafft es, mit ihnen Waren zu handeln, an die nicht einmal der Rüstmeister kommt!\n\nEr ist vor drei Tagen aus Shattrath losgezogen und noch nicht zurückgekehrt. Normalerweise schafft er seine Runde in viel kürzerer Zeit. Wenn Ihr in den Wald reist, haltet Ihr dann ein Auge nach ihm offen?", sourceObjective = "Reist nach Nordwesten entlang der Straße nach Shattrath und sucht nach Hinweisen auf den Verbleib von Dugar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9930] = { id = 9930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Händler", description = "Ich nehme an, Ihr seid noch nicht lange genug hier um Deirom zu kennen, oder? Er ist ein Händler mit Kontakten zu den verschiedenen Fraktionen hier in Shattrath.\n\nFragt mich nicht, wie er das anstellt, aber er schafft es, mit ihnen Waren zu handeln, an die nicht einmal der Rüstmeister kommt!\n\nEr ist vor drei Tagen aus Shattrath losgezogen und noch nicht zurückgekehrt. Normalerweise schafft er seine Runde in viel kürzerer Zeit. Wenn Ihr in den Wald reist, haltet Ihr dann ein Auge nach ihm offen? Meldet Euch bei Thander, wenn Ihr etwas herausfindet.", sourceObjective = "Reist nach Nordwesten entlang der Straße nach Shattrath und sucht nach Hinweisen auf den Verbleib von Deirom.", sourceObjectiveStatus = "unverified-source-field" }
quests[9931] = { id = 9931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich für den Gefallen revanchieren", description = "Nun müsst Ihr den Wunsch nach Krieg in den fetten, nutzlosen Köpfen der Totschläger wecken. Im Nordwesten, bei den Bergen, findet Ihr die Ruinen des Lachenden Schädels.\n\n<Lantresor zeigt auf die Kiste mit den Waffen, die Ihr ihm gebracht habt.>\n\nErkennt Ihr diese Banner? Es sind Banner von Kil'sorge. Ich möchte, dass Ihr einen Stapel Banner von Kil'sorge nehmt und sie in die Leichen der Totschlägeroger rammt. Denkt daran, Ihr findet sie im Nordwesten.", sourceObjective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr 10 Banner von Kil'sorge in die Leichen der Totschlägeroger in den Ruinen des Lachenden Schädels rammt.\n\nBringt unbenutzte Banner von Kil'sorge zu ihm zurück.", progress = "Könnt Ihr vorhersehen, was als Nächstes geschieht?", completion = "Der Plan ist perfekt, {name}. Ich sehe jetzt schon die Früchte unserer Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9932] = { id = 9932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweismaterial", description = "Euer Angriff auf die Festung Kil'sorge hat uns eine ganz besondere Möglichkeit eröffnet. Wir haben genügend Leichen, um es so aussehen zu lassen, als hätte eine große Schlacht stattgefunden.\n\nReist zu den Ruinen des Lachenden Schädels und sucht den Hof des Lachenden Schädels. Dort solltet Ihr einen brennenden Scheiterhaufen finden. Vergewissert Euch, dass die Gegend sicher ist, und benutzt diese Decke, um Rauchzeichen zu senden. Wenn meine Oger den Rauch sehen, werden sie sich einschleichen und die Leichen der toten Soldaten von Kil'sorge dort platzieren.\n\nDas sollte unser letzter Streich sein.", sourceObjective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr die feuchte Wolldecke am lodernden Scheiterhaufen der Totschläger im Hof des Lachenden Schädels benutzt, um Signale an seine Oger zu senden.", progress = "Wisst Ihr nun, warum Ihr nie einen Krieg gegen mich gewinnen würdet?", completion = "Ich muss zugeben, dass ich mich seit Jahrzehnten nicht mehr so lebendig gefühlt habe. Ihr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9933] = { id = 9933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Telaar", description = "<Lantresor zeigt auf eine unbeschriftete Kiste.>\n\nNehmt dies. Es ist mein Geschenk an Euer Volk. Ihr habt meinen Klan eigenhändig vor der Ausrottung bewahrt.\n\nIhr könnt Eurem Anführer sagen, dass Lantresor von der Brennenden Klinge und seine Felsfäuste das Friedensangebot annehmen.\n\n<Lantresor verneigt sich.>", sourceObjective = "Bringt das Friedensangebot der Brennenden Klinge zu Arechron nach Telaar in Nagrand.", progress = "Frieden sagt Ihr?", completion = "Bitte, {name}, nehmt Euch von diesem Friedensangebot was immer Ihr möchtet. Schließlich wäre dies ohne Eure Hilfe niemals möglich gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9934] = { id = 9934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Garadar", description = "<Lantresor zeigt auf eine unbeschriftete Kiste.>\n\nNehmt dies. Es ist mein Geschenk an Euer Volk. Ihr habt meinen Klan eigenhändig vor der Ausrottung bewahrt.\n\nIhr könnt Eurem Anführer sagen, dass Lantresor von der Brennenden Klinge und seine Felsfäuste das Friedensangebot annehmen.\n\n<Lantresor verneigt sich.>", sourceObjective = "Bringt das Friedensangebot der Brennenden Klinge zu Garrosh in Garadar.", progress = "<Garrosh scheint von dem Angebot unbeeindruckt zu sein.>", completion = "<Garrosh tritt die Kiste um.>\n\nIhr verschwendet Eure Zeit, {race}. Nehmt Euch aus der Kiste was immer Ihr wollt. Weder ich noch Garadar haben für diesen unnützen Tand Verwendung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9935] = { id = 9935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Giselda die Alte", description = "Gesucht: Tot oder lebendig\n\nGiselda die Alte von Kil'sorge und ihre Lakaien wegen Mord, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.\n\nAufenthaltsort in der Festung Kil'sorge im Südosten von Nagrand, an der Grenze zu Terokkar.\n\nEine hohe Belohnung in Gold wird von Aufseher Bullrok in Garadar an denjenigen ausgezahlt, der Giselda ihre gerechte Strafe zukommen lässt.", sourceObjective = "Tötet Giselda die Alte und 10 beliebige Agenten von Kil'sorge. Kehrt danach zu Aufseher Bullrok in Garadar zurück.", completion = "Die Alte ist tot! Das sind wundervolle Nachrichten, {name}. Hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9936] = { id = 9936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Giselda die Alte", description = "Gesucht: Tot oder lebendig\n\nGiselda die Alte von Kil'sorge und ihre Lakaien wegen Mord, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.\n\nAufenthaltsort in der Festung Kil'sorge im Südosten von Nagrand, an der Grenze zu Terokkar.\n\nEine hohe Belohnung in Gold wird von Aufseher Moi'bff Jill in Telaar an denjenigen ausgezahlt, der Giselda ihre gerechte Strafe zukommen lässt.", sourceObjective = "Tötet Giselda die Alte und 10 beliebige Agenten von Kil'sorge. Kehrt danach zu Aufseher Moi'bff Jill in Telaar zurück.", completion = "Die Alte ist tot! Das sind wundervolle Nachrichten, {name}. Hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9937] = { id = 9937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Durn der Nimmersatte", description = "Ihr habt eine der beiden größten Bedrohungen in Nagrand vernichtet, {name}. Seid Ihr nun bereit für die Geißel der Geisterfelder?\n\nDurn der Nimmersatte regiert über das Gebiet beim Oshu'gun und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, Nagrand von diesem blutrünstigen Gronn zu befreien. Reist zu den Geisterfeldern, weit im Südwesten von hier, und findet Durn. Tötet ihn und ich verspreche Euch eine Belohnung, die der Schwierigkeit dieser Aufgabe angemessen ist.", sourceObjective = "Tötet Durn den Nimmersatten. Meldet Euch bei Aufseher Bullrok, wenn Ihr diese Aufgabe erledigt habt.", completion = "Durns tödlicher Griff wurde gelöst! Nagrand schaut Dank Euch auf eine bessere Zukunft, Held. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9938] = { id = 9938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Durn der Nimmersatte", description = "Ihr habt eine der beiden größten Bedrohungen in Nagrand vernichtet, {name}. Seid Ihr nun bereit für die Geißel der Geisterfelder?\n\nDurn der Nimmersatte regiert über das Gebiet beim Oshu'gun und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, Nagrand von diesem blutrünstigen Gronn zu befreien. Reist zu den Geisterfeldern, weit im Südwesten von hier, und findet Durn. Tötet ihn und ich verspreche Euch eine Belohnung, die der Schwierigkeit dieser Aufgabe angemessen ist.", sourceObjective = "Tötet Durn den Nimmersatten. Meldet Euch bei Aufseher Moi'bff Jill, wenn Ihr diese Aufgabe erledigt habt.", completion = "Durns tödlicher Griff wurde gelöst! Nagrand schaut Dank Euch auf eine bessere Zukunft, Held. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9939] = { id = 9939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Zorbo der Berater", description = "Gesucht: tot oder lebendig\n\nZorbo der Berater, gesucht für mehrere geplante Angriffe auf Garadar. Zusammen mit seinen Häschern und Schamanen hat Zorbo unzählige Orcs getötet. Zorbo ist als bewaffnet, gefährlich und erbarmungslos einzustufen.\n\nSein Zuhause befindet sich in den Ruinen des Lachenden Schädels in den nördlichen Bergen von Nagrand.\n\nDie Belohnung für den Tod oder die Gefangennahme von Zorbo dem Berater wird von Aufseher Bullrok in Garadar ausbezahlt.", sourceObjective = "Tötet Zorbo den Berater, 5 Schamanen der Totschläger und 5 Häscher der Totschläger. Meldet Euch bei Aufseher Bullrok, wenn Ihr die Aufgabe erledigt habt.", completion = "Dies ist ein großer Sieg für die Bewohner von Garadar! Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9940] = { id = 9940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Zorbo der Berater", description = "Gesucht: tot oder lebendig\n\nZorbo der Berater, gesucht für mehrere geplante Angriffe auf Telaar. Zusammen mit seinen Häschern und Schamanen hat Zorbo unzählige Zerschlagene getötet. Zorbo ist als bewaffnet, gefährlich und erbarmungslos einzustufen.\n\nSein Zuhause befindet sich in den Ruinen des Lachenden Schädels in den nördlichen Bergen von Nagrand.\n\nDie Belohnung für den Tod oder die Gefangennahme von Zorbo dem Berater wird von Aufseher Moi'bff Jill in Telaar ausbezahlt.", sourceObjective = "Tötet Zorbo den Berater, 5 Schamanen der Totschläger und 5 Häscher der Totschläger. Meldet Euch bei Aufseher Moi'bff Jill, wenn Ihr die Aufgabe erledigt habt.", completion = "Dies ist ein großer Sieg für die Bewohner von Telaar! Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9941] = { id = 9941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schuldigen aufspüren", description = "Die Arakkoaspuren, bei denen auch ein paar flache Furchen zu erkennen sind, führen nach Norden über die Straße hinweg. Es sieht aus, als hätten die Arakkoa etwas vom Schlachtfeld weggeschleift, vielleicht zu einer Siedlung in der Nähe.\n\nAuch wenn ein kaputter Wagen auf einen Kampf hinweist, sind keine Hinweise auf Deiroms Schicksal erkennbar. Folgt den Arakkoaspuren nach Norden und sucht weiter nach dem Händler. Wenn er lebend gefangen wurde, besteht vielleicht immer noch die Chance, ihn zu retten.", sourceObjective = "Sucht weiter in der Arakkoasiedlung nördlich des kaputten Wagens nach einem Lebenszeichen von Deirom.", sourceObjectiveStatus = "unverified-source-field" }
quests[9942] = { id = 9942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schuldigen aufspüren", description = "Die Arakkoaspuren, bei denen auch ein paar flache Furchen zu erkennen sind, führen nach Norden über die Straße hinweg. Es sieht aus, als hätten die Arakkoa etwas vom Schlachtfeld weggeschleift, vielleicht zu einer Siedlung in der Nähe.\n\nAuch wenn ein kaputter Wagen auf einen Kampf hinweist, sind keine Hinweise auf Dugars Schicksal erkennbar. Folgt den Arakkoaspuren nach Norden und sucht weiter nach dem Händler. Wenn er lebend gefangen wurde, besteht vielleicht immer noch die Chance, ihn zu retten.", sourceObjective = "Sucht weiter in der Arakkoasiedlung nördlich des kaputten Wagens nach einem Lebenszeichen von Dugar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9943] = { id = 9943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Thander", description = "Deiroms Ladung scheint nicht beschädigt oder geöffnet worden zu sein. Die Ladung hat wohl ihr Interesse geweckt, doch der Gefangene scheint ihnen wichtiger gewesen zu sein. Was die Arakkoa sich von dem Angriff und der Entführung Deiroms erhofft haben, bleibt unklar, aber hier wird der Händler sicher nicht gefangengehalten.\n\nDa Ihr keine Ahnung habt, wo Ihr die Suche fortsetzen sollt, beschließt Ihr, dass es an der Zeit ist, Thander Eure Entdeckungen mitzuteilen.", sourceObjective = "Kehrt mit Euren neuen Erkenntnissen zu Thander in Allerias Feste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9944] = { id = 9944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene mag'harische Prozession", description = "Großmutter sagt, dass wir durchhalten und unserem Volk dienen müssen. Sie sagt, dass wir Garrosh als Beispiel dienen müssen, zeigen, dass das Leben weitergeht.\n\nIch muss mich um so viele Dinge hier kümmern, besonders seit Großmutter krank ist. Würdet Ihr den Mag'har eine Gefallen tun, indem Ihr einer ihrer Matronen helft?\n\nVor ein paar Tagen haben wir einen Begräbniszug zum Ahnengrund geschickt, der noch nicht zurückgekehrt ist. Würdet Ihr nach ihnen suchen? Sie haben die westliche Straße aus Garadar hinaus genommen. Folgt ihr und meidet Halaa.", sourceObjective = "Sucht nach der verschollenen mag'harischen Prozession.", completion = "Dreißig Orcs, {race}! Von diesen dreißig sind nur noch Ungriz und ich übrig. Wir haben den jungen Orc, Saurfang, halb tot in der Nähe von Sonnenwind gefunden. Offensichtlich ist er aus einem anderen Grund hier...", sourceObjectiveStatus = "unverified-source-field" }
quests[9945] = { id = 9945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg den Totschlägern", description = "Wir waren auf dem Weg zum Ahnengrund, als wir in einen Hinterhalt der Totschläger geraten sind. Sie kamen von allen Seiten, haben viele der Wächter der Prozession getötet und auch viele andere. Sie haben sogar die Überreste des Ältesten im Wagen geschändet.\n\nUnd warum? Um uns zu erniedrigen und ihre Macht zu beweisen. Nicht einmal die Felsfäuste hätten sich zu so etwas herabgelassen.\n\nIch habe mich dem spirituellen Weg verschrieben, {name}, aber auch ich kenne Grenzen. Sucht die Angreifer im Totschlägerhügel im Nordwesten und vernichtet sie!", sourceObjective = "Ältester Yorley bei der mag'harischen Prozession in Nagrand möchte, dass Ihr 8 Schläger der Totschläger und 8 Hexenmeister der Totschläger tötet.", completion = "Das ist ein guter Anfang, aber ihr Anführer muss getötet werden, damit Eure Taten auch langfristige Erfolge erzielen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9946] = { id = 9946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cho'war der Plünderer", description = "Habt Ihr je einen Ogerkönig gesehen, {race}? Nur wenige haben es überlebt und können davon erzählen. Unglücklicherweise haben wir es genau jetzt mit einem zu tun.\n\nDer Anführer dieser Barbaren ist ein Oger namens Cho'war. Gerüchten zufolge soll er die Gronn aus den Höhlen vertrieben haben. Danach hat sich Cho'war selbst zum König ernannt und die Ogerklans, die unter den Gronn gedient haben, aufgelöst. So entstanden die Totschläger.\n\nSucht tief in den Höhlen des Totschlägerhügels nach Cho'war. Tötet ihn und bringt mir seinen Kopf.", sourceObjective = "Ältester Yorley bei der mag'harischen Prozession in Nagrand möchte, dass Ihr Cho'war den Plünderer tötet und Cho'wars Kopf besorgt.", progress = "Er ist sicher sehr schwer bewacht.", completion = "Diesen Kopf stellen wir an dem Toren von Garadar auf, damit alle ihn sehen können. Die Oger werden es sich zweimal überlegen, bevor sie heilige Rituale der Mag'har stören.", sourceObjectiveStatus = "unverified-source-field" }
quests[9947] = { id = 9947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Rokag", description = "Dugars Ladung scheint nicht beschädigt oder geöffnet worden zu sein. Die Ladung hat wohl ihr Interesse geweckt, doch der Gefangene scheint ihnen wichtiger gewesen zu sein. Was die Arakkoa sich von dem Angriff und der Entführung Deiroms erhofft haben, bleibt unklar, aber hier wird der Händler sicher nicht gefangengehalten.\n\nDa Ihr keine Ahnung habt, wo Ihr die Suche fortsetzen sollt, beschließt Ihr, dass es an der Zeit ist, Rokag Eure Entdeckungen mitzuteilen.", sourceObjective = "Kehrt mit Euren neuen Erkenntnissen zu Rokag in der Steinbrecherfeste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9948] = { id = 9948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet die Überlebenden", description = "Wenn ich etwas über Oger weiß, dann dass sie Ihr Essen frisch mögen. Das bedeutet, dass die Mag'har, die sie gefangen haben, wahrscheinlich am Leben gehalten werden, bis sie verspeist werden sollen. Ich weiß, das ist ein grausamer Gedanke, aber wir müssen das zu unserem Vorteil ausnutzen.\n\nGeht zum Totschlägerhügel und sucht nach gefangenen Mag'har. Wenn Ihr Gefangene gefunden habt, holt Euch die Schlüssel von den Totschlägern in der Nähe.\n\nTötet die Oger, um an die Schlüssel zu gelangen, und befreit die Gefangenen.", sourceObjective = "Ältester Ungriz bei der mag'harischen Prozession in Nagrand möchte, dass Ihr 5 gefangene Mag'har befreit.", completion = "Ihr habt geschafft, was keiner für möglich hielt und unsere vermissten Brüder und Schwestern zurückgebracht. Für die Mag'har seid Ihr ein Held, {name}. Alle werden Euren Namen kennen und wissen, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9949] = { id = 9949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Vogelperspektive", description = "Ohne weitere Informationen sind wir in einer schwierigen Lage. Ich werde die Suche nach Deirom nicht aufgeben. Seine Entführung war kein Zufall, {name}.\n\nDie Arakkoa planen etwas, aber was?\n\nAndarl im Magierturm kennt sich ein wenig mit ihrer besonderen Magie aus. Mit den richtigen Werkzeugen kann er uns neue Informationen besorgen. Er benötigt die Augenkristalle der Arakkoadörfer nördlich der Knochenwüste - dem Skithversteck, dem Reskkversetck und dem Shienorversteck.", sourceObjective = "Bringt das Auge des Sktihverstecks, das Auge des Shienorverstecks und das Auge des Reskkverstecks zu Andarl in Allerias Feste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9950] = { id = 9950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Vogelperspektive", description = "Ohne weitere Informationen sind wir in einer schwierigen Lage. Ich werde die Suche nach Dugar nicht aufgeben. Seine Entführung war kein Zufall, {name}.\n\nDie Arakkoa planen etwas, aber was?\n\nKurgatok der Hexenmeister kennt sich ein wenig mit ihrer besonderen Magie aus. Mit den richtigen Werkzeugen kann er uns neue Informationen besorgen. Er benötigt die Augenkristalle der Arakkoadörfer nördlich der Knochenwüste - dem Skithversteck, dem Reskkversetck und dem Shienorversteck.", sourceObjective = "Bringt das Auge des Sktihverstecks, das Auge des Shienorverstecks und das Auge des Reskkverstecks zu Krugatok in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9951] = { id = 9951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es beobachtet Euch!", description = "Schnell, versteckt Euch! Naphthal'ars Auge beobachtet Euch... uns alle!\n\nIch traue mich nicht, auf die Spitze des Turms zu gehen, um mit ihm zu sprechen, aber Ihr... Ihr seht aus, als könntet Ihr die richtigen Worte finden. Aber seid vorsichtig, es mag keine Witze und kann Dummköpfe nicht leiden.\n\nÜberredet es, auf eine Tasse Tee hinunterzukommen. Aber bitte sorgt dafür, dass es mich nicht mehr anstarrt!", sourceObjective = "Tötet Naphthal'ar und kehrt dann zu Aufseher Baumlas im Cenariusdickicht in den Wäldern von Terokkar zurück.", completion = "Es ist besser so. Wenn es keine zivilisierte Einladung annehmen kann, dann ist es das auch nicht wert.\n\n<Aufseher Baumlas schaut Euch kurz verwirrt an.>\n\nWer seid Ihr und was wollt Ihr hier? Ihr müsst von hier verschwinden, bevor es zu spät ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[9952] = { id = 9952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabungsleiter Balmoral", description = "Andarl ist also sicher, dass Deirom im Shalasversteck gefangengehalten wird? Das ist die größte Arakkoasiedlung, die wir kennen.\n\nDas Shalasversteck liegt weit im Süden der Wälder, nahe bei der östlichen Grenze der Knochenwüste. Ich weiß leider nicht sehr viel darüber, aber dort unten gibt es ein Lager eines Mitglieds der Forscherliga, der Euch vielleicht weiterhelfen kann. Ausgrabungsleiter Balmorals Lager befindet sich am äußersten Rand des Landes südwestlich vom Shalasversteck. Befragt ihn zunächst, bevor Ihr etwas gegen die Arakkoa unternehmt.", sourceObjective = "Findet und sprecht mit Ausgrabungsleiter Balmoral.", sourceObjectiveStatus = "unverified-source-field" }
quests[9953] = { id = 9953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufklärer Nodak", description = "Kurgatok ist also sicher, dass Dugar im Shalasversteck gefangengehalten wird? Das ist die größte Arakkoasiedlung, die wir kennen.\n\nDas Shalasversteck liegt weit im Süden der Wälder, nahe bei der östlichen Grenze der Knochenwüste. Ich weiß leider nicht sehr viel darüber, aber einer unserer Späher hat dort unten sein Lager. Vielleicht kann er Euch weiterhelfen. Aufklärer Nodaks Lager befindet sich am äußersten Rand des Landes südwestlich vom Shalasversteck. Befragt ihn zunächst, bevor Ihr etwas gegen die Arakkoa unternehmt.", sourceObjective = "Findet und sprecht mit Aufklärer Nodak.", sourceObjectiveStatus = "unverified-source-field" }
quests[9954] = { id = 9954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corkis Lösegeld", description = "<Arechron zeigt Euch einen rußverschmierten Brief.>\n\nIch habe gerade diesen Brief erhalten. Er ist von einem Ogerstamm, die sich selbst Totschläger nennen. Sie herrschen über die nordwestlichen Gebiete von Nagrand. Hier steht, dass sie Corki in ihrer Gewalt haben, und sie drohen ihn aufzufressen, wenn wir nicht kooperieren. Nunja, Corki ist ein Dummkopf, aber er gehört zur Familie. Würdet Ihr ihn retten, {name}?\n\nIch nehme an, dass er in einem Käfig auf dem Totschlägerhügel eingesperrt ist. Dort solltet Ihr zuerst nachsehen.", sourceObjective = "Arechron möchte, dass Ihr Corki auf dem Totschlägerhügel findet.", completion = "Diesmal haben sie mich gut eingesperrt, {name}. Der König der Totschläger, Cho'war, hat den Schlüssel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9955] = { id = 9955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cho'war der Plünderer", description = "Sie nennen ihn Cho'war den Plünderer, {name}. Er ist der Oger, der die Gronn, die über die Oger geherrscht hatten, vertrieben hat. Ihr könnt mir ruhig glauben, dass er mächtig ist!\n\nDer Chef hat gesagt, dass Cho'war in der großen Höhle wohnt - wo immer das auch sein mag... Besorgt diesen Schlüssel und holt mich hier raus! Wenn wir das hier überleben, wird mein Vater Euch sicher reich belohnen! Geht zu ihm sobald ich frei bin.", sourceObjective = "Corki möchte, dass Ihr Cho'wars Schlüssel besorgt, um ihn aus dem Käfig zu befreien. Kehrt zu Arechron in Telaar zurück, falls Ihr Erfolg haben solltet.", completion = "Danke, {name}. Ich habe Corki zu den Nachtelfen im Schergrat geschickt. Hoffentlich gelingt es ihnen, ihn vom Ärger fern zu halten.\n\nWegen der Belohnung...", sourceObjectiveStatus = "unverified-source-field" }
quests[9956] = { id = 9956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überfallene Karawane", description = "Ich war bei einer Karawane dabei, die Vorräte zur Oreborzuflucht in den Zangarmarschen bringen sollte. An der Grenze zu den Marschen wurden wir jedoch von einer hinterlistigen Truppe von Totschlägerogern überfallen. Sie haben die anderen getötet und mich sowie all unsere Vorräte beschlagnahmt.\n\nZum Glück haben sie vergessen, meinen Käfig zu verriegeln. Als sie eingeschlafen waren, bin ich geflohen.\n\nEs ist zwar zu spät für meine Kameraden, aber wir könnten die gestohlenen Vorräte wirklich gebrauchen. Den Totschlägerhügel findet Ihr in den nordwestlichen Bergen von Nagrand.", sourceObjective = "Jägerin Kima in Telaar in Nagrand möchte, dass Ihr 10 Vorratskisten von Telaar wiederbesorgt.", progress = "Ich komme mir so dumm vor. Archerons Sohn, Corki, hat mich gefragt, was los ist, und ich habe es ihm gesagt. Jetzt ist er schon wieder verschwunden!", completion = "Erstaunlich! Wie habt Ihr es geschafft, all das alleine zurückzutragen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9957] = { id = 9957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los mit dem Cenariusdickicht?", description = "Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts in den Wäldern von Terokkar gehört.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Es gibt viele Wege dorthin, aber der kürzeste führt den Weg nach Süden entlang. Biegt die Straße nach Osten von Shattrath ab, wenn Ihr im Wald seid.", sourceObjective = "Sprecht mit einem der Druiden beim Cenariusdickicht in den Wäldern von Terokkar.", completion = "Ich bin froh, dass die Zuflucht Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9958] = { id = 9958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung ausspähen", description = "Seit ich hier bin habe ich schon öfter mit den Arakkoa zu tun gehabt, und das war alles andere als freundlich. Sie scheinen sehr ortsgebunden zu sein, aber das sind wir ja auch, oder?\n\nDie Arakkoa verfügen über eine Art ursprüngliche Magie, die in Azeroth völlig unbekannt ist. Mit ihrer Hilfe haben sie die magische Verteidigung des Shalasverstecks gewirkt. Bevor wir gegen sie vorgehen können, wäre es klug, diese Verteidigungseinrichtungen zunächst auszuspähen, damit wir wissen, wogegen wir ankommen müssen.", sourceObjective = "Begebt Euch in die Nähe des Shalasverstecks und beobachtet die Verteidigungseinrichtungen des Dorfes.", sourceObjectiveStatus = "unverified-source-field" }
quests[9959] = { id = 9959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung ausspähen", description = "Seit ich hier bin habe ich schon öfter mit den Arakkoa zu tun gehabt, und das war alles andere als freundlich. Sie scheinen sehr ortsgebunden zu sein, aber das sind wir ja auch, oder?\n\nDie Arakkoa verfügen über eine Art ursprüngliche Magie, die in Azeroth völlig unbekannt ist. Mit ihrer Hilfe haben sie die magische Verteidigung des Shalasverstecks gewirkt. Bevor wir gegen sie vorgehen können, wäre es klug, diese Verteidigungseinrichtungen zunächst auszuspähen, damit wir wissen, wogegen wir ankommen müssen.", sourceObjective = "Begebt Euch in die Nähe des Shalasverstecks und beobachtet die Verteidigungseinrichtungen des Dorfes.", sourceObjectiveStatus = "unverified-source-field" }
quests[9960] = { id = 9960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los mit dem Cenariusdickicht?", description = "Hey Ihr da, {class}! Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts gehört.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Ihr findet es, wenn Ihr Richtung Nordwesten durch den Wald geht.", sourceObjective = "Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.", completion = "Ich bin froh, dass die Steinbrecherfeste Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9961] = { id = 9961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los mit dem Cenariusdickicht?", description = "{class}, ich habe eine eilige Aufgabe für Euch. Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts gehört. Das ist sehr merkwürdig, da sie sich normalerweise alle paar Tage bei uns melden.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Ihr findet es, wenn Ihr Richtung Nordwesten durch den Wald geht.", sourceObjective = "Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.", completion = "Ich bin froh, dass Allerias Feste Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9962] = { id = 9962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Schmetterzehe", description = "Seid Ihr bereit für den ersten Kampf? Wenn Ihr so weit seid, gebt mir Bescheid und ich bringe die Dinge ins Rollen. Ihr müsst nur im Ring des Blutes auf Euren ersten Gegner warten.\n\nEuer erster Herausforderer wird Schmetterzehe sein, ein grausamer Grollhuf.\n\nViel Glück! Ich hoffe, Ihr habt ein paar Freunde mitgebracht.\n\nUnd denkt daran, der Kampf ist erst zu Ende, wenn Ihr oder Euer Gegner mit dem Gesicht nach unten auf dem Boden liegt.", sourceObjective = "Besiegt Schmetterzehe. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Hm, nicht schlecht. Gar nicht schlecht... Ihr habt Potenzial, Kleiner. Hier habt Ihr etwas Gold für Eure Taschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9963] = { id = 9963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe von der Geißel", description = "Die Schutzzauber, die Ihr bemerkt habt, sind tatsächlich sehr starke Magie. Die Fertigkeiten der Arakkoa entziehen sich unserem Verständnis, weswegen wir nur hoffen können, dass wir mit ihrer Hilfe einen Gegenzauber finden können.\n\nIch weiß, was Ihr denkt. Warum sollte der Feind uns helfen wollen, seine Verteidigung zu durchbrechen? Die Antwort ist natürlich, dass er das nicht will. Habt Ihr die Geschichten über den verrückten alten Arakkoa namens Kokorek gehört? Man sagt, er hielte sich im Lithicversteck am westlichen Ende der Knochenwüste auf und warte auf die Rückkehr längst vergangener Zeiten.", sourceObjective = "Sucht Kokorek im Lithicversteck und sprecht mit ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[9964] = { id = 9964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe von der Geißel", description = "Die Schutzzauber, die Ihr bemerkt habt, sind tatsächlich sehr starke Magie. Die Fertigkeiten der Arakkoa entziehen sich unserem Verständnis, weswegen wir nur hoffen können, dass wir mit ihrer Hilfe einen Gegenzauber finden können.\n\nIch weiß, was Ihr denkt. Warum sollte der Feind uns helfen wollen, seine Verteidigung zu durchbrechen? Die Antwort ist natürlich, dass er das nicht will. Habt Ihr die Geschichten über den verrückten alten Arakkoa namens Kokorek gehört? Man sagt, er hielte sich im Lithicversteck am westlichen Ende der Knochenwüste auf und warte auf die Rückkehr längst vergangener Zeiten.", sourceObjective = "Sucht Kokorek im Lithicversteck und sprecht mit ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[9965] = { id = 9965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guten Willen zeigen", description = "Ich möchte Euch einen Handel vorschlagen: zeigt mir, dass Ihr gute Absichten habt, indem Ihr mir bei der Lösung eines kleinen Problems helft, und ich werde Euch bei der Rettung Eures Freundes unterstützen.\n\nDie Oger sind ein uralter Feind meines Volkes, und in letzter Zeit haben sie begonnen, vom Grasland in Nagrand zurück in unsere Wälder zu ziehen.\n\nEiner dieser Oger, Mug'gok, ist ein ziemlich abenteuerlicher Geselle, aber leider kein allzu kluger. Er reist die ganze Zeit hin und her, bereitet seinen Freunden in den Ruinen des Blutenden Auges Ärger und provoziert uns.", sourceObjective = "Bringt Mug'goks Kopf zu Kokorek im Lithicversteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[9966] = { id = 9966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guten Willen zeigen", description = "Ich möchte Euch einen Handel vorschlagen: zeigt mir, dass Ihr gute Absichten habt, indem Ihr mir bei der Lösung eines kleinen Problems helft, und ich werde Euch bei der Rettung Eures Freundes unterstützen.\n\nDie Oger sind ein uralter Feind meines Volkes, und in letzter Zeit haben sie begonnen, vom Grasland in Nagrand zurück in unsere Wälder zu ziehen.\n\nEiner dieser Oger, Mug'gok, ist ein ziemlich abenteuerlicher Geselle, aber leider kein allzu kluger. Er reist die ganze Zeit hin und her, bereitet seinen Freunden in den Ruinen des Blutenden Auges Ärger und provoziert uns.", sourceObjective = "Bringt Mug'goks Kopf zu Kokorek im Lithicversteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[9967] = { id = 9967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Die Blaumänner", description = "Im nächsten Kampf werdet Ihr auf gleich zwei Gegner treffen, Zwillinge um genau zu sein. Sie nennen sich selbst die \"Blaumänner\".\n\nEs ist noch nicht zu spät, um zu kneifen, {name}. Ich könnte das verstehen.\n\nAber wenn Ihr bereit seid für ein wenig Action, tretet in den Ring des Blutes und wartet auf die Zwillinge der Finsterblut.\n\nDer Letzte, der noch steht, hat gewonnen!", sourceObjective = "Besiegt die Zwillinge der Finsterblut, die sich selbst die Blaumänner nennen. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", completion = "Ich gebe zu, dass ich nicht geglaubt habe, dass Ihr eine Chance hättet, {name}! Das war beeindruckend! Wie wär's mit einem weiteren Kampf? Gurgthock hat den perfekten Gegner für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9968] = { id = 9968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremde Energien", description = "Etwas Merkwürdiges hat die Teromotten des Dickichts verändert.\n\nWo einst eine Vielfalt von Arten herrschte, sind jetzt nur noch die Teromotten übrig. Und während sie früher friedlich waren, sind sie jetzt sehr aufgeregt und greifen alles an, was ihnen zu nahe kommt.\n\nIch muss die bösartigen mit den normalen Motten vergleichen. Bringt mir ein paar Exemplare von beiden Sorten. Die gewöhnlichen Teromotten findet Ihr im Süden und im Norden.\n\nIch bin mir sicher, dass dies mit dem Tod der Druiden zusammenhängt.", sourceObjective = "Sammelt 4 Teromottenproben und 4 Proben einer bösartigen Teromotte. Kehrt dann zu Erdbinder Tavgren beim Cenariusdickicht in den Wäldern von Terokkar zurück.", progress = "Habt Ihr meine Proben?", completion = "Merkwürdig. Die Proben der bösartigen Teromotten enthalten etwas, das sich wie reines Mana anfühlt.\n\nWie es scheint hinterließ das, was all die Tode verursacht hat, ein starkes Energiefeld. Aber aus irgendeinem Grund hat es die Teromotten nicht umgebracht, sondern nur aufgewühlt.\n\nEs scheint, als wäre diese merkwürdige Energie ein Nebenprodukt dessen, was das Dickicht angegriffen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9969] = { id = 9969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Reagenzien", description = "Ich kann einen Gegenstand herstellen, der den Schutzzauber, der das Shalasversteck umgibt, aufheben kann, aber seid gewarnt, {name}, die Wirkung wird nur so lange andauern, bis Ihr Euren Freund befreit habt. Ich werde Euch keine Waffe geben, mit der Ihr mein Volk wann immer Ihr wollt angreifen könnt.\n\nIch habe fast alle Zutaten, die ich für diesen Zauber brauche, aber Ihr müsst noch ein paar weitere für mich sammeln, bevor ich ihn abschließen kann. Ich brauche etwas Sphärenpirscheressenz und eine Handvoll Apfelbeeren von Terokkar. Ihr könnt beides um das Versteck herum finden.", sourceObjective = "Bringt 5 Sphärenpirscheressenzen und 30 Apfelbeeren von Terokkar zu Kokorek im Lithicversteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[9970] = { id = 9970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Rokdar der Zerklüftete", description = "Das wird ein harter Kampf, {name}. Habt Ihr vielleicht ein paar Freunde, die Euch helfen können? Den Ogern ist es gelungen, einen Riesen namens Rokdar aus dem Schergrat hierher zu bringen! Glaubt mir, Ihr werdet ein paar Freunde brauchen, er scheint unbesiegbar zu sein! Er ist hart wie Stein - im wahrsten Sinne des Wortes!\n\nWenn Ihr immer noch gegen ihn antreten möchtet, tretet in den Ring des Blutes und er wird kommen.", sourceObjective = "Besiegt Rokdar den Zerklüfteten. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", completion = "Ihr habt die Oger zum Schwitzen gebracht, Kleiner. Diesmal bekommt Ihr noch etwas dazu. Benutzt nicht alles auf einmal!\n\nSeid Ihr bereit für einen weiteren Kampf? Gurgthock setzt die ganze Bank auf Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[9971] = { id = 9971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise im Dickicht", description = "Ich habe keine Ahnung, was all die Druiden hier getötet hat. Ich war ein paar Tage unterwegs, um die Knochenwüste im Süden zu untersuchen.\n\nBitte, Ihr müsst mir helfen herauszufinden, was hinter dieser furchtbaren Tragödie steckt. Geht zum Dickicht und haltet nach einem Hinweis Ausschau, der uns weiterhelfen könnte. Als ich kurz dort war, hätte ich schwören können, dass ich einen toten Zerschlagenen und ein merkwürdiges Ding neben ihm gesehen habe.\n\nUnd habt keine Angst vor Baumlas - er ist vielleicht durch die Geschehnisse verrückt geworden, aber ich glaube, er ist harmlos.", sourceObjective = "Untersucht das merkwürdige Objekt neben der Leiche eines Zerschlagenen um herauszufinden, was hinter der Tragödie beim Cenariusdickicht steckt. Kehrt dann zu Erdbinder Tavgren außerhalb des Dickichts in den Wäldern von Terokkar zurück.", completion = "Ich hatte also Recht. Die Leiche eines Zerschlagenen? Und Ihr sagt, dass da tatsächlich ein komisches Objekt auf dem Boden neben ihm war?\n\nDas macht keinen Sinn. Was würde einer von ihnen denn hier wollen? Und was war das für ein Ding, das er dabei hatte?\n\nHat es vielleicht all die Tode verursacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[9972] = { id = 9972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Skra'gath", description = "Ihr bringt sie ja reihenweise um, <Kleiner/Kleine>! Dieses Mal haben sie einen Profi für den Kampf. Sie sagen er sei ein Leerenfürst oder so was... Sie wollen Euch auf keinen Fall gegen ihren Champion kämpfen lassen. Habt Ihr gehört wie Mogor, das Fallobst, Euch angekläfft hat? Die Wetten stehen astronomisch hoch!\n\nSteigt in den Ring und haut ihn um!", sourceObjective = "Besiegt Skra'gath. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", completion = "KLEINER! KLEINER IHR HABT ES GESCHAFFT! Als nächstes kommt der große Kampf! Die Meisterschaft!\n\nOk, locker bleiben. Wir wollen ja nicht, dass die Oger erfahren, dass hier was im Busch ist. Schließlich bekomme ich ja auch meinen Anteil daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[9973] = { id = 9973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Champion der Totschläger", description = "Sie mussten den Champion aus den Gladiatorengruben im Schergrat einschiffen. Dort hat er mit den Bergriesen trainiert - mit gleich dreien auf einmal!\n\nWenn Ihr gegen ihn gewinnt, seid Ihr der neue Champion. Glaubt Ihr, Ihr habt eine Chance? Könnt Ihr das schaffen? Sagt mir nur Bescheid, dann setze ich mein Haus auf Euch.\n\nJetzt steigt in den Ring und gewinnt!", sourceObjective = "Besiegt den Champion der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener, um Eure Belohnung zu erhalten.", completion = "Oh je, Mogor hat sein Kampfrecht als Held der Totschläger eingefordert. Ihr müsst gegen ihn kämpfen!\n\nNiemand hat je behauptet, dass die Totschläger gute Verlierer... äh... Oger wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[9974] = { id = 9974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Reagenzien", description = "Ich kann einen Gegenstand herstellen, der den Schutzzauber, der das Shalasversteck umgibt, aufheben kann, aber seid gewarnt, {name}, die Wirkung wird nur so lange andauern, bis Ihr Euren Freund befreit habt. Ich werde Euch keine Waffe geben, mit der Ihr mein Volk wann immer Ihr wollt angreifen könnt.\n\nIch habe fast alle Zutaten, die ich für diesen Zauber brauche, aber Ihr müsst noch ein paar weitere für mich sammeln, bevor ich ihn abschließen kann. Ich brauche etwas Sphärenpirscheressenz und eine Handvoll Apfelbeeren von Terokkar. Ihr könnt beides um das Versteck herum finden.", sourceObjective = "Bringt 5 Sphärenpirscheressenzen und 30 Apfelbeeren von Terokkar zu Kokorek im Lithicversteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[9975] = { id = 9975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urmagie", description = "Ich habe den Zauber in diesem Talisman aufbewahrt. Entfesselt ihn, wenn Ihr bei den Totems steht, die den Zugang zum Shalasversteck bewachen. Er sollte stark genug sein, um die Wächter außer Gefecht zu setzen.\n\n<Ihr bemerkt, dass die Figur des Talismans nicht wie ein Arakkoa aussieht.>\n\nMein Volk sah nicht immer so aus wie jetzt. Einst waren wir prächtige Wesen, aber wir... wir haben die falschen Entscheidungen getroffen und sind bei unserer heiligen Aufgabe gescheitert. Das hat uns unsere Schönheit, unsere Macht und fast unser Leben gekostet. Wiederholt unsere Fehler nicht, {name}.", sourceObjective = "Benutzt Kokoreks Talisman in der Nähe der Totems, die den Weg ins Shalasversteck bewachen, und sprecht dann mit Ausgrabungsleiter Balmoral.", sourceObjectiveStatus = "unverified-source-field" }
quests[9976] = { id = 9976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urmagie", description = "Ich habe den Zauber in diesem Talisman aufbewahrt. Entfesselt ihn, wenn Ihr bei den Totems steht, die den Zugang zum Shalasversteck bewachen. Er sollte stark genug sein, um die Wächter außer Gefecht zu setzen.\n\n<Ihr bemerkt, dass die Figur des Talismans nicht wie ein Arakkoa aussieht.>\n\nMein Volk sah nicht immer so aus wie jetzt. Einst waren wir prächtige Wesen, aber wir... wir haben die falschen Entscheidungen getroffen und sind bei unserer heiligen Aufgabe gescheitert. Das hat uns unsere Schönheit, unsere Macht und fast unser Leben gekostet. Wiederholt unsere Fehler nicht, {name}.", sourceObjective = "Benutzt Kokoreks Talisman in der Nähe der Totems, die den Weg ins Shalasversteck bewachen, und sprecht dann mit Aufklärer Nodak.", sourceObjectiveStatus = "unverified-source-field" }
quests[9977] = { id = 9977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Die letzte Herausforderung", description = "<Gurgthock zählt seinen riesigen Berg Gold.>\n\nIhr habt viel Geld eingebracht, <Kleiner/Kleine>. Wenn Ihr Mogor besiegt, verspreche ich, dass es sich für euch lohnen wird. Die ganzen Schmerzen, die Ihr im Ring des Blutes aushalten musstet, werden sich bezahlt machen.\n\nJetzt geht da rein und zeigt diesen Ogern, was in Euch steckt!", sourceObjective = "Besiegt Mogor, Held der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", completion = "Gurthock hat doch gesagt, dass es sich bezahlt machen wird, Kleiner. Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[9978] = { id = 9978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit allen Mitteln", description = "Ich bin mir nicht sicher, was das zu bedeuten hat, aber ich weiß, wie wir an weitere Hinweise kommen können.\n\nEmpoor ist ein Händler der Zerschlagenen, der mit allen Arten von Waren und Informationen handelt. Wenn wir ihn zum Reden bringen könnten, bin ich mir sicher, dass er etwas Interessantes zu sagen hätte.\n\nEr reist auf der Straße zwischen Tuurem und Shattrath hin und her. Seid aber vorsichtig, er hat einen Leibwächter.", sourceObjective = "Findet Empoor. Er hält sich auf der Straße zwischen Tuurem und Shattrath in den Wäldern von Terokkar auf. Bringt ihn dazu, Euch zu erzählen, was Ihr wissen wollt.", completion = "Gut, gut... Ich sage Euch, was ich weiß, aber viel ist das nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9979] = { id = 9979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windhändler Lathrai", description = "Ich wurde gebeten, ein paar Kästen mit Waren bei einem Astralen in Shattrath abzuholen und auszuliefern.\n\nAls ich ihn das letzte Mal gesehen habe, stand er außerhalb der Taverne Weltenend im Unteren Viertel. Sein Name ist Windhändler Lathrai, mehr weiß ich nicht!\n\nWenn Ihr mehr wissen wollt, dann fragt ihn selbst!", sourceObjective = "Sprecht mit Lathrai in der Nähe der Taverne Weltenend im Unteren Viertel in Shattrath.", completion = "Ja? Wie kann ich Euch diesmal helfen, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9980] = { id = 9980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Deirom!", description = "Macht Euch so schnell Ihr könnt ins Shalasversteck auf, {name}! Zeit ist von äußerster Wichtigkeit. Wenn die Arakkoa bemerken, was Ihr mit ihrer Verteidigung angestellt habt, werden sie wahrscheinlich versuchen, Deirom wegzubringen oder gar zu töten!\n\nNehmt ein oder zwei Freunde mit, wenn Ihr könnt. Es wird wahrscheinlich hart werden. Die Vogelwesen haben alles getan, um ihren Gefangenen unter Verschluss zu halten, und sie werden ihn sicher nicht so leicht aufgeben. Wenn Ihr Deirom gefunden habt, kehrt zu Allerias Feste zurück und benachrichtigt Thander.", sourceObjective = "Begebt Euch ins Shalasversteck, tötet Lunga und befreit Deirom. Meldet Euch bei Lady Dana Kennedy in Allerias Feste, wenn Ihr Euren Auftrag erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9981] = { id = 9981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Dugar!", description = "Macht Euch so schnell Ihr könnt ins Shalasversteck auf, {name}! Zeit ist von äußerster Wichtigkeit. Wenn die Arakkoa bemerken, was Ihr mit ihrer Verteidigung angestellt habt, werden sie wahrscheinlich versuchen, Dugar wegzubringen oder gar zu töten!\n\nNehmt ein oder zwei Freunde mit, wenn Ihr könnt. Es wird wahrscheinlich hart werden. Die Vogelwesen haben alles getan, um ihren Gefangenen unter Verschluss zu halten, und sie werden ihn sicher nicht so leicht aufgeben. Wenn Ihr Dugar gefunden habt, kehrt zur Steinbrecherfeste zurück und benachrichtigt Rokag.", sourceObjective = "Begebt Euch ins Shalasversteck, tötet Lunga und befreit Dugar. Meldet Euch bei Rokag in der Steinbrecherfeste, wenn Ihr Euren Auftrag erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9982] = { id = 9982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er nannte sich Altruis...", description = "Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.\n\nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?\n\nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.", sourceObjective = "Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.", sourceObjectiveStatus = "unverified-source-field" }
quests[9983] = { id = 9983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er nannte sich Altruis...", description = "Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.\n\nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?\n\nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.", sourceObjective = "Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.", completion = "Überrascht Euch mein Aussehen? Wisst Ihr, was ich bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9984] = { id = 9984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herr der versteckten Stadt", description = "Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Deirom gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.\n\nIch erinnert Euch, dass Thander erwähnt hat, dass Andarl die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.", sourceObjective = "Bringt Luangas Befehle zu Andarl in Allerias Feste in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9985] = { id = 9985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herr der versteckten Stadt", description = "Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Dugar gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.\n\nIch erinnert Euch, dass Rokag erwähnt hat, dass Kurgatok die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.", sourceObjective = "Bringt Luangas Befehle zu Kurgatok in der Steinbrecherfeste in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9986] = { id = 9986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arakkoa hindern", description = "Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.\n\nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.", sourceObjective = "Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Thander in Allerias Feste zurück.", completion = "Gut gemacht, {name}. Wir haben schon genug Sorgen, wir können uns nicht erlauben, dass die Arakkoa unsere Händler und Boten erneut angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9987] = { id = 9987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arakkoa hindern", description = "Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.\n\nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.", sourceObjective = "Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Rokag in der Steinbrecherfeste zurück.", completion = "Gut gemacht, {name}. Wir haben schon genug Sorgen, wir können uns nicht erlauben, dass die Arakkoa unsere Händler und Boten erneut angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9988] = { id = 9988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Freund eines Gecken", description = "Lasst Euch von Thander und seinem Gefolge nicht täuschen. Sie sehen vielleicht aus wie eine Gruppe von Furcht einflößenden Kriegern, aber sie sind nichts als eine Bande von Gecken!\n\nUnd sie lassen sich in der Öffentlichkeit nicht ohne ihre Hüte sehen. Das sind ganz schicke Teile aus Filz und Fell, mit den ausgefallensten Federn, die Ihr je gesehen habt.\n\nDie begehrtesten Federn stammen natürlich von den Arakkoa, und mein Vorrat geht langsam zur Neige. Ich würde Euch bezahlen, wenn Ihr sie für mich sammelt.", sourceObjective = "Bringt 30 Arakkoafedern zu Ros'eleth in Allerias Feste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9989] = { id = 9989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremde Geister", description = "Als ich in die Scherbenwelt kam und meine Ohren den Stimmen seiner Geister geöffnet habe, war ich erstaunt, was ich zu hören bekam. Nach einiger Zeit fand ich auch heraus, welche Geister ich nicht hören konnte.\n\nTrotz all meiner Versuche habe ich niemals mit den Geistern der Arakkoaahnen Kontakt aufnehmen können. Ihre Magie unterscheidet sich grundlegend von unserer, aber ich bin mir nicht sicher, ob ihre Geister außerhalb meiner Reichweite liegen.\n\nBringt mir die Federn vieler Arakkoa. Vielleicht kann ein Zeichen ihres Volks die nötige Verbindung herstellen.", sourceObjective = "Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9990] = { id = 9990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung von Tuurem", description = "Wisst Ihr, jetzt, da Ihr es sagt, erinnere ich mich daran, dass ich Empoor vor etwa einem Monat mehrere Kästen mit merkwürdigen und fremdartigen Bauteilen verkauft habe. Ich weiß nicht, wozu sie gut sind, aber ich weiß, dass sie nach Tuurem geliefert werden sollten.\n\nVielleicht sind dort ja noch ein paar Kästen davon?", sourceObjective = "Findet den versiegelten Kasten und bringt ihn zu Erdbinder Tavgren beim Cenariusdickicht in den Wäldern von Terokkar.", progress = "Welche Neuigkeiten bringt Ihr, {name}?", completion = "Astrale? Waren nach Tuurem? Fremdartige Bauteile? Und ein Blutelf, der den letzten Kasten zum Posten der Feuerschwingen bringen wollte?\n\nWas soll das alles bedeuten?! Was hat das mit dem Schicksal der Druiden im Cenariusdickicht zu tun?\n\nIch glaube, wir sollten einmal einen Blick in den Kasten werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9991] = { id = 9991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspektion des Lagers", description = "Wenn Ihr meine Augen sein wollt, müsst Ihr sehr sorgfältig sein. Nethrandamus wird Euch durch die Lager der Legion führen, aber Ihr müsst alles, was Ihr seht, katalogisieren. Selbst das kleinste Detail, und wenn Euch noch so unwichtig erscheint, kann für unsere Zwecke hilfreich sein.\n\nZuerst möchte ich, dass Ihr notiert, welchen Aufbau das Lager hat und wie seine Verteidigungsmaßnahmen aussehen.\n\nNethrandamus ist bereit, wenn Ihr es seid, {name}. Habt keine Angst, er wird Euch beschützen.", sourceObjective = "Lehnt Euch zurück und genießt Euren Flug. Sprecht mit Altruis wenn die Besichtigung abgeschlossen ist.", completion = "Ausgezeichnete Arbeit, {name}! Jetzt haben wir einen Ausgangspunkt um unseren Gegenangriff zu planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9992] = { id = 9992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olembasamen", description = "Sind die Bäume des Waldes nicht wunderschön? Ich habe mich schon oft gefragt, ob sie wohl auch in Azeroth wachsen würden.\n\nIch scheue mich jedoch davor, Keimlinge zurückzuschicken. Es ist ein anstrengender Weg und sie sind viel schwieriger zu transportieren als ein Sack mit Samen. Die Samenkörner wachsen in harten Zapfen, die von den Ästen der Bäume fallen, wenn sie reif sind.\n\nWenn Ihr auf Euren Reisen ein paar dieser Zapfen findet, könntet Ihr mir dann ein paar Samenkörner bringen?", sourceObjective = "Sammelt 30 Olembasamenkörner und kehrt dann zu Ros'eleth in Allerias Feste zurück.", progress = "Ich habe eine Samenkornsammlung angefangen, aber ich werde Hilfe brauchen, bis ich genügend zusammen habe, um sie nach Sturmwind zu schicken.", completion = "Vielen Dank für diese Samenkörner. Ich habe schon fast genügend zusammen, um eine erste Ladung zurückzuschicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[9993] = { id = 9993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olembaöl", description = "Die öligen Samen der Olembabäume könnten sich als sehr wertvoll erweisen. Ich würde gern eine größere Menge davon sammeln und schauen, was ich daraus machen kann.\n\nStellt Euch nur vor, da steht ein ganzer Wald mit Bäumen, die so viele Samen produzieren, die alle ungenutzt bleiben. Mir ist egal, ob ich nur Salatöl, Waffenöl oder Lampenöl daraus herstellen kann, ich werde ihre Verschwendung nicht dulden!\n\nBringt mir alle Samen, die Ihr von den Olembazapfen sammeln könnt. Sie liegen hier überall.", sourceObjective = "Bringt 30 Olembasamenkörner zu Rakoria in der Steinbrecherfeste.", progress = "Habt Ihr ein paar Samenkörner für mich?", completion = "Das ist ein guter Anfang, aber wir werden noch mehr davon brauchen, wenn wir eine angemessene Menge Öl herstellen wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9994] = { id = 9994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das?", description = "Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!\n\n{name}, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste im Südosten bringen. Vielleicht hat sie ja eine Ahnung, was das ist.", sourceObjective = "Bringt den Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar.", progress = "Ihr seht besorgt aus. Was ist los, {class}?", completion = "Oh nein! Das sind furchtbare Nachrichten! Ich kann nicht glauben, dass alle bis auf zwei unserer Cenariusfreunde tot sind!\n\nIn Ordnung, lasst mich die Teile einmal anschauen. Ich hoffe nur, dass sie nicht das sind, was ich vermute.\n\nJa, wie ich befürchtet habe. Ich glaube, das sind Bombenteile. Unsere Augen und Ohren in Shattrath haben uns informiert, dass einige Astrale verbotene Waren aus anderen Dimensionen, mit denen sie in Kontakt stehen, einführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9995] = { id = 9995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das?", description = "Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!\n\n{name}, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Tooki in die Steinbrecherfeste im Südosten bringen. Vielleicht hat er ja eine Ahnung, was das ist.", sourceObjective = "Bringt den Kasten mit Ersatzteilen zu Tooki in der Steinbrecherfeste in den Wäldern von Terokkar.", progress = "Ihr seht besorgt aus. Was ist los, {class}?", completion = "Oh nein! Das sind furchtbare Nachrichten! Ich kann nicht glauben, dass alle bis auf zwei unserer Cenariusfreunde tot sind!\n\nIn Ordnung, lasst mich die Teile einmal anschauen. Ich hoffe nur, dass sie nicht das sind, was ich vermute.", sourceObjectiveStatus = "unverified-source-field" }
quests[9996] = { id = 9996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Posten der Feuerschwingen", description = "Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.\n\nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.\n\nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Norden und kümmert Euch darum!", sourceObjective = "Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Leutnant Meridian bei Allerias Posten in den Wäldern von Terokkar zurück.", completion = "Das ist ein guter Anfang, aber nach dem, was Ihr auf dem Hof beobachtet habt und was mir meine Agenten berichten, haben wir weitaus dringendere Dinge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9997] = { id = 9997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Posten der Feuerschwingen", description = "Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.\n\nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.\n\nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Nordosten und kümmert Euch darum!", sourceObjective = "Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Unteroffizierin Chawni im Steinbrecherlager in den Wäldern von Terokkar zurück.", completion = "Das ist ein guter Anfang, aber nach dem, was Ihr auf dem Hof beobachtet habt und was mir meine Agenten berichten, haben wir weitaus dringendere Dinge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9998] = { id = 9998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerspenstige Nachbarn", description = "Thander ist über die Ankunft der Höllenorcs bei den Ruinen vor Kurzem sowohl überrascht als auch besorgt. Sie haben keine Zeit verschwendet und sofort begonnen, Befestigungsanlagen zu bauen und die Gebäude zu reparieren.\n\nDie Bauarbeiten laufen Tag und Nacht, {name}. Ich habe ein paar meiner zuverlässigsten Agenten losgeschickt, um die Situation zu überwachen, aber wir können uns keine Verzögerungen leisten. Geht gegen ihre Arbeiter vor und sucht dann nach Theloria Dämmermantel bei Allerias Posten nördlich der Ruinen der Knochenmalmer. Sie wird Euch weitere Anweisungen geben.", sourceObjective = "Tötet 12 verunstaltete Peons und meldet Euch dann bei Theloria Dämmermantel bei Allerias Posten.", completion = "<Die Hochelfe nickt.>\n\nEs ist ein guter Anfang, aber Bertelm hatte Recht, Euch zu mir zu schicken. Ich habe eine Entdeckung gemacht, die die Anwesenheit der Höllenorcs hier erklären könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9999] = { id = 9999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiel auf Zeit", description = "Solange die Transporter noch stehen, ist nichts, was wir gegen die Konstruktionslager unternehmen, von Dauer. Wir müssen einen Weg finden, die Gebäude der Legion zu zerstören.\n\nIch brauche Zeit, um einen Angriffsplan auszuarbeiten. Wenn Ihr die Ingenieure und Tüftler eine Weile beschäftigen könntet, würde das ihre Fortschritte verlangsamen, und ich hätte die Zeit, die ich benötige.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr 2 Legionäre der Teufelswache, 3 Ingenieure der Mo'arg und 8 Tüftler der Gan'arg tötet.", completion = "Wie ich es mir dachte. Es gibt keinen normalen Weg, Teufelsstahl zu zerstören. Es ist aber noch nicht alles verloren...", sourceObjectiveStatus = "unverified-source-field" }
quests[10000] = { id = 10000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unangenehme Gesellschaft", description = "Unsere Streitkräfte in Thrallmar dachten, sie hätten die Höllenorcs der Höllenfeuerzitadelle unter Kontrolle, aber die Neuankömmlinge in den Ruinen im Osten sagen etwas anderes.\n\nWir können ihnen nicht erlauben, hier Fuß zu fassen. Rokag hat Schattenpirscher Kaide zu den Ruinen geschickt, um sie zu beobachten, aber wir müssen sie aufhalten, bevor sie es sich zu bequem machen.\n\nGeht zu den Ruinen, dezimiert ihre Peons und haltet bei den Bäumen im Norden nach Kaide Ausschau. Er wird Euch sagen, wo Ihr danach hingehen sollt.", sourceObjective = "Tötet 12 verunstaltete Peons und meldet Euch dann bei Schattenpirscher Kaide.", completion = "Um die Höllenorcs aufzuhalten müssen wir schon mehr tun, als ihre Arbeiter zu töten. Ich habe eine Entdeckung gemacht, die vielleicht erklären kann, warum sie hier sind, und die mich in meiner Überzeugung bestätigt, dass wir schnell handeln müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10001] = { id = 10001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterplaner", description = "Alle Konstruktionslager haben einen Meisterplaner. Der Meisterplaner bestimmt, welche Gebäude im Konstruktionslager vorhanden sein müssen, und wie sie platziert werden. Zudem werden diese Informationen auf Blaupausen festgehalten, die der Planer bei sich trägt.\n\nWir brauchen die Blaupausen des Meisterplaners. Mit solch detaillierten Informationen könnten wir einen meiner Bekannten dazu bewegen, uns etwas Unterstützung zu schicken.\n\nSucht den Meisterplaner der Mo'arg und stehlt seine Blaupausen. Er wird sich hinter den Konstruktionen aufhalten.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners besorgt.", progress = "Bleibt auf jeden Fall von den Vorarbeitern fern. Sie dürfen nichts von Eurer Anwesenheit mitbekommen. Die Folgen könnten verheerend sein!", completion = "Mein Bekannter kennt hoffentlich einen Weg, die Lager zu zerstören. Er war schließlich mal ein Ingenieur der Legion...", sourceObjectiveStatus = "unverified-source-field" }
quests[10002] = { id = 10002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermittler der Feuerschwingen", description = "In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?\n\nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.\n\nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.", sourceObjective = "Findet und tötet Lisaile Feuerweber und kehrt dann zu Theloria Dämmermantel zurück.", completion = "<Theloria nickt Euch zu.>\n\nGut gemacht. Dadurch haben wir uns ein wenig Zeit verschafft. Die Blutelfen werden sich fragen, was ihrer Freundin zugestoßen ist. Hoffentlich wissen wir bis dahin mehr über ihre Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[10003] = { id = 10003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermittler der Feuerschwingen", description = "In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?\n\nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.\n\nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.", sourceObjective = "Findet und tötet Lisaile Feuerweber und kehrt dann zu Schattenpirscher Kaide zurück.", completion = "<Kaide nickt Euch zu.>\n\nGut gemacht. Dadurch haben wir uns ein wenig Zeit verschafft. Die Blutelfen werden sich fragen, was ihrer Freundin zugestoßen ist. Hoffentlich wissen wir bis dahin mehr über ihre Pläne.\n\nWenn die Zeit gekommen ist, werde ich Rokag von unseren Fortschritten berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10004] = { id = 10004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geduld und Verständnis", description = "Nehmt die Blaupausen und reist nach Shattrath in den Wäldern von Terokkar. Wenn Ihr in Shattrath seid, geht ins Untere Viertel sucht nach einem Mo'arg namens Sal'salabim. Er ist wahrscheinlich an der Bar und ertränkt seine Sorgen.\n\nDa fällt mir ein, dass Ihr ihn wahrscheinlich überreden müsst, uns zu helfen. Versucht ihm viel Geduld und Verständnis entgegenzubringen. Wenn das nichts hilft, dann versucht es mit Gewalt.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners zu Sal'salabim in Shattrath bringt und ihn überredet, euch zu helfen.", progress = "<Sal'salabim kratzt sich am Kopf.>\n\n[Dämonisch] Ik il romath sardon.", completion = "Beruhigt Euch, Schätzchen, Sal'salabim wird helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10005] = { id = 10005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbinder Tavgren Bescheid sagen", description = "{name}, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.\n\nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.", sourceObjective = "Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.", completion = "Eine Bombe aus reinem Mana, die ganze Städte auslöschen kann! Aber warum? Warum würden die Blutelfen so etwas bauen und gegen uns verwenden? Das Cenariusdickicht sollte ein Ort des Friedens und der Erholung sein.\n\nWas auch immer der Grund sein mag, ich bin sicher, dass Aufseher Baumlas ihn kennt, doch ich habe keine Ahnung, wie ich ihn heilen kann. Vielleicht heilt sein Geist mit der Zeit von alleine?\n\nWie auch immer, ich danke Euch für Eure Hilfe. Ich kann nur hoffen, dass diese Tragödie sich niemals wiederholen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10006] = { id = 10006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbinder Tavgren Bescheid sagen", description = "{name}, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.\n\nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.", sourceObjective = "Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.", completion = "Eine Bombe aus reinem Mana, die ganze Städte auslöschen kann! Aber warum? Warum würden die Blutelfen so etwas bauen und gegen uns verwenden? Das Cenariusdickicht sollte ein Ort des Friedens und der Erholung sein.\n\nWas auch immer der Grund sein mag, ich bin sicher, dass Aufseher Baumlas ihn kennt, doch ich habe keine Ahnung, wie ich ihn heilen kann. Vielleicht heilt sein Geist mit der Zeit von alleine?\n\nWie auch immer, ich danke Euch für Eure Hilfe. Ich kann nur hoffen, dass diese Tragödie sich niemals wiederholen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10007] = { id = 10007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reihen lichten", description = "So wie ich Thander und Bertelm kenne, werden sie nicht dulden, dass eine feindliche Macht so ein großes Lager direkt vor unserer Haustüre errichtet. Aber sie zu bitten, ein paar Leute ihrer Garnison zu schicken, um das Lager anzugreifen, steht auch nicht zur Debatte. Wir wären dann viel zu leicht angreifbar.\n\nWir müssen uns also selbst darum kümmern, die Bedrohung durch die Bauarbeiten der Höllenorcs zu verringern. Tötet alle von ihnen, die Ihr könnt, und ich sehe mich solange nach Verstärkung um.", sourceObjective = "Tötet 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer und kehrt dann zu Theloria Dämmermantel zurück.", completion = "Langsam sehen die Dinge besser aus. Wenn wir die Höllenorcs daran hindern können, ihre Kumpel hier zu unterstützen, können wir den Posten unter Kontrolle halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10008] = { id = 10008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was in Terokkar geschieht, bleibt in Terokkar", description = "Wenn Thrallmar erfährt, dass sie es nicht geschafft haben, die Höllenorcs unter Kontrolle zu halten, werden wir hier bald viel Gesellschaft haben. Ehrlich gesagt bin ich mir nicht sicher, ob ich so viel Aufmerksamkeit möchte, deswegen behalten wir dieses kleine Problem für uns, verstanden?\n\nWenn wir den Höllenorcs genug Verluste beibringen können, besteht die Möglichkeit, dass niemand außerhalb der Steinbrecherfeste von ihrer Anwesenheit erfährt.\n\nMarschiert da rein, schwingt Eure Waffe, wedelt mit der Hand - oder was auch immer Ihr tut - und tötet die Höllenorcs!", sourceObjective = "Schattenpirscher Kaide möchte, dass Ihr 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer tötet.", completion = "Ich weiß, dass Ihr schon weit gereist seid, {name}, aber manche Geschichten sollten das Land niemals verlassen, haben wir uns verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[10009] = { id = 10009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Schädel spalten", description = "<Sal'salabim lacht.>\n\nDas Sal'salabims Entwurf.\n\n<Sal'salabim zeigt auf die Architektur und die Anordnungen auf den Blaupausen.>\n\nSchaut Türme an. Dämonenjäger kann nicht sehen, oder? Armer, armer Altruis. Er weinen wenn er Augen hätte, oder?\n\nJa, Sal'salabim helfen, aber erst Ihr helfen Sal'salabim.\n\n<Sal'salabim gibt Euch einen Ordner.>\n\nDiese Wesen schulden Sal'salabim Gold. Viel Gold. Gehen für Sal'salabim eintreiben. Sie werden nicht einfach rausrücken Sal'salabims Gold. Müssen kämpfen, aber Ihr stark. Ihr besiegen Sal'salabim!", sourceObjective = "Sal'salabim in Shattrath möchte, dass Ihr Raliqs Schulden, Kusch'kuschs Schulden und Floons Schulden eintreibt.", progress = "Ihr ja nicht kommen zurück ohne Sal'salabims Gold!", completion = "Nun, Geschäft sein Geschäft, aber wenn Sal'salabim Euch sagen, Ihr nicht böse werden, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[10010] = { id = 10010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So einfach ist das?", description = "<Sal'salabim zeigt auf die Blaupause.>\n\nSeht Ihr, wo Teufelskanonen sind?\n\n<Sal'salabim zeichnet einen Pfeil, der einen Richtungswechsel anzeigt.>\n\nIhr dreht Teufelskanone um und richtet sie auf Gebäude.\n\nWartet! Nicht durchdrehen! Ihr wisst etwas nicht. Vorarbeiter haben Schlüssel, um Kanonen zu drehen. Ihr braucht erst Schlüssel! Einer von jedem Vorarbeiter!\n\nNicht so leicht, was?\n\nBringt Information zurück zu Altruis.", sourceObjective = "Sal'salabim in Shattrath möchte, dass Ihr zu Altruis dem Leider im westlichen Nagrand zurückkehrt.", completion = "Natürlich! Wir werden sie mit ihren eigenen Waffen schlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10011] = { id = 10011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager: zerstört", description = "Sammelt Euren Mut, {name}. Ihr werdet ihn brauchen, wenn Ihr einem Vorarbeiter gegenübersteht.\n\nSobald Ihr bereit seid, sucht und tötet die Vorarbeiter in jedem Lager. Nehmt ihre Schlüssel und benutzt sie, um die Kanonen umzudrehen. Schießt damit auf die Lager. Kehrt zu mir zurück, wenn die Lager zerstört sind.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr das Konstruktionslager: Hass und das Konstruktionslager: Furcht zerstört.", completion = "Wir haben gesiegt! Das Vorrücken der Legion wurde gebremst!\n\nIch biete Euch eine Auswahl an Belohnungen für Eure heldenhaften Taten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10012] = { id = 10012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenorcpläne", description = "Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.\n\nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Bertelm mehr über dieses merkwürdige Bündnis. Ihr beschließt, zu Allerias Feste zurückzukehren und ihm die Pläne zu zeigen.", sourceObjective = "Bringt die Höllenorcpläne zu Bertelm in Allerias Feste in den Wäldern von Terokkar.", progress = "Was habt Ihr da, {name}?", completion = "<Bertelm nimmt die Pläne und schaut sie an.>\n\nWenn Ihr mir diese Pläne nicht gebracht hättet, hätte ich behauptet, dass Ihr irre seid, aber hier steht es ganz deutlich. Die Höllenorcs sind nicht nur hier, um den Blutelfen zu dienen, sie haben sogar den Auftrag, uns abzulenken.\n\nDiese Pläne werfen mehr Fragen auf, als sie beantworten, aber nun können wir uns besser vorstellen, womit wir es hier zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10013] = { id = 10013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ungesehene Hand", description = "Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.\n\nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Rokag mehr über dieses merkwürdige Bündnis. Ihr beschließt, zur Steinbrecherfeste zurückzukehren und ihm die Pläne zu zeigen.", sourceObjective = "Bringt die Höllenorcpläne zu Rokag in der Steinbrecherfeste in den Wäldern von Terokkar.", progress = "Was habt Ihr da, {name}?", completion = "<Rokag nimmt die Pläne und schaut sie an.>\n\nKaide hatte also Recht! Diese Höllenorcs führen etwas im Schilde. Ich hätte jedoch nie gedacht, dass sie mit den Blutelfen zusammenarbeiten.\n\nLaut diesen Plänen sollen die Höllenorcs uns beschäftigen... aber warum? Das sind beunruhigende Nachrichten, {name}. Gut, dass Ihr mir die Pläne gleich gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10014] = { id = 10014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Projekt des Postens der Feuerschwingen", description = "Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.\n\nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen Allerias Feste einzusetzen!\n\nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!", sourceObjective = "Stehlt die vier Codetabellen der Manabombe und bringt sie zu Meridian in Allerias Posten in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10015] = { id = 10015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Projekt des Postens der Feuerschwingen", description = "Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.\n\nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen die Steinbrecherfeste einzusetzen!\n\nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!", sourceObjective = "Stehlt die vier Codetabellen der Manabombe und bringt sie zu Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10016] = { id = 10016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldworgschwänze", description = "Seid Ihr auf Euren Reisen den Waldworgs begegnet? Ich hatte die Gelegenheit, sie zu beobachten, als ich einige der nördlichen Regionen des Waldes kartografiert habe. Ich würde Euch nicht empfehlen, zu nahe an sie heranzugehen, es sei denn, Ihr seid bereit für einen Kampf.\n\nSie haben keine Angst und scheuen vor nichts zurück, um ihr Territorium zu verteidigen.\n\nEs ist nicht verwunderlich, dass diese Kreaturen solch wundervolle Schwänze haben. Ich habe versucht, ein paar von ihnen zu sammeln, um einen neuen Mantel zu schneidern, aber die Worgs entkommen meinen Fallen dauernd. Wollt Ihr mir helfen?", sourceObjective = "Bertelm in Allerias Feste möchte, dass Ihr ihm 12 Waldworgschwänze bringt. Die Schwänze können von Waldworgs oder Waldworgalphas stammen.", progress = "Wie ich sehe habt Ihr die Gefahren des Waldes überlebt. Habt Ihr ein paar Schwänze für meinen Umhang?", completion = "Ah, gut gemacht, Freund. Sie sind noch feiner, als ich gedacht habe. Sie werden sicher einen schönen Umhang abgeben.\n\n<Bertelm schaut zum Gasthaus hinüber.>\n\nJa, das wird ein schöner Umhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[10017] = { id = 10017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwindende Vorräte", description = "Immer mehr Flüchtlinge kommen Tag für Tag durch die Tore von Shattrath. Viele sind so schwer verwundet, dass es an ein Wunder grenzt, dass sie es überhaupt hierher geschafft haben.\n\nAls Heiler der Aldor kann ich die meisten gewöhnlichen Wunden verarzten. Vergiftete Wunden sind jedoch problematischer, da mir langsam die Vorräte an Gegengift ausgehen.\n\nBringt mir ein paar Schreckensgiftbeutel von den Schreckensspinnen hier in der Gegend, damit ich mehr davon herstellen kann. Ihr findet eine Gruppe von diesen Spinnen im Südosten von Terokkar.", sourceObjective = "Bringt 8 Schreckensgiftbeutel zu Sha'nir in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr die Giftbeutel, {name}? Diese Flüchtlinge können nicht mehr lange warten.", completion = "Ihr habt meinen Dank, {name}. Die Aldor werden von Euren Taten erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10018] = { id = 10018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Wolfgeistes", description = "Vor Generationen, als die Orcs die Wälder von Terokkar noch ihr Zuhause nannten, spielte der Wolfgeist eine große Rolle in ihrem Leben. Als die Orcs fortgingen, brauchten sie den Wolfgeist nicht mehr und haben ihn zurückgelassen.\n\nMit der Zeit wurde der Geist einsam und verließ die Wälder ebenfalls.\n\nIch glaube, dass ich den Wolfgeist zu seinem ursprünglichen Heim zurückbringen kann, wie auch wir Orcs zurückgekehrt sind. Das Ritual erfordert, dass ich ein Gewand aus den Pelzen der Wölfe der Wälder schneidere, um den Wolfgeist zu seinem Zuhause zurück zu geleiten.", sourceObjective = "Bringt 12 Waldworgpelze zu Malukaz in der Steinbrecherfeste.", progress = "Konntet Ihr alle Pelze, die ich benötige, finden?", completion = "Die Pelze sind perfekt, {name}! Ich hätte keine besseren bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10019] = { id = 10019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Giftbeutel", progress = "Viele Flüchtlinge brauchen immer noch Heilung für ihre vergifteten Wunden. Habt Ihr mir noch mehr Giftbeutel gebracht, {name}?", completion = "Ihr habt meinen Dank, {name}. Die Naaru haben diese unglücklichen Seelen unter ihren Schutz gestellt. Es wäre sehr schade, wenn sie es bis Shattrath geschafft hätten, um dort an ihren Wunden zu verenden." }
quests[10020] = { id = 10020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heilmittel für Zahlia", description = "Die Frau rechts von mir hat eine schwere Kopfverletzung erlitten. Sie hat zwar überlebt, aber ihr Augenlicht verloren.\n\nEin traditionelles Heilmittel meines Volkes verlangt das Blut eines sehr alten Basilisken.\n\nUnglücklicherweise leben die Basilisken von Terokkar wegen der Wilderei verschiedener Lager in der Regel nicht sehr lange.\n\nEs gibt jedoch einen Basilisken, dessen Name ich schon als Kind kannte. Er ist als Steinstarrer bekannt und soll östlich von hier leben, in der Nähe der Landesgrenze.\n\nBringt mir sein Blut, damit Zahlia wieder sehen kann.", sourceObjective = "Bringt Steinstarrers Blut zu Sha'nir in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr das Blut bekommen, {name}? Ohne das Blut wird Zahlia ihrem Sohn nie wieder in die Augen schauen können.", completion = "Vielen Dank, {name}. Sich um die Notleidenden zu kümmern ist eine schwierige Aufgabe, aber sie wird auf ihre ganz eigene Weise belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10021] = { id = 10021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht wiederherstellen", description = "Vor langer Zeit war ein Großteil dieses Gebiets von den Draenei bewohnt. Wir, die Aldor, hatten den Auftrag, unsere heiligen Stätten und Altäre zu beschützen. Doch seitdem wurden viele davon zerstört oder von unseren Feinden eingenommen.\n\nÖstlich von hier gibt es einen Außenposten der Arakkoa. Sie haben ihn mit voller Absicht auf dem Gebiet errichtet, auf dem drei unserer heiligen Altäre stehen. Die Arakkoa haben ihre üble Magie benutzt, um die ureigene Macht unserer Schreine zu verändern und zu schänden.\n\nBringt dies zum Arakkoaaußenposten und reinigt die drei Altäre.", sourceObjective = "Ishanah möchte, dass Ihr zum Arakkoaaußenposten östlich von Shattrath geht. Benutzt die gesegnete Phiole, um den östlichen Altar, den westlichen Altar und den nördlichen Altar zu reinigen.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ihr habt meinen Dank, {name}. Wir sind die Hüter des Lichts und können unsere Pflichten nicht vernachlässigen. Nicht einmal in den schwersten Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10022] = { id = 10022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwer zu fassende Eisenkiefer", description = "Jetzt, da ich das Fell habe, das ich für mein Gewand benötige, dachte ich, dass der Pelz eines ganz bestimmten Wolfs eine schöne Kapuze für meinen Umhang abgeben würde. Stellt Euch nur vor, wie es wäre, Euren Feind im Pelz des gerissensten Raubtiers der Wälder zu sehen!\n\nIch habe bisher vergeblich versucht, Eisenkiefer zu fangen. Ich habe versucht ihn in die Enge zu treiben, ihn zu überlisten und ihn zu locken. Nichts hat geklappt.\n\nEr streunt in den nordöstlichen Gebieten des Waldes herum, und ich würde Euch angemessen belohnen, wenn Ihr schafft, was mir nie gelang.", sourceObjective = "Bringt Eisenkiefers Pelz zu Bertelm in Allerias Feste.", progress = "Hat der alte Eisenkiefer Euch übers Ohr gehauen? Oder konntet Ihr den alten Gesellen überlisten?", completion = "Ich verneige mich vor Eurem Geschick, {name}. Ihr habt Euch als herausragender {class} bewiesen.\n\nIch werde Eure Hilfe bei der Herstellung dieses Umhangs nie vergessen. Er ist ein einzigartiges Gewand, das ich voller Stolz tragen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10023] = { id = 10023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patriarch Eisenkiefer", description = "Ihr habt gute Arbeit beim Sammeln der ersten Pelze geleistet.\n\nDas letzte Stück der Gewandung erfordert einen ganz besonderen Pelz. Es gibt einen bestimmten Wolf, der alt und gerissen ist, und sich dadurch den Rang des Patriarchen unter den Wölfen des Waldes verdient hat. Er ist unter ihnen als Eisenkiefer, der mächtige Jäger, bekannt.\n\nIn meinen Visionen habe ich ihn im Nordosten der Wälder umherstreifen sehen. Sein Pelz in meiner Gewandung wird sicher den Pfad des Wolfgeistes erhellen.\n\nBeklagt Eisenkiefer nicht. Er wird die ihm gebührende Ehre erhalten.", sourceObjective = "Bringt Eisenkiefers Pelz zu Malukaz in der Steinbrecherfeste.", progress = "Der Geist wartet, {name}. Habt Ihr den Pelz des Patriarchen?", completion = "Der Pelz ist noch vortrefflicher, als ich erhofft hatte! Das ist ein gutes Zeichen, {name}, und die Geister werden Euch wegen Eurem Beitrag zu dieser Zeremonie wohlgesinnt sein.\n\nIch habe Euch aus dem übrigen Pelz einen Helm gemacht, {name}. Er zeichnet Euch als mächtigen Jäger und Verbündeter des großen Wolfgeists der Wälder von Terokkar aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10024] = { id = 10024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voren'thals Visionen", description = "Unser Anführer, Voren'thal der Seher, war einst ein enger Vertrauter von Kael'thas. Seine prophetischen Visionen habe ihn gewarnt, dass Kaels Weg in der Zerstörung unseres Volkes enden würde.\n\nNormalerweise sind diese Visionen nur sehr vage und ungenau, aber unsere Alchemisten haben ein Elixier entwickelt, mit dessen Hilfe seine Visionen deutlicher werden. Unglücklicherweise erfordert das Elixier eine sehr seltene Zutat: Basiliskenaugen. Normalerweise bekomme ich sie von diesem aufgeblasenen Astralen, aber er hat mich enttäuscht.\n\nMacht Euch auf die Suche nach den Dunstschuppenbasilisken im gebirgigen Terokkar und bringt mir ihre Augen.", sourceObjective = "Bringt 8 Augen eines Dunstschuppenbasilisken zu Arkanist Adyria in Shattrath.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Basiliskenaugen für Voren'thals Elixier?", completion = "Sie sind in tadellosem Zustand, {name}. Macht weiter so, und die Seher werden bald zu Euren Freunden zählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10025] = { id = 10025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Basiliskenaugen", progress = "Um auch nur eine kleine Dosis von Voren'thals Elixier herzustellen, braucht man sehr viele Basiliskenaugen. Wenn Ihr mir mehr davon bringt, gewinnt Ihr sicher das Wohlwollen der Seher.", completion = "Ich danke Euch, {name}. Voren'thals Visionen können vielleicht eines Tages das Schicksal unseres Volks entscheiden. Wir tun gut daran, dafür zu sorgen, dass seine Visionen so klar wie möglich sind." }
quests[10026] = { id = 10026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Störungen", description = "Es ist mir ein wenig peinlich, aber mir ist hier in den Wäldern von Terokkar etwas widerfahren, was mir seit meinen Lehrjahren nicht mehr passiert ist.\n\nManchmal scheitern meine Zauber, obwohl ich genau weiß, dass ich alles richtig gemacht habe. Ich bin fast wahnsinnig geworden, als das zum ersten Mal passiert ist.\n\nIch glaube, ich habe den Grund dafür gefunden. Die Wälder sind voller Wesen, die Sphärenjäger genannt werden. Das sind dämonische Kreaturen mit einem Hang zur Magie und zur Störung magischer Ströme. Der beste Weg, um mit ihnen fertigzuwerden, ist, sie einfach zu töten.", sourceObjective = "Andarl in Allerias Feste möchte, dass Ihr 10 Sphärenjäger tötet.", completion = "<Andarl wischt sich die Stirn mit dem Ärmel seiner Robe ab.>\n\nZum Glück. Ich habe schon befürchtet, dass die Biester die restlichen Waldbewohner vertrieben haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10027] = { id = 10027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Störungen", description = "Es gibt nichts Ärgerlicheres, als einen Zauber vorzubereiten, und dann von einer unsichtbaren Macht unterbrochen zu werden. Nach dem vierten Mal wusste ich, dass es kein Zufall sein konnte, und habe Keb'ezil losgeschickt, um die Ursache herauszufinden.\n\nIch garantiere Euch, dass Ihr nie einen Wichtel treffen werdet, der widerspenstiger ist als Keb.\n\nWie auch immer, er konnte die Quelle des Problems finden, eine verteufelte Kreatur namens Sphärenjäger. Sie haben die Angewohnheit, überall, wo sie auftauchen, die magischen Energien zu stören. Ich habe genug von ihren Störungen.", sourceObjective = "Tötet 10 Sphärenjäger und kehrt dann zu Kurgatok in der Steinbrecherfeste zurück.", completion = "Keb'ezil ist sehr erleichtert, dass Ihr Euch um das kleine Problem gekümmert habt, nicht wahr Keb?\n\n<Der Wichtel ignoriert seinen Meister und scheint beleidigt zu sein.>\n\nIhr müsst ihm seine schlechten Manieren nachsehen. Ihr wisst ja, wie Dämonen sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[10028] = { id = 10028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefäße der Macht", description = "Zwischen den Ruinen von Tuurem gibt es einige Gefäße mit roher, magischer Energie. Wir können von Glück sagen, dass die Zerschlagenen, die in der Stadt eingefallen sind, keine Ahnung von dieser Machtquelle mitten unter ihnen haben, aber wir dürfen nicht hoffen, dass das so bleibt.\n\nMithilfe dieser Gefäße und ihrer Macht können die verstreuten Überlebenden meines Volkes der Verlockung der dämonischen Magie widerstehen. Jeder Quel'dorei, den wir vor dem Wahnsinn unseres Prinzen retten können, ist einer mehr, der uns beim Wiederaufbau unseres verlorenen Ruhms helfen kann. Bringt mir die Gefäße, {class}.", sourceObjective = "Bringt 8 Draeneigefäße zu Ros'eleth in Allerias Feste.", progress = "Konntet Ihr ein paar unbeschädigte Gefäße finden?", completion = "Ich hoffe, dass dies nicht die einzigen Gefäße in der Stadt sind. Es ist ein guter Anfang, aber ich schätze, wir werden noch viel mehr davon brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10029] = { id = 10029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister rufen", description = "Die Geister der Toten in der Knochenwüste rufen nach mir! Sie leiden!\n\n{class}, Ihr müsst zur Knochenwüste im Süden reisen und meinen Gehilfen Soolaveen bei der Flüchtlingskarawane aufsuchen. Er muss es auch spüren und wird Eure Hilfe dabei brauchen, die Geister dort zur Ruhe zu bringen.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht noch einholen. Ich weiß, dass sie in Norden der Knochenwüste Rast machen wollten, bevor sie weiter Richtung Süden nach Auchindoun ziehen wollten.", sourceObjective = "Anachoret Lyteera möchte, dass Ihr ihren Gehilfen Soolaveen bei der Flüchtlingskarawane in der Knochenwüste der Wälder von Terokkar findet.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[10030] = { id = 10030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochen zurückholen", description = "Die Knochen der Draenei, die bei der Explosion von Auchindoun gestorben sind, sind überall in der Knochenwüste verstreut. Viele ihrer Geister sind daher ruhelos und können nicht ins nächste Leben übertreten.\n\n{name}, Ihr müsst mir helfen, ihre Knochen wieder zu besorgen und sie zu ihrer letzten Ruhestätte zu bringen. Nur dann werden sie Frieden finden und den Segen des Lichts erlangen.\n\nSammelt die ruhelosen Knochen mit größter Vorsicht und bringt sie zu Ramdor dem Wahnsinnigen in Auchindoun in der Mitte der Knochenwüste. Trotz seines Namens wird er wissen, wie er sich um sie zu kümmern hat.", sourceObjective = "Sammelt 10 ruhelose Knochen und bringt sie zu Ramdor dem Wahnsinnigen bei der westlichen Seite des Rings der Beobachtung in Auchindoun, das sich in der Mitte der Knochenwüste in den Wäldern von Terokkar befindet.", progress = "Was ist das? Wer seid Ihr?", completion = "Super, genau das, was ich brauche... noch mehr Knochen.\n\n<Ramdor seufzt.>\n\nJa, ja, ich werde mich darum kümmern, dass die Gebeine dieser ehrenwerten Vorfahren ein anständiges Begräbnis bekommen, keine Sorge.\n\nWenn Ihr den Toten wirklich helfen wollt, habe ich noch eine andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10031] = { id = 10031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Verirrten den Weg zeigen", description = "Viele Geister der Draenei wurden von der Explosion in Auchindoun verderbt und wandeln nun voller Pein in der Wüste.\n\n{name}, ich flehe Euch an, gebt ihnen ihren Seelenfrieden wieder. Vernichtet die verirrten Geister und die Skelette der Zerschlagenen, die die Knochenwüste hinter den Mauern Auchindouns heimsuchen.\n\nWas? Ihr denkt, es wäre besser, sie in blinder Wut umherstreifen zu lassen?\n\nKehrt danach zu Anachoret Soolaveen bei der Flüchtlingskarawane zurück und berichtet ihm, was Ihr erreicht habt.", sourceObjective = "Tötet 10 verirrte Geister und 10 Skelette eines Zerschlagenen und kehrt dann zu Anachoret Soolaveen bei der Flüchtlingskarawane in der Knochenwüste in den Wäldern von Terokkar zurück.", completion = "Ihr habt getan, was nötig war. Auch wenn es mich traurig macht, dass die Geister meiner Vorfahren zu schrecklichen Untoten verwandelt wurden, hat Euer Handeln sie endlich zur Ruhe gebracht.\n\nVielen Dank, dass Ihr sie befreit habt, {name}. Bitte nehmt dieses bescheidene Zeichen meiner Hochachtung für Euch und Eure Selbstlosigkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10032] = { id = 10032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakte von Tuurem", description = "Ist Euch das Verhalten der Verirrten in Tuurem aufgefallen? Sie streifen in den Ruinen umher und suchen nach allen Überbleibseln der Draenei, die sie in die Finger bekommen können.\n\nIhre zerschlagenen Meister wissen es besser. Sie haben ihr früheres Leben abgestreift und sind zu etwas ganz anderem geworden.\n\nIch glaube, wir können die Gier der Verirrten ausnutzen und alte Draeneirelikte von ihnen sammeln. Warum sollten wir unser Leben im Kampf gegen die Zerschlagenen riskieren, wenn wir unsere Ziele weise auswählen können?", sourceObjective = "Sammelt 6 Artefakte von Tuurem von den Strauchdieben von Tuurem und den Jägern von Tuurem und bringt sie zu Rakoria in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10033] = { id = 10033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AUFRUF: Tötet die Knochenpeitscher!", description = "Es wurde ein Kopfgeld auf die Knochenpeitscher der Knochenwüste ausgesetzt. Als Überträger der Pest müssen sie von nun an vernichtet werden!\n\nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.\n\nMeldet Euch bei Taela Immerlauf, um Eure Belohnung einzufordern.", sourceObjective = "Tötet 20 Knochenpeitscher und meldet Euch dann bei Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar.", completion = "Ja, ich bin mir sicher, dass Ihr all die Knochenpeitscher getötet habt. Ist ja auch klar, weil der Hauptmann auf dem Anschlag einen Beweis gefordert hat.\n\n<Taela schaut Euch sarkastisch an.>\n\nIch nehme Euch beim Wort. Ich bin mir nicht sicher, wen ich so geärgert habe, dass ich zu diesem Dienst verdonnert wurde, aber vielen Dank für Eure Mühe für die Allianz. Hier habt Ihr eine Entschädigung für Euren Aufwand.", sourceObjectiveStatus = "unverified-source-field" }
quests[10034] = { id = 10034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AUFRUF: Tötet die Knochenpeitscher!", description = "Die Knochenpeitscher der Knochenwüste haben Mawg gebissen und ihn krank gemacht. Jetzt möchte er, dass sie alle vernichtet werden!\n\nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.\n\nKehrt zu Mawg Grimmschlag zurück, wenn Ihr die Aufgabe erledigt habt, und er wird Euch gut belohnen.", sourceObjective = "Tötet 20 Knochenpeitscher und meldet Euch dann bei Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar.", completion = "Ihr müsst viele von diesen Knochenpeitschern getötet haben! Gut, ich hasse sie! Seit mich einer von ihnen gebissen hat, habe ich dauernd Ohnmachtsanfälle.\n\nWisst Ihr, wie peinlich das ist? Hier, nehmt dies als Dank, dass Ihr meine Rache vollstreckt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10035] = { id = 10035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "In der Knochenwüste gibt es ein Wesen, das so bösartig, so widerlich und so Furcht einflößend ist, dass nur die besten Jäger es wagen, ihm aufzulauern.\n\nIch spreche von Torgos, dem König der Knochenpeitscher, der sich beim Rhazeversteck am westlichen Ende der Weiten herumtreibt.\n\nUnglücklicherweise haben die Arakkoa eine Vogelscheuche aufgestellt, die als 'Torgos' Fluch' bekannt ist und ihn von dort fernhält. Ich wette, dass er trotzdem herauskommen würde, wenn Ihr den Leichnam seines Weibchens Trachela am Fuß dieser Vogelscheuche platziert. Ihr findet sie beim Aashügel im nördlichen Teil der Wüste.\n\nBringt mir eine Schwanzfeder von Torgos.", sourceObjective = "Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar zurück.", progress = "Habt Ihr die Feder? Muss ich Euch für Eure waghalsige Kühnheit belohnen?", completion = "Ich bin beeindruckt, {class}. Torgos war eines der hartgesottensten Wesen, das ich auf dieser Seite von Nagrand kenne.\n\nNun, ich denke, Ihr habt Euch etwas aus dem Schatz von Allerias Feste verdient. Sucht Euch etwas aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10036] = { id = 10036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "Ich will Torgos, den König der Knochenpeitscher tot sehen!\n\nVor nicht allzu langer Zeit, als ich beim Rhazeversteck am westlichen Ende der Wüste auf Jagd war, fiel dieses Tier mich an.\n\n<Mawg tippt seine Augenklappe an.>\n\nEr hat mir mein Auge genommen, und nun will ich sein Leben dafür! Bringt mir eine seiner Schwanzfedern als Beweis und ich werde Euch gebührlich belohnen.\n\nIhr werdet den Leichnam seines Weibchens Trachela brauchen, um ihn hervorzulocken, da er Todesangst vor der alten Vogelscheuche der Arakkoa hat, die als Torgos' Fluch bekannt ist.\n\nIhr findet sie beim Aashügel im Norden der Wüste.", sourceObjective = "Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", progress = "Habt Ihr ihn getötet? Ist Torgos tot?\n\nHabt Ihr den Beweis?", completion = "Ich danke Euch, {name}. Ihr habt meine Rache ausgeübt, und wie versprochen werde ich Euch belohnen.\n\nSucht Euch hiervon etwas aus und benutzt es weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[10037] = { id = 10037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich würd' lieber angeln", description = "Da wir gerade von Seen sprechen, da gibt es einen See im Nordosten, an dem man richtig toll angeln kann. Früher bin ich da immer mit meinen Freunden hin, aber meine Mutter erlaubt es mir nicht mehr.\n\nSie sagt, es sei zu gefährlich, aber ich habe da oben noch nichts außer ein paar Spinnen gesehen. Als ob Spinnen einem irgendwas anhaben könnten...\n\nIch mochte am liebsten die Aale von da oben. Wenn Ihr zum See hoch geht, könntet Ihr mir dann ein paar dieser Aale bringen? Sie sind störrisch, aber wenn man sie einmal gebändigt hat, kann man sie ganz leicht mitnehmen.", sourceObjective = "Bringt 8 makellose Schimmerschuppenaale zu Seth in Shattrath.", progress = "<Seth zieht Euch am Mantel.>\n\nHabt Ihr die Aale? Hä? Hä?", completion = "Danke! Ich kann mich nicht erinnern, wann ich das letzte Mal Aal gegessen habe.\n\nWie soll ich sie bloß kochen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10038] = { id = 10038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Gefreiter Wöch", description = "Ich habe gerade einen Bericht von einem unserer Späher in der Nähe von Grangol'var erhalten. Er sagt, dass eine schattenhafte Truppe in die Ruinen dort eingezogen ist.\n\n{name}, ich möchte, dass Ihr mit Gefreiter Wöch sprecht und schaut, wie Ihr ihm dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.\n\nGeht nach Westen an der Steinbrecherfeste vorbei. Sein letzter Bericht besagt, dass er sich in der Nähe des nördlichen Eingangs zum Dorf befindet.", sourceObjective = "Sprecht mit Gefreiter Wöch in der Nähe des nördlichen Eingangs von Grangol'var in den Wäldern von Terokkar.", completion = "Es wird auch langsam Zeit, dass Ihr kommt. Ich habe diesen Bericht schon vor über einer Woche zur Allerias Feste geschickt!\n\nBürokratie!", sourceObjectiveStatus = "unverified-source-field" }
quests[10039] = { id = 10039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Späherin Neftis", description = "Ich wurde informiert, dass eine unserer Späherinnen in der Nähe von Grangol'var zurzeit eine schattenhafte Truppe beobachtet, die vor Kurzem dorthin gezogen ist.\n\n{name}, ich möchte, dass Ihr mit Späherin Neftis sprecht und schaut, wie Ihr ihr dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.\n\nGeht von hier aus nach Süden und dann nach Westen, um den Norden der Knochenwüste herum. Ihr letzter Bericht besagt, dass sie sich in der Nähe des südlichen Eingangs zum Dorf befindet.", sourceObjective = "Sprecht mit Späherin Neftis in der Nähe des südlichen Eingangs von Grangol'var in den Wäldern von Terokkar.", completion = "Es wird auch langsam Zeit, dass Ihr kommt. Ich habe diesen Bericht schon vor über einer Woche zur Steinbrecherfeste geschickt!\n\nBlutelfen und ihre Bürokratie!", sourceObjectiveStatus = "unverified-source-field" }
quests[10040] = { id = 10040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sind sie?", description = "Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!\n\nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.\n\nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.", sourceObjective = "Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Gefreiter Wöch in Grangol'var in den Wäldern von Terokkar zurück.", completion = "Gut, Ihr seid endlich zurück! Was habt Ihr herausgefunden? Wer sind sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10041] = { id = 10041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sind sie?", description = "Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!\n\nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.\n\nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.", sourceObjective = "Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Späherin Neftis in Grangol'var in den Wäldern von Terokkar zurück.", completion = "Gut, Ihr seid endlich zurück! Was habt Ihr herausgefunden? Wer sind sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10042] = { id = 10042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet den Schattenrat!", description = "Was? Diese Kerle gehören zum Schattenrat?!\n\n{name}, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.\n\nWenn Ihr damit fertig seid, meldet Euch bei Leutnant Kieshammer in Allerias Feste.\n\nViel Glück, {class}.", sourceObjective = "Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Leutnant Kieshammer in Allerias Feste in den Wäldern von Terokkar zurück.", completion = "Das sind schlechte Nachrichten! Aber ich habe die richtige Wahl getroffen, als ich Euch geschickt habe, um Wöch zu helfen. Das Letzte, was wir brauchen können, ist, dass der Schattenrat einen starken Posten genau vor unserer Haustür errichtet.\n\n{name}, als Anerkennung für Eure Taten in Grangol'var erlaube ich Euch hiermit, Euch eine dieser wundervollen Belohnungen auszusuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10043] = { id = 10043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet den Schattenrat!", description = "Was? Diese Kerle gehören zum Schattenrat?!\n\n{name}, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.\n\nWenn Ihr damit fertig seid, meldet Euch bei Beraterin Faila in der Steinbrecherfeste.\n\nViel Glück, {class}!", sourceObjective = "Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", completion = "Das sind schlechte Nachrichten! Aber ich habe die richtige Wahl getroffen, als ich Euch geschickt habe, um Neftis zu helfen. Das Letzte, was wir brauchen können, ist, dass der Schattenrat einen starken Posten genau vor unserer Haustür errichtet.\n\n{name}, Ihr habt Euch etwas Nettes verdient. Sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10044] = { id = 10044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei der Großmutter", description = "Die Großmutter hat mich gebeten, Euch aufzusuchen und Euch eine Nachricht zu überbringen. Sie möchte unverzüglich mit Euch sprechen.\n\nMein Wille mag vielleicht gebrochen sein, aber macht besser keinen Fehler, {name}. Wenn Ihr die Großmutter verärgert, werde ich Euch mit aller Kraft, die noch in mir steckt, bestrafen. Ihr findet sie in der Haupthalle.\n\n<Garrosh zeigt auf das große Gebäude im Norden.>\n\nHört Euch an, was sie zu sagen hat, und tut, was sie Euch aufträgt.", sourceObjective = "Sprecht mit Großmutter Geyah und hört Euch an, was sie zu sagen hat.", completion = "Wir müssen zuerst Euren Geist erweitern, damit Ihr mit den Ahnen sprechen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10045] = { id = 10045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutaten sammeln", description = "Mutter Kashur möchte mit Euch sprechen, {name}. Bevor Ihr das könnt, müsst Ihr jedoch ein paar Kräuter sammeln, um einen Trank zuzubereiten, der Euren Geist erweitert, damit Ihr mit den Geistern sprechen könnt.\n\nIhr müsst Olembawurzeln aus Terokkar, Marschenbeeren aus den Zangarmarschen, Telaarifarn aus Nagrand und Drachenwirbel aus dem Schergrat sammeln. Ich habe die Anleitung zum Anbau dieser Kräuter auf dieses Pergament geschrieben. Kehrt zu mir zurück, wenn Ihr die Zutaten beisammen habt.", sourceObjective = "Großmutter Geyah in Garadar in Nagrand möchte, dass Ihr 1 Olembawurzel, 1 Marschenbeere, 1 Telaarifarn und 1 Drachenwirbel sammelt.", progress = "Hallo, Kind.", completion = "Ihr seid sehr geschickt, {name}. Unsere besten Kräutersammler hätten doppelt so lange gebraucht, um die Kräuter zu sammeln.\n\n\n\nHabt keine Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[10046] = { id = 10046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Dunkle Portal", description = "Vor zwei Wochen haben unsere Späher beobachtet, wie eine schwer bewaffnete Streitmacht der Allianz unter dem Kommando von Feldkommandant Romus aus der Burg Nethergarde aufgebrochen ist. Mit so vielen Soldaten, Vorräten und einem so erfahrenen Kommandanten können sie nur ein Ziel haben: die Scherbenwelt.\n\nDer Kriegshäuptling hat eine Vorhut durch das Portal geschickt, aber wenn die Allianz glaubt, dass so viele Truppen von Nöten sind, sollten vielleicht auch wir Verstärkung schicken.\n\nReist durch das Dunkle Portal und meldet Euch bei Nazgrel in Thrallmar.", sourceObjective = "Reist durch das Dunkle Portal und sprecht mit Nazgrel in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10047] = { id = 10047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Ruhms", description = "Sie haben sie den Pfad des Ruhms genannt, eine Straße, die vom Herzen ihrer grausamen Festung zum Dunklen Portal führt, befestigt mit den Knochen meines Volks.\n\nEs war ihnen nicht genug, uns wie Tiere zu jagen, unsere Städte zu zerstören und die Überlebenden zu quälen. Nein, sie mussten auch noch unsere Knochen als Pflastersteine verwenden, und meinen Brüdern und Schwestern ein anständiges Begräbnis unter dem Licht verweigern.\n\nDiese gequälten Seelen wandeln immer noch durch diese Lande und schreien nach Erlösung. Ich bitte Euch, {name}, helft mir, sie beizusetzen.", sourceObjective = "Reinigt 8 zertrampelte Skelette auf dem Pfad des Ruhms mit dem heiligen Wasser der Draenei und kehrt dann zu Seher Kryv in der Ehrenfeste zurück.", progress = "Die Schreie scheinen irgendwie... schwächer geworden zu sein. Möge das Licht dafür sorgen, dass es nicht nur Wunschdenken ist.", completion = "Ihr habt meinen aufrichtigen Dank für Eure Mühen, {name}. Wenn auch noch viel zu tun ist, macht es mich froh, dass einige nun ihren wohlverdienten Frieden gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10048] = { id = 10048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Handvoll Magiestaub", description = "Ich brauche Staub, aber nicht irgendeinen Staub.\n\nDie königlichen Teromotten, die in den Wäldern in der Nähe leben, tragen magischen Staub auf ihren Flügeln, mit dem sie ihre Jäger betäuben. Diese Eigenschaft könnte ich mir zunutze machen. Die Arakkoaaugen, die Ihr mir gebracht habt, sind sehr widerspenstig. Mithilfe des Staubs werde ich diesen Widerstand lähmen. So kann ich dann endlich Deirom finden.\n\nIch brauche nicht viel davon, vielleicht ein halbes Dutzend oder so.", sourceObjective = "Sammelt 7 Handvoll besänftigender Staub für Andarl in Allerias Feste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10049] = { id = 10049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Handvoll Magiestaub", description = "Ich brauche Staub, aber nicht irgendeinen Staub.\n\nDie königlichen Teromotten, die in den Wäldern in der Nähe leben, tragen magischen Staub auf ihren Flügeln, mit dem sie ihre Jäger betäuben. Diese Eigenschaft könnte ich mir zunutze machen. Die Arakkoaaugen, die Ihr mir gebracht habt, sind sehr widerspenstig. Mithilfe des Staubs werde ich diesen Widerstand lähmen. So kann ich dann endlich Dugar finden.\n\nIch brauche nicht viel davon, vielleicht ein halbes Dutzend oder so.", sourceObjective = "Sammelt 7 Handvoll besänftigenden Staubs für Kurgatok in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10050] = { id = 10050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerschütterliche Seelen", description = "Am Ende unserer Invasion wurde das Rüstlager im Süden von den heimtückischen Todesrittern der Horde angegriffen. Diese bösartigen Schemen haben die Verteidiger des Rüstlagers verflucht und ihre Seelen zwischen dem Reich der Lebenden und dem der Toten gefangen.\n\nDiese ehrwürdigen Seelen müssen befreit werden! Ich bitte Euch, {name}, beendet das Leid meiner Kameraden, denn ich bringe es nicht selbst übers Herz, sie zu töten.", sourceObjective = "Ehrenwache Wesilow möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberer und 5 unerschütterliche Ritter beim Expeditionsrüstlager im Süden tötet.", completion = "Die Söhne sind Euch für Eure Mühen dankbar, auch wenn nur wenige über das Rüstlager sprechen möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10051] = { id = 10051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Posten der Feuerschwingen!", description = "Was für ein Glück, dass Ihr hier seid!\n\n{class}, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit von Allerias Feste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!\n\nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!", sourceObjective = "Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Hauptmann Auric Sonnenjäger in Allerias Feste in den Wäldern von Terokkar.", completion = "Isla Sternenmähne ist gerade gegangen, aber sie hat mir einen vollständigen Bericht über die Vorkommnisse im Posten der Feuerschwingen gegeben. Verständlich, dass sie über die Geschehnisse beim Cenariusdickicht sehr bestürzt ist. Garstige Blutelfen!\n\nSie hat mir gesagt, dass Ihr die entscheidende Rolle bei ihrer Rettung gespielt habt, damit wir diese Informationen erhalten. Allerias Feste steht tief in Eurer Schuld.\n\nBitte, nehmt im Namen aller dieses Geschenk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10052] = { id = 10052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Posten der Feuerschwingen!", description = "Was für ein Glück, dass Ihr hier seid!\n\n{class}, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit der Steinbrecherfeste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!\n\nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!", sourceObjective = "Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terokkar.", completion = "Isla Sternenmähne ist gerade gegangen, aber sie hat mir einen vollständigen Bericht über die Vorkommnisse im Posten der Feuerschwingen gegeben. Verständlich, dass sie über die Geschehnisse beim Cenariusdickicht sehr bestürzt ist.\n\nSie hat mir gesagt, dass Ihr die entscheidende Rolle bei ihrer Rettung gespielt habt, damit wir diese Informationen erhalten. Die Steinbrecherfeste steht tief in Eurer Schuld.\n\nBitte, nehmt im Namen aller dieses Geschenk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10053] = { id = 10053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor bewältigen", description = "Es ist unerlässlich, dass wir den Vorteil, den wir durch Euren Sieg über Nekrogg errungen haben, ausnutzen. Wenn wir Glück haben, hat die Führung in Zeth'Gor noch nichts von Nekrogg erfahren.\n\nDie Knochenmalmer in Zeth'Gor werden normalerweise von Grillok \"Finsterauge\" in die Schlacht geführt. Findet ihn in seinem Lager, einer Höhle im Felsen unter dem Außenposten, und tötet ihn. Durchsucht die Höhle nach den Schlachtplänen der Höllenorcs, wenn er tot ist. Wir dürfen nicht überrascht werden.", sourceObjective = "Tötet Grillok \"Finsterauge\" und durchsucht seinen Unterschlupf nach den Angriffsplänen des Blutenden Auges.", sourceObjectiveStatus = "unverified-source-field" }
quests[10054] = { id = 10054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohende Verdammnis", description = "Eine schnelle Überprüfung der Pläne zeigt, dass der Anführer von Zeth'Gor, Kriegsherr Morkh, das Genie hinter den Angriffen, die von Knochenmagier Warlor geleitet werden, ist. Auf der Karte sind mehr als nur Morkhs Streitkräfte zu sehen.\n\nDie Pläne deuten an, dass die Streitkräfte der Knochenmalmer bewaffnet und zusammen mit den Kräften der Höllenfeuerzitadelle bereit für einen Angriff auf die Ehrenfeste sind.\n\nEs bleibt keine Zeit, um Leutnant Amadi zu informieren. Ihr müsst die Knochenmalmer aufhalten, bevor sie ihren Angriff starten können!", sourceObjective = "Tötet 15 Grunzer des Blutenden Auges, 10 Nekrolyten des Blutenden Auges, 5 Peons des Blutenden Auges und Kriegsherr Morkh. Meldet Euch danach bei Leutnant Amadi im westlichen Turm der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10055] = { id = 10055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts verkommen lassen!", description = "Verstärkung ist gut, aber ich sehe nicht, dass sie irgendwelche Karren mit Barren oder Holz durch die Gegend ziehen.\n\nSchaut Euch um, Freund. Die Bäume sind knapp und die Minen voller Legionsabschaum.\n\nMir gehen die Vorräte aus. Ich versuche schon, sie, wo ich kann, zu ersetzen. Aber so langsam müssen wir anfangen, alles, was wir bekommen können, wiederzuverwenden.\n\nAm südlichen Ende des Pfads des Ruhms steht ein Haufen alter Belagerungsmaschinen 'rum. Ein paar der Teile kann man immer noch verwenden. Habt Ihr Lust, mir bei einer kleinen Wiederverwertungsaktion zu helfen?", sourceObjective = "Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Dumphry in der Ehrenfeste.", progress = "Habt Ihr ein wenig wiederverwertbares Material unter all dem Staub, der Asche und der Kohle finden können?", completion = "Das hier ist in einem besseren Zustand, als ich befürchtet habe. Sicher, es wird eine Weile dauern bis der ganze Rost und Zunder entfernt ist, aber ich kann mich nicht beklagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10056] = { id = 10056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte des Blutenden Auges", description = "Die orcischen Ruinen von Zeth'Gor im Südosten dienen als Basislager für die immer weiter steigende Flut von Höllenorcs, die aus der Höllenfeuerzitadelle strömt.\n\nDie Söhne Lothars haben sie eine Zeitlang bekämpft, und ich würde ihre Geschichten nicht glauben, wenn ich diese Höllenorcs nicht mit eigenem Auge gesehen hätte.\n\nEtwas hat sie verändert, sie größer gemacht. Ich habe so etwas noch nie gesehen. Wir müssen alles in unserer Macht Stehende tun, um zu verhindern, dass sie noch stärker werden. Geht nach Zeth'Gor und zerstört sämtliche Vorräte, die Ihr dort finden könnt.", sourceObjective = "Zerstört 6 Stapel Vorräte des Blutenden Auges und meldet Euch dann bei Leutnant Amadi in der Ehrenfeste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10057] = { id = 10057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den Anführern", description = "Trotz Eurer Bemühungen haben wir immer noch Probleme bei der Expeditionsrüstkammer. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet.\n\nVielleicht gehen wir die Sache falsch an. In meiner Vision habe ich gesehen, dass jeder Geist eine Verbindung zu den Ruinen hat, aber was ist, wenn eine Verbindung zu ihren Anführern besteht?\n\nErzmagier Xintor und Feldkommandant Thalvos standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.", sourceObjective = "Besiegt die Geister von Erzmagier Xintor und Feldkommandant Thalvos und kehrt dann zu Ehrenwache Wesilow im Turm nordwestlich der Ehrenfeste zurück.", completion = "Wir können nur hoffen, dass die Geister der Fußsoldaten mit dem Verschwinden der Geister ihrer Offiziere zur Ruhe kommen. Ich danke Euch ein weiteres Mal für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10058] = { id = 10058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein altes Geschenk", description = "<Der Blick des Priesters wandert langsam von seiner Tasse zu Euch.>\n\nHabt Ihr nichts Besseres zu tun, als einen Mann von seiner Tasse fernzuhalten?\n\nAch, was soll's. Ich bin der Meinung, dass Neuankömmlinge ein gutes Zeichen sind. Was würde Turalyon davon halten?\n\nIch erinnere mich noch an den Tag unserer Abreise, als ich ihm die Geheimnisse des Lichts gab. Während des Feldzugs und den folgenden Jahren hat er nicht einen einzigen Tag vergessen, seinen Mannen einen Abschnitt daraus vorzulesen.\n\nAls er uns wieder verließ, gab er mir das Buch zurück, damit ich bis zu seiner Rückkehr darauf aufpasse, aber ich Dummkopf dachte, es sei in meinem Quartier südlich der Waffenkammer sicher...", sourceObjective = "Besorgt die Geheimnisse des Lichts und bringt das Buch zu Vater Malgor Devidicus in der Ehrenfeste zurück.", progress = "Ich dachte, ich hätte Euch gesagt, dass Ihr mich nicht stören sollt. Was gibt's?", completion = "Ist es das? Kaum zu glauben, dass es die Schlacht überlebt hat. Die Gegebenheiten in den Ruinen waren nicht gerade gut für das Buch, aber ich bin dennoch froh, dass ich es wiederhabe.\n\nEs ist das einzige Zeichen, das ich von Turalyon habe.\n\n<Vater Devidicus scheint mit den Tränen zu kämpfen.>\n\nWenn man so lange Zeit Seite an Seite gekämpft hat, steht man sich noch näher als die eigene Familie.", sourceObjectiveStatus = "unverified-source-field" }
quests[10059] = { id = 10059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor bewältigen", description = "Es ist unerlässlich, dass wir den Vorteil, den wir durch Euren Sieg über Nekrogg errungen haben, ausnutzen, {name}. Wenn wir Glück haben, hat die Führung in Zeth'Gor noch nichts von Nekrogg erfahren.\n\nDie Knochenmalmer in Zeth'Gor werden normalerweise von Grillok \"Finsterauge\" in die Schlacht geführt. Findet ihn in seinem Lager, einer Höhle im Felsen unter dem Außenposten, und tötet ihn. Durchsucht die Höhle nach den Schlachtplänen der Höllenorcs, wenn er tot ist. Thrallmar darf nicht überrascht werden.", sourceObjective = "Tötet Grillok \"Finsterauge\" und durchsucht seinen Unterschlupf nach den Angriffsplänen des Blutenden Auges.", sourceObjectiveStatus = "unverified-source-field" }
quests[10060] = { id = 10060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohende Verdammnis", description = "Eine schnelle Überprüfung der Pläne zeigt, dass der Anführer von Zeth'Gor, Kriegsherr Morkh, das Genie hinter den Angriffen, die von Knochenmagier Warlor geleitet werden, ist. Auf der Karte sind mehr als nur Morkhs Streitkräfte zu sehen.\n\nDie Pläne deuten an, dass die Streitkräfte der Knochenmalmer bewaffnet und zusammen mit den Kräften der Höllenfeuerzitadelle bereit für einen Angriff auf Thrallmar sind. Ihr müsst die Knochenmalmer aufhalten, bevor sie ihren Angriff starten können!", sourceObjective = "Tötet 15 Grunzer des Blutenden Auges, 10 Nekrolyten des Blutenden Auges, 5 Peons des Blutenden Auges und Kriegsherr Morkh. Meldet Euch danach bei Steingardist Ambelan im Rückenbrechergrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10061] = { id = 10061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unerschütterlichen", description = "Als die Höllenorcs der Knochenmalmer die Expeditionswaffenkammer angegriffen haben, fiel unsere Garnison sehr schnell. Es war eine kurze, blutige und grausame Schlacht. Es gab keine Überlebenden.\n\nObwohl wir die Toten begraben und uns an den Höllenorcs gerächt haben, spuken die Geister der Gefallenen immer noch in den Ruinen. Seit Kurzem habe ich Visionen, in denen diese Geister zu einer Gefahr für Thrallmar werden.\n\nEs gibt nur einen Weg, um die Geister zur Ruhe zu bringen - Ihr müsst sie im Kampf besiegen.", sourceObjective = "Grelag möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberer und 5 unerschütterliche Ritter bei der Expeditionsrüstkammer südlich der Ehrenfeste tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10062] = { id = 10062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den Anführern", description = "Trotz Eurer Bemühungen haben wir immer noch Probleme bei der Expeditionsrüstkammer. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet.\n\nVielleicht gehen wir die Sache falsch an. In meiner Vision habe ich gesehen, dass jeder Geist eine Verbindung zu den Ruinen hat, aber was ist, wenn eine Verbindung zu ihren Anführern besteht?\n\nErzmagier Xintor und Feldkommandant Thalvos standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.", sourceObjective = "Besiegt die Geister von Erzmagier Xintor und Feldkommandant Thalvos und kehrt dann zu Grelag im Rückenbrechergrat zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10063] = { id = 10063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscherliga, für Gnome geeignet?", description = "Kindermädchen! Glaubt Ihr das?\n\nSie haben mich von einer viel versprechenden Grabung abgezogen und mit Odesyus' Expedition losgeschickt, um das Kindermädchen für diesen kleinen Gnom zu spielen!\n\nIch habe noch nie von einem Gnom gehört, der Ausgrabungsleiter werden wollte, Ihr etwa?\n\nAnscheinend nehmen wir jetzt auch Gnome und dieser ist wohl besonders von Murlocs fasziniert!\n\nNun gut, er ist losgezogen und hat sich in einem alten Schildkrötenpanzer an der nördlichen Küste der Insel eingerichtet. Geht und seht selbst, wenn Ihr mir nicht glaubt!", sourceObjective = "Zieht los und sucht nach Klopper Knacksklug, der sich in einem alten Schildkrötenpanzer an der Küste nördlich der Blutwacht eingerichtet hat.", completion = "Dachte ich's mir doch! Dieser mürrische alte Zwerg sollte mir eigentlich beim Transport meiner Ausrüstung und dem Sammeln von Daten helfen, aber stattdessen sitzt er nur in dem komischen Draeneidorf herum und betrinkt sich sinnlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[10064] = { id = 10064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht zu der Hand", description = "Die Hand von Argus hat bei Verteidigers Ruh' einen Vorposten eingerichtet, allerdings sind sie dort den Blutelfen und auch der Wildnis zahlenmäßig weit unterlegen. Ihrem Posten droht ohne Verstärkung bald der Fall und somit würden wir die Ereignisse bei der Vektorspule nicht länger im Auge behalten können.\n\nErstattet Späherin Jorli bei Verteidigers Ruh' im Nordwesten Bericht und bietet ihr Eure Hilfe an, {name}.", sourceObjective = "Erstattet Späherin Jorli bei Verteidigers Ruh' Bericht.", completion = "Ich habe gehofft, dass die Blutwacht uns Verstärkung schicken würde, sobald man dort weiß, mit wem wir es hier zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10065] = { id = 10065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schneise schlagen", description = "Während unserer Mission, die Sonnenfalken und ihr Portal auszukundschaften, wurde ich ernsthaft verletzt. Späherin Loryi konnte glücklicherweise die Blutung stillen und sucht gerade nach einem Weg, um mich zur Blutwacht zu bringen.\n\nUnser Problem liegt allerdings darin, dass wir unsere Stellung hier verlassen müssen, um eine sichere Rückkehr garantieren zu können.\n\nSobald wir diesen sicheren Grund verlassen, werden uns Felshetzer anfallen. Wenn Ihr ein paar der wütenden Felshetzer aus dem Weg räumen könntet, würden wir höchstwahrscheinlich sicher an unser Ziel gelangen.", sourceObjective = "Tötet 10 wütende Felshetzer und kehrt zu Späherin Jorli bei Verteidigers Ruh' zurück.", completion = "Es sieht da draußen schon etwas besser aus, ich bin mir jedoch noch immer nicht sicher, ob es besser wäre, hier auf medizinische Versorgung zu warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10066] = { id = 10066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles im Griff", description = "Wir wagen es nicht, unseren Posten zu verlassen oder uns zu weit von Verteidigers Ruh' zu entfernen, {race}. Die mutierten Kreaturen, die sich in der unmittelbaren Nähe der Vektorspule aufhielten, wurden schwerwiegend von der Energie beeinflusst, die den Kristallen entweicht.\n\nDie mutierten Greifer scheinen bis zu einem gewissen Grad Empfindungen entwickelt zu haben. Sie haben gelernt, tückische Fallen zu erschaffen, aufzustellen und zu verbergen, damit sich selbst die umsichtigsten Kämpfer darin verfangen.\n\nWir werden niemals gegen die Sonnenfalken vorgehen können, wenn wir ständig auf unsere Schritte Acht geben müssen. Packt das Problem bei der Wurzel, {name}.", sourceObjective = "Tötet 8 mutierte Greifer und meldet Euch bei Verteidigerin Corin bei Verteidigers Ruh'.", completion = "Gut gemacht, {name}. Ohne die Tücken der Greifer, wird es jetzt wesentlich einfacher sein, Verstärkung von der Blutwacht zu erhalten oder Angriffe gegen die Sonnenfalken zu starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10067] = { id = 10067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Wassergeister", description = "Die meisten der Kreaturen, die von der Energie der Kristalle berührt wurden, wurden auf die gleiche Art verdorben: seltsame Male auf ihrer Haut, aggressiveres Verhalten und kleine Kristallsplitter in ihren Körpern. Wie dem auch sei, die besudelten Wassergeister im Norden scheinen sich vollständig in Kristall zu verwandeln.\n\nIch habe bis jetzt noch nichts gesehen, was derart auf die Kristalle reagiert hat. Als wir den Besudelten Teich untersucht haben, haben sie sich als besonders gefährlich herausgestellt. Wir müssen sie loswerden, bevor die Sonnenfalken sie als neue Energiequelle missbrauchen können.", sourceObjective = "Tötet 6 besudelte Wassergeister und kehrt zu Verteidigerin Corin bei Verteidigers Ruh' zurück.", completion = "Gut gemacht, {name}. Es ist besonders wichtig, dass wir keine Möglichkeit außer Acht lassen, die den Sonnenfalken weiterhin ihre Existenz sichern könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10068] = { id = 10068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostnova", description = "Je stärker Ihr werdet, desto mehr entwickelt sich Eure Verbindung zum Arkanen und Ihr findet Zugang zu neuen Zaubern.\n\n\n\nMacht Euch auf, um noch stärker zu werden. Und wenn Ihr etwas Neues gelernt habt, kommt Ihr zurück, um es mir zu demonstrieren.", sourceObjective = "Erreicht Stufe 3 und erlernt Frostnova. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt Frostnova 2-mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[10069] = { id = 10069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wege des Lichts", description = "Es ist an der Zeit, Eure erste Lektion in den Wegen des Lichts zu lernen, {name}. Durch das Schlagen von Schlachten, werdet Ihr dem Licht näher kommen und Ihr werdet neue Fähigkeiten erlernen.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Kehrt dann zu mir zurück, demonstriert sie mir und wir werden Eure Ausbildung fortsetzen.", sourceObjective = "Erreicht Stufe 3, um 'Siegel des Befehls' zu erlernen. Wirkt 'Siegel des Befehls' auf Euch selbst, sucht eine Trainingsattrappe auf und trefft sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[10070] = { id = 10070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuverlässiger Schuss", description = "Und nun ist es an der Zeit für Eure erste Lektion.\n\nSobald Ihr mehr Erfahrung gesammelt habt, werdet Ihr neue Techniken entdecken.\n\nGeht, sammelt mehr Erfahrung und erlernt Eure erste neue Fähigkeit. Wenn Ihr das getan habt, sucht eine der Trainingsattrappen draußen auf und probiert sie daran aus.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Findet eine Trainingsattrappe vor dem Sonnenturm und übt daran fünfmal 'Zuverlässiger Schuss'.", sourceObjectiveStatus = "unverified-source-field" }
quests[10071] = { id = 10071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden", description = "Je stärker Ihr werdet, desto mehr Tricks werdet Ihr herausfinden können.\n\nEine der ersten Techniken, die Ihr lernen werdet, ist wahrscheinlich das Ausweiden des Gegners, nachdem Ihr schon ein paar erste Treffer gelandet habt.\n\nSorgt dafür, dass Ihr etwas Erfahrung sammeln könnt, lernt diese Technik und dann übt sie weiter an einer der Trainingsattrappen da draußen.", sourceObjective = "Erreicht Stufe 3 und erlernt das Ausweiden. Macht dann eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt Ausweiden 3-mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[10072] = { id = 10072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Je mehr Fertigkeiten Ihr erlangt, desto größer wird die Auswahl der Euch zur Verfügung stehenden Kräfte.\n\nIch möchte, dass Ihr loszieht, noch mehr Erfahrung sammelt und einen neuen Zauber entdeckt. Wenn Euch dies gelungen ist, kommt zurück und beweist mir Euer neues Wissen.", sourceObjective = "Erreicht Stufe 3, um das Schattenwort: Schmerz zu erlernen. Wirkt es dann 5-mal auf die Trainingsattrappen in der Nähe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10073] = { id = 10073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Mittlerweile habt Ihr die Gerüchte über unsereins, die Hexenmeister, gehört. Schenkt ihnen keine Beachtung; es sind diejenigen, die neidisch auf unsere furchteinflößende Macht sind, die solche Lügen verbreiten.\n\nWenn Ihr Erfahrungen sammelt, werdet Ihr die Mysterien entschlüsseln, die es Euch erlauben, die Teufelsenergien zu kontrollieren.\n\nGeht, setzt Euren Weg fort, bis Ihr eine neue Technik entdeckt habt. Ich möchte, dass Ihr diesen neuen Zauber an den Trainingsattrappen vor dem Sonnenturm ausprobiert.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt daran fünfmal das Wirken von 'Verderbnis'.", sourceObjectiveStatus = "unverified-source-field" }
quests[10074] = { id = 10074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", description = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, das Ihr bei den Rüstmeistern eintauschen könnt.", sourceObjective = "Bringt 10 Kristallpulverproben von Oshu'gun zu Forschungsleiterin Amereldine in Halaa.", progress = "Der Erdkern dieser Gegend ist vom Kristallpulver des Bergs durchdrungen.", completion = "Wundervoll, {name}. Das wird uns in unserem Kampf gegen den Abschaum der Allianz helfen, der sich hier in der Scherbenwelt breitgemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10075] = { id = 10075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", progress = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt." }
quests[10076] = { id = 10076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", description = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", sourceObjective = "Bringt 10 Kristallpulverproben von Oshu'gun zu Forschungsleiter Kartos in Halaa.", progress = "Das Kristallpulver des Bergs ist vom Erdenkern dieser Gegend durchdrungen.", completion = "Wundervoll, {name}. Das wird uns in unserem Kampf gegen den Abschaum der Horde helfen, der sich hier in der Scherbenwelt breitgemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10077] = { id = 10077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", progress = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt." }
quests[10078] = { id = 10078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unerwünschten zerstören", description = "Jetzt, da unsere Bergungsaktion ins Rollen gekommen ist, ist es an der Zeit, die zweite Phase unseres Plans einzuläuten.\n\nAm Pfad des Ruhms hat die Horde immer noch ihre alten Klingenwerfer postiert. Lasst Euch von Ihrem Alter nicht täuschen, {name}, sie sind immer noch sehr gefährlich. So sehr wir auch versuchen, alles zurückzuerobern, was wir können, können wir nicht erwarten, dass die Horde ihre Waffen einfach so abbaut.\n\nNehmt diese Fackel und zündet ihre übriggebliebene Belagerungsausrüstung an. Ich werde die Sicherheit der Ehrenfeste nicht dem Zufall überlassen.", sourceObjective = "Zündet die Klingenwerfer der Horde mit der flammenden Fackel am Pfad des Ruhms an. Kehrt dann mit der flammenden Fackel zu Dumphry in der Ehrenfeste zurück.", completion = "Das nenne ich Einsatz!\n\nIch bin froh, dass wir endlich Unterstützung erhalten haben, aber ich bin nicht so sicher, ob sie die richtige Einstellung gegenüber der Horde haben. Dort, wo ich herkomme, ist jeder, der eine Waffe auf Euch richtet, ein Feind und muss vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10079] = { id = 10079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt diese Mine zum Beben!", description = "Die Mine wurde von diesem Gan'argpack überrannt!\n\nSie haben nicht nur meine Arbeiter aus den Tunneln getrieben, sondern hämmern auch noch Tag und Nacht darin herum! Und jetzt sitzt mir auch noch Danath im Rücken! Sagt, er würde mir meine Bierration streichen, wenn ich mich nicht bald darum kümmere!\n\nKeiner der Minenarbeiter will dort hineingehen, und die Wächter sind zu sehr damit beschäftigt, sich vollaufen zu lassen.\n\nIch flehe Euch an, {name}, helft mir! Danath mag mir meinen Stolz nehmen, aber niemals mein Bier!", sourceObjective = "Tötet 12 Pioniere der Gan'arg und kehrt dann zu Großknecht Biggums zurück.", completion = "Bei Bronzebarts bronzenem... Bart, Ihr habt es geschafft! Ihr seid ein Held, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10080] = { id = 10080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager der Legion", description = "Ich habe mit Humphry gesprochen. Er hat Euch sicher gesagt, dass die Heimsuchung der Mine ein kleineres Übel ist, aber ich bin der Meinung, dass es sogar ein sehr großes Übel ist.\n\nNordöstlich des Hordenpostens Thrallmar arbeiten die Diener der Legion Tag und Nacht an etwas, aber was?\n\nKeiner der Späher, die ich dorthin geschickt habe, ist je zurückgekommen. Die Zeit der Zurückhaltung ist vorbei, {name}. Begebt Euch in das Konstruktionslager: Zorn und findet heraus, was die Legion vorhat.", sourceObjective = "Tötet 10 Diener der Gan'arg, 5 Legionäre des Konstruktionslagers und 5 Schwestern des Leids. Durchsucht danach des Konstruktionslager: Zorn nach einem Hinweis auf die Absichten der Legion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10081] = { id = 10081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutter Kashur treffen", description = "Erschreckt Euch nicht über das, was Ihr sehen werdet, wenn die Wirkung eintritt. Diese Geister sind überall um uns herum - immer. Der Trank erlaubt Euch nur, sie zu verstehen und zu sehen. Ihr werdet seine Wirkung brauchen, wenn Ihr mit Mutter Kashur sprecht.\n\nIhr findet sie ein gutes Stück im Südwesten beim Ahnengrund.", sourceObjective = "Großmutter Geyah möchte, dass Ihr mit Mutter Kashur sprecht.", completion = "Der Trank, den Ihr zu Euch genommen habt, hat keine echte Wirkung. Ihr könnt einen Geist nur sehen, wenn er es zulässt. Der Trank ist nur ein Symbol Eures Glaubens und Eurer Hingabe. Es war ein Test. Und Ihr habt ihn bestanden...", sourceObjectiveStatus = "unverified-source-field" }
quests[10082] = { id = 10082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die aufgebrachten Ahnen", description = "Seht Ihr, wie sie unter uns wandeln? Der Ahnengrund ist normalerweise sehr ruhig und friedlich.\n\nIn letzter Zeit haben sich die Geister der Ahnen jedoch erhoben und sind sehr aufgebracht. Etwas muss sie sehr stören. Wir müssen herausfinden, was das sein könnte, aber zuerst müssen wir die direkte Bedrohung beseitigen.\n\nDie Geister, die Ihr hier seht, sind nicht wirklich unsere Ahnen, sondern ein Abbild ihrer gegenwärtigen Lage. Ihr müsst die aufgebrachten Orcgeister zerstören. Tut dies und kehrt dann zu mir zurück.", sourceObjective = "Mutter Kashur möchte, dass Ihr 8 aufgebrachte Orcgeister tötet.", completion = "Es ergibt keinen Sinn. Sie erheben sich weiter. Es muss etwas Heimtückischeres dahinter stecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10083] = { id = 10083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pläne der Legion", description = "Ihr schreibt die leuchtenden Glyphen, die in den Boden geritzt wurden, ab, aber ohne die zweite Hälfte ergibt das Diagramm keinen Sinn.\n\nFeldmarschall Rohamus sprach von einem weiteren Konstruktionslager im Westen, dem Konstruktionslager: Bosheit. Vielleicht bewahrt die Legion dort die zweite Hälfte der Pläne auf?\n\nWenn die Legion etwas in Massenproduktion herstellt, macht es Sinn, dass die Teile in verschiedenen Lagern zusammengebaut werden.", sourceObjective = "Besorgt die Pläne des Konstruktionslagers: Bosheit und bringt sie zu Feldmarschall Rohamus im Expeditionsposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10084] = { id = 10084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Mageddon", description = "Mit den Fähigkeiten der Ingenieure der Mo'arg und der endlosen Menge an Gan'argdienern werden sie sicher schneller Teufelshäscher produzieren, als wir in Nethergarde Bescheid geben können.\n\nWir haben keine andere Wahl als sie so schnell wie möglich anzugreifen. Wir können keine Männer von der Ehrenfeste für diesen Angriff abziehen, das wäre purer Selbstmord! Die Höllenorcs und die Horde würden uns bei dem kleinsten Anzeichen von Schwäche überrennen.\n\nDie Ehrenfeste steht nun seit 20 Jahren, und wir haben nicht vor, sie jetzt zu verlieren.", sourceObjective = "Tötet Nachtlord Malphas im Konstruktionslager: Mageddon und meldet Euch dann bei Truppenkommandant Danath Trollbann in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10085] = { id = 10085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Ahnen", description = "Ich brauche Euch, um zu den Dörfern unserer Ahnen zu reisen, {name}. Geht zu jedem einzelnen und schaut, ob unsere Vorfahren noch da sind.\n\nGeht zum Sonnenwindposten im Norden, zu den Ruinen des Lachenden Schädels ganz im Norden bei den Bergen, besucht Garadar im Nordosten und zuletzt die Ruinen des Blutenden Auges an der Grenze zwischen Nagrand und den Wäldern von Terokkar im Osten.\n\nBerichtet mir, sobald Ihr die Ahnen in ihrem Zuhause beobachtet habt.", sourceObjective = "Mutter Kashur im Ahnengrund in Nagrand möchte, dass Ihr den Sonnenwindposten, die Ruinen des Lachenden Schädels, Garadar und die Ruinen des Blutenden Auges besucht.", completion = "Das ist sehr beunruhigend. Ihr sagt, keiner der Ahnen war in seinem Dorf? Sie gehen alle nach Süden?", sourceObjectiveStatus = "unverified-source-field" }
quests[10086] = { id = 10086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich arbeite... für die Horde!", description = "Könnt Ihr das fassen? Diese Orcs haben mich angeheuert, um ihre beschädigten Befestigungsanlagen abzustützen und Sprengstoff herzustellen. Ist das nicht ein Traumjob? Nur zu schade, dass uns die Materialien ausgehen, aber ein gewitzter Goblin wie ich weiß sich immer zu helfen!\n\nKönntet Ihr mich dabei unterstützen? Ich benötige ein wenig gebrauchtes Holz und Metall von den zerstörten Belagerungsmaschinen entlang des Pfads des Ruhmes. Geht dorthin und sammelt, aber gebt auf diese rothäutigen Orcs Acht!\n\nWenn Ihr fertig seid, kommt zurück und holt Euch eine fette Belohnung ab!", sourceObjective = "Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Megzeg Knaxknöchel in Thrallmar.", progress = "Wie geht es mit der Sammelaktion voran? Habt Ihr etwas Wiederverwertbares finden können?", completion = "Die Materialien sind ausgezeichnet! Vielleicht ein wenig verbogen oder angesengt, aber ich habe mich noch nie von minderwertigem Material aufhalten lassen, wenn es darum ging, Präzisionssprengstoff herzustellen!\n\nDanke, {name}. Ihr habt wirklich ein Händchen exquisiten Müll!", sourceObjectiveStatus = "unverified-source-field" }
quests[10087] = { id = 10087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zündet es an... für die Horde!", description = "Ich bin ein glücklicher, glücklicher Goblin! Ich darf hier Sprengstoff und Killermaschinen herstellen in der Gewissheit, dass sie sofort bei wichtigen Missionen eingesetzt werden!\n\nWo wir gerade von Missionen sprechen, ich habe einen Befehl aus Thrallmar erhalten: Verbrennt die Kanonen der Allianz entlang des Pfads des Ruhms... die Kanonen, die gefährlich auf die Befestigungsanlagen der Horde gerichtet sind. Nehmt diese Fackel und begebt Euch zu jeder Kanone. Zündet die Fackel an und bestaunt den Funkenflug!", sourceObjective = "Zündet die östliche und die westliche Kanone der Allianz mit der flammenden Fackel an und kehrt danach zu Megzeg Knaxknöchel in Thrallmar zurück.", progress = "Ich habe nach Zeichen von brennenden Kanonen Ausschau gehalten - Rauchschwaden oder den Schreien brennender Höllenorcs...\n\nHattet Ihr Erfolg mit Eurem Auftrag?", completion = "Dachte ich's mir doch! Ich konnte die Zerstörung von hier aus zwar nicht richtig sehen, aber ich kann sie mir redlich vorstellen! Ausgezeichnet!\n\nGut gemacht, {name}. Das oberste Kommando von Thrallmar wird sich freuen, von Eurem Erfolg zu hören!", sourceObjectiveStatus = "unverified-source-field" }
quests[10088] = { id = 10088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt diese Mine zum Beben!", description = "Die Mine wurde von diesem Gan'argpack überrannt, und zu allem Übel sind die Peons der Meinung, dass jetzt die richtige Zeit für ein Schläfchen ist! Ich weiß nicht, wie sie bei all dem Lärm aus der Mine schlafen können, aber das ist mein geringstes Problem.\n\nWenn wir dieses Gan'arggesindel nicht bald loswerden, wird Thrallmars Nachschub an Erzen und anderen Materialien abgeschnitten. Ich habe schon Wachkommandant Krunk um Hilfe gebeten, aber er sagt, dass er keine Männer schicken kann, solange die Stadt angegriffen wird. Könnt Ihr mir helfen?", sourceObjective = "Tötet 12 Pioniere der Gan'arg und kehrt dann zu Großknecht Razelcraz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10089] = { id = 10089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager der Legion", description = "Thrallmar steht seit seiner Gründung unter Beschuss der Lager der Legion. Bis jetzt haben wir standhalten können, aber die Situation wird von Tag zu Tag schlimmer.\n\nSchattenjäger Ty'jin hat mehrere Versuche unternommen, mehr über die Lager herauszufinden, aber keiner seiner Späher ist je zurückgekehrt.\n\nDie Zeit für Zurückhaltung ist vorbei, {name}. Begebt Euch ins Konstruktionslager: Zorn und findet heraus, was die Legion vorhat.", sourceObjective = "Tötet 10 Diener der Gan'arg, 5 Legionäre des Konstruktionslagers und 5 Schwestern des Leids. Durchsucht danach des Konstruktionslager: Zorn nach einem Hinweis auf die Absichten der Legion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10090] = { id = 10090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pläne der Legion", description = "Ihr schreibt die leuchtenden Glyphen, die in den Boden geritzt wurden, ab, aber ohne die zweite Hälfte ergibt das Diagramm keinen Sinn.\n\nDie Glyphen verweisen darauf, dass ein weiteres Konstruktionslager im Westen, das Konstruktionslager: Bosheit, an dem Projekt beteiligt ist. Vielleicht bewahrt die Legion dort die zweite Hälfte der Pläne auf?\n\nWenn die Legion etwas wirklich Gewaltiges herstellt, macht es Sinn, dass die Teile in verschiedenen Lagern zusammengebaut werden.", sourceObjective = "Besorgt die Pläne des Konstruktionslagers: Bosheit und bringt sie zu Oberanführer Hun Stümmelfaust im Häschersturz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10091] = { id = 10091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeleninstrumente", description = "Pah! Sie haben mich gefoltert und versucht, etwas über die Verteidigungsanlagen von Shattrath aus mir herauszuquetschen.\n\nIch habe mich geweigert - da haben sie die anderen Spione an Höllenschlund verfüttert, und ich sollte der Nächste sein. Aber ich habe ihnen nichts verraten!\n\nSie sind wahnsinnig! Sie sind versessen darauf, dämonische Mächte zu beschwören, die sie auf gar keinen Fall kontrollieren können!\n\nSie benutzen besondere Seeleninstrumente, um ihre Seelensplitter herzustellen und ihre Beschwörungen noch mächtiger zu machen. Ihr müsst ihnen diese Instrumente stehlen!\n\nIch würde Euch ja begleiten, aber ich muss nach Shattrath zurück um der Spionagemeisterin des Unteren Viertels zu berichten.", sourceObjective = "Stehlt 5 Seeleninstrumente und bringt sie zu Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[10092] = { id = 10092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Mageddon", description = "Mit den Fähigkeiten der Ingenieure der Mo'arg und der endlosen Menge an Gan'argdienern werden sie sicher schneller Teufelshäscher produzieren, als wir in Orgrimmar Bescheid geben können.\n\nWir haben keine andere Wahl als sie so schnell wie möglich anzugreifen. Wir können keine Männer von Thrallmar für diesen Angriff abziehen, dann wären wir zu leicht angreifbar.\n\nEs gibt zu viele, die sich, ungeachtet der Allianz, nur zu gerne auf unseren ungeschützten Außenposten stürzen würden. Versagt nicht, {name}. Es hängt zu viel von Euch ab.", sourceObjective = "Tötet Nachtlord Malphas im Konstruktionslager: Mageddon und meldet Euch dann bei Oberanführer Hun Stümmelfaust im Häschersturz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10093] = { id = 10093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Telhamat", description = "Zum Glück ist der Pfad des Ruhms nicht das einzige Zeichen meines Volks in diesen Ländereien. Im Westen befinden sich immer noch ein paar unserer geheiligten Stätten, auch wenn einige von ihnen überrannt wurden.\n\nWährend Velen sich auf seine Reise nach Azeroth vorbereitete, haben diejenigen von uns, die hier bleiben sollten, versucht, sich wieder in unseren heiligen Orten niederzulassen.\n\nIm westlichen Teil der Höllenfeuerhalbinsel könnt Ihr beim Tempel von Telhamat eine kleine Gruppe von Draenei finden, die von Amaan dem Weisen angeführt werden. Ich bin mir sicher, dass er Euch gerne kennenlernen würde.", sourceObjective = "Sprecht mit Amaan dem Weisen beim Tempel von Telhamat im Westen der Höllenfeuerhalbinsel.", completion = "Ah, Ihr habt also Seher Kryv getroffen. Er ist ein weiser und begabter Mann, und seine Freunde sind auch meine Freunde.\n\nMacht es Euch gemütlich und stellt Euch den anderen vor, die diesen Tempel ihr Zuhause nennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10094] = { id = 10094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex des Blutes", description = "Es ist nun zwei Jahre her, dass die Beschwörung des Schattenrats dieses einst großartige Mausoleum explodieren und die Knochenwüste entstehen lies.\n\nJetzt befinden sie sich im Krieg mit einer unglaublich mächtigen Kraft im Inneren.\n\n{name}, Ihr müsst in das Schattenlabyrinth eindringen und herausfinden, wogegen sie kämpfen und ob es eine Gefahr für uns sein könnte. Unserer Spione haben berichtet, dass sie ein verbotenes Buch mit unheiligen Beschwörungen verwenden, bekannt als der Kodex des Blutes.\n\nSucht in ihm nach Antworten.", sourceObjective = "Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10095] = { id = 10095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Herz des Labyrinths", description = "Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren! Es hat die Explosion von Auchindoun verursacht und die Knochenwüste erschaffen.\n\nJetzt nur noch als Murmur bekannt, droht es, den Schattenrat zu überrennen und zu entkommen!\n\nNun, da der Großmeister und der Rest der Führung tot sind, seid Ihr die einzige Hoffnung der Scherbenwelt im Kampf gegen dieses Monster!\n\n{name}, tief in Eurem Herzen wisst Ihr, dass Ihr und Eure Freunde nicht versagen dürfen!", sourceObjective = "Vernichtet Murmur und informiert danach Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath über die Geschehnisse im Schattenlabyrinth.", sourceObjectiveStatus = "unverified-source-field" }
quests[10096] = { id = 10096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Sporloks", description = "Ikeyen hat mir erzählt, was ihm in diesen Höhlen widerfahren ist, und ich finde es einfach nur schrecklich!\n\nWisst Ihr, vielleicht sollten wir diesen armen Sporloks helfen. Ikeyen sagt, dass sie dort in der Funggorhöhle leben, aber die Marschenbestien sind kürzlich dort eingefallen.\n\nWarum geht Ihr nicht dort hin und schaut, dass Ihr ein paar von diesen Marschenbestien erlegt? Die Höhle ist ganz nah im Südwesten.", sourceObjective = "Tötet 10 Marschengräber und 10 Marschenlauerer und kehrt dann zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen zurück.", completion = "Gut! Diese Marschenbiester haben kein Recht, das Zuhause der Sporloks zu überfallen!\n\nEs wäre besser, wenn diese Tiere lernen würden, in Harmonie zu leben, aber wenn das nicht geht, müssen wir uns eben um die Situation kümmern!\n\nHier, bitte nehmt etwas hiervon als Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10097] = { id = 10097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder gegen Bruder", description = "Die Sethekk haben Skettis mit Fanfaren verlassen, als Auchindoun explodiert ist. Das war sicher ein Vorbote für die Ankunft unseres Meisters.\n\nMein Bruder, Syth, war einer ihrer Anführer und hat uns gesagt, dass es unsere Pflicht wäre, in die Tempelruinen zu gehen und unserem Gott zu begegnen.\n\nNachdem wir unser Lager in den Ruinen aufgeschlagen und sie die Sethekkhallen getauft hatten, kamen mir Zweifel an den Fähigkeiten meines Bruders und seines Verbündeten Ikiss.\n\nNach einiger Zeit hat mich Syth aus den Hallen geworfen und mir verboten, meine Schwester Lakka mitzunehmen. Helft Ihr mir, sie zu retten?", sourceObjective = "Tötet Dunkelwirker Syth in den Sethekkhallen und befreit Lakka. Kehrt zu Isfar außerhalb der Sethekkhallen zurück, wenn Ihr die Aufgabe abgeschlossen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10098] = { id = 10098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Erbe", description = "Mein Volk verehrt einen uralten Helden namens Terokk. Arakkoaküken erfreuen sich an den Geschichten über seine Taten und den Beschreibungen seines prächtigen Federkleids.\n\nEr lebte für hunderte von Jahren unter meinem Volk, doch eines Tages verschwand er urplötzlich, und ließ nur seine Maske, seinen Speer und seine Schriften zurück.\n\nDiese Relikte werden von den Arakkoa hoch verehrt, und es brach ihnen das Herz, als die Sethekk die Gegenstände bei ihrem Aufbruch aus Skettis verschleppten.\n\nIch habe alles, was ich über den Verbleib der Schriftrollen in den Hallen weiß, niedergeschrieben.", sourceObjective = "Bringt Terokks Maske, Terokks Federkiel und die Sage von Terokk zu Isfar außerhalb der Sethekkhallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10099] = { id = 10099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Genie", description = "Diese verfluchten Gan'arg wuseln immer noch in die Mine! Für jeden, den wir umbringen, scheinen zwei oder drei weitere aufzutauchen!\n\nIrgendwas in den Tiefen der Mine muss diese Menge steuern. Ihr scheint das letzte Mal ganz gut klargekommen zu sein, und das Licht weiß, dass Ihr <der/die> Einzige seid, <der/die> mutig genug ist, wieder in die Mine zu gehen. Findet heraus, wer für dieses Ärgernis verantwortlich ist und bestraft ihn dafür!", sourceObjective = "Sucht und tötet Z'kral in den Minen unter der Ehrenfeste und meldet Euch dann bei Großknecht Biggums zurück.", completion = "Ich bin froh, dass Ihr Euch um, um... wie sagtet Ihr hieß er noch gleich? Z'kral?\n\nEurer Beschreibung nach war es wohl mehr ein es als ein er. Nun ja, was zählt ist, dass es tot ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10100] = { id = 10100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Genie", description = "Versteht mich nicht falsch, {name}, ich bin sehr froh, dass Ihr Euch bereit erklärt habt, uns mit den Minen zu helfen, aber für jeden Pionier, den Ihr getötet habt, sind zwei neue dazugekommen.\n\nIch habe Wachkommandant Krunk schon die Ohren vollgeheult, aber er weigert sich immer noch, mir Hilfe zu schicken. Er murmelt immer irgendwas von Höllenebern. Wenn ich mir nicht so sicher wäre, dass er mich verprügeln würde, würde ich ihm sagen, dass jetzt nicht die Zeit ist, um an Rippchen zu denken!\n\nWie auch immer, es sieht so aus, als ob irgendjemand tief in den Minen die ganze Sache steuert. Findet ihn und tötet ihn!", sourceObjective = "Sucht und tötet Urga'zz in den Minen unter Thrallmar und kehrt dann zu Großknecht Razelcraz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10101] = { id = 10101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Geister sprechen", description = "Oshu'gun, der diamantene Berg, war einst ein heiliger Ort meines Volkes. Dort versammelten sich die Klans jedes Jahr, um das Frühlingsfest zu feiern. Dort kommunizierten unsere Schamanen mit unseren altehrwürdigen Vorfahren. Er bildete das Zentrum unserer Kultur - bis die Schatten uns übernahmen. Als die Klans zu einer Horde wurden, verstummten die Geister von Oshu'gun. Unsere Vorfahren haben sich von uns abgewendet.\n\nDoch nun werden sie in ihrer Ruhe gestört. Reist nach Oshu'gun und findet heraus, was die Geister beunruhigt.", sourceObjective = "Mutter Kashur im Ahnengrund in Nagrand bittet Euch, Eurer Vision auf den Grund zu gehen. Findet K'ure in Oshu'gun.", completion = "<Eine sanfte, melodische Stimme erklingt in Eurem Kopf.> Ich bin K'ure von den Naaru, {name}. Ihr steht hier im Herzen meines alten Schiffs.\n\nOshu'gun, wie die Orcs es genannt haben, ist das Schiff, mit dem die Draenei zuerst auf diese Welt gekommen sind. Obwohl wir schon vor hunderten von Jahren hier vom Himmel gefallen und abgestürzt sind, sind meine Energien immer noch in diesen Trümmern gefangen. Leider bin ich der Grund für die Schmerzen der Orcgeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[10102] = { id = 10102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gelüftetes Geheimnis", description = "Als meine Energien sich über die Jahrhunderte nach und nach verflüchtigten, nahm eine Leere meinen Platz ein und verschlang die Seelen in der Nähe. Hilflos musste ich zusehen, wie ganze Generationen von Orcseelen in den Wirbel hineingezogen wurden. Vor Kurzem bemächtigten meine Feinde sich des Wirbels und benutzten ihn, um zahllose Leerdiener in ihre Brennende Legion zu rufen.\n\nNun liegt der Schlüssel zur Beendigung dieses Kreislaufs und der Befreiung der Orcgeister bei einem anderen Naaru, A'dal. Ich konnte seine Essenz in der uralten Stadt Shattrath in den Wäldern von Terokkar fühlen.", sourceObjective = "Sprecht mit A'dal in Shattrath.", completion = "Es war weise von K'ure, Euch hierherzuschicken. Wir können das Leiden der Orcahnen nicht lindern, doch es gibt einen, der es kann.\n\nEinen, der bald im Licht wiedergeboren wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[10103] = { id = 10103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Zurai", description = "Mit der Ankunft von Feldkommandeur Romus und seinen Streitmächten sind die Allianz und ihre Draeneifreunde mutiger geworden. Sie wandeln alle alten Draeneiruinen von hier bis Shattrath in Heerlager um.\n\nAls Antwort darauf haben die Trolle einen neuen Außenposten im östlichen Teil der Zangarmarschen errichtet, südlich des Todesmoors. Sie nennen ihn Sumpfrattenposten. Ich bin froh, dass sie sich in einer solchen Umgebung ihren Humor bewahrt haben. Ich wollte jedenfalls nicht mit ihnen tauschen.\n\nDer Kommandeur des Posten hat mich gebeten, ihm alle Mann zu schicken, die ich entbehren kann.", sourceObjective = "Meldet Euch bei Zurai im Sumpfrattenposten in den Zangarmarschen.", completion = "Um ehrlich zu sein hatte ich mehr Leute erwartet, aber Ihr müsst reichen. Willkommen im Sumpfrattenposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10104] = { id = 10104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorgen um Tuurem", description = "Die Gerüchte über Tuurem sind beunruhigend. Manche sagen, die Ruinen der Stadt laufen vor verrückten Zerschlagenen und Verirrten über, während gierige Artefaktjäger Draeneirelikte stehlen.\n\nEs ist schwer zu sagen, welche wahr und welche falsch sind, aber es liegt in unserer Verantwortung, die Ruinen so gut es geht zu schützen. Sucht Andarl in der Feste in den Wäldern von Terokkar. Er ist eine Art Forscher für magische Relikte. Er weiß wahrscheinlich besser als alle anderen Bescheid, was dort vor sich geht.", sourceObjective = "Sprecht mit Andarl in der Feste in den Wäldern von Terokkar.", completion = "Ich fühle mich geschmeichelt, dass Euer Freund von den Zerschlagenen mich für einen Gelehrten für Relikte seines Volkes hält, aber um ehrlich zu sein, habe ich seit meiner Ankunft nicht viel Gelegenheit gehabt, sie zu studieren. Das war sicherlich meine Absicht, aber als ich hier ankam, musste ich feststellen, dass es andere Dinge gibt, um die ich mich dringend kümmern muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[10105] = { id = 10105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachrichten für Rakoria", description = "Jetzt, da der Sumpfrattenposten fertig ist, haben wir nicht mehr so viel Kontrolle über die Wege, die in die Marschen und aus ihnen heraus führen. Unsere Anwesenheit in den Wäldern von Terokkar ist nun viel unsicherer. Trotzdem wartet Rakoria in der Steinbrecherfeste auf Nachrichten über unsere Fortschritte hier.\n\nSie ist sehr schlau und tüchtig, {name}, aber seid vorsichtig, wenn Ihr in ihrer Nähe seid. Sie hat viele Waren, die sie nur zu gerne auf den Weg schicken würde, aber glaubt nicht, dass sie nur unser Bestes im Sinn hat. Rakoria geht dorthin, wo sie den besten Gewinn machen kann.", sourceObjective = "Sprecht mit Rakoria in der Steinbrecherfeste in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10106] = { id = 10106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[10107] = { id = 10107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatische Maßnahmen", description = "Kilrath hat Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Südosten, nahe der Grenze zu Terokkar. Viel Erfolg, {name}!\n\nSeid auf der Hut, er ist ein Klingenmeister...", sourceObjective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.", progress = "Sprecht.", completion = "Wie also lautet Eure Entscheidung? Soll es Krieg geben, oder werdet Ihr mich unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10108] = { id = 10108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatische Maßnahmen", description = "Die Agenten der Jägerin haben Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Osten. Viel Erfolg, {name}!\n\nSeid auf der Hut, er ist ein Klingenmeister...", sourceObjective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.", completion = "Wie also lautet Eure Entscheidung? Soll es Krieg geben, oder werdet Ihr mich unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10109] = { id = 10109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich muss sie haben!", description = "Könnt Ihr sie sehen?? Bei Gazlows wundervollem Mundgeruch, ich muss diese Eier haben! Ihr seht aus wie jemand, den man gebrauchen kann.\n\nIch sag Euch was, {race}, wenn Ihr ein paar Dinge für mich sammelt, damit ich meinen Spring-o-Mat 4000 zum Laufen bekomme, werde ich Euch einen Schlüssel geben, mit dem auch Ihr die Maschine bedienen könnt! Was man mit einem Spring-o-Mat 4000 machen kann? Wohl eher was man damit nicht machen kann...\n\nIch brauche Luftelementargas von den Luftelementaren in Nagrand. Sie sind überall, fragt mich also nicht, wo Ihr sie finden könnt!", sourceObjective = "Wazdaz gegenüber der Klanwacht im Süden von Nagrand möchte, dass Ihr ihm 3 Einheiten Luftelementargas bringt.", progress = "Habt Ihr das Gas?", completion = "Ausgezeichnet! Nur ein paar kleine Einstellungen und dieses Ding ist so gut wie neu. Oh richtig, Euer Schlüssel! Bitte sehr.\n\nDer Spring-o-Mat hat übrigens noch ein paar Macken, die ich noch reparieren muss. Äh, seid einfach vorsichtig damit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10110] = { id = 10110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10111] = { id = 10111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir das Ei!", description = "Jetzt, da Ihr initiiert wurdet, möchte ich, dass Ihr mir dieses Ei bringt! Benutzt den Spring-o-Mat und versucht, das Nest genau in der Mitte zu treffen. Aber seid vorsichtig! Schlechte Sprünge können in körperlichen Schäden oder dauerhaften schweren Wunden resultieren.", sourceObjective = "Wazdaz in Nagrand möchte, das Ihr den Spring-o-Mat 4000 benutzt, um in das Nest in dem nahe gelegenen Baum zu springen und das geheimnisvolle Ei zu stehlen.", progress = "Habe ich meine Vorliebe für Eier erwähnt?", completion = "Nun, es ist kein Ei... Aber Hühnchen mag ich auch! Ich beiße mich einfach durch diese riesige Klaue durch! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[10112] = { id = 10112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein persönlicher Gefallen", description = "Hmmm? Eine Kiste sagt Ihr? Oder waren es mehrere? Wisst Ihr aus welchem Material sie war?\n\nUnd wie heißt der Händler? Empoor? Und Ihr seid Euch sicher, dass er ein Zerschlagener ist? Ich mache nicht viele Geschäfte mit ihresgleichen.\n\nVielleicht hilft es meinem Gedächtnis ein wenig auf die Sprünge, wenn Ihr mir einen Gefallen tut.\n\nDie Arakkoa der Skith - diese primitiven Zauberer - haben neulich eine große Schiffladung meiner magischen Waren gestohlen. Ich will alles zurückhaben!\n\nIhr könnt das Skithversteck südlich von Shattrath finden.", sourceObjective = "Holt 5 von Lathrais gestohlenen Waren zurück und bringt sie zu Windhändler Lathrai bei der Taverne Weltenend im Unteren Viertel in Shattrath.", progress = "Hmm, wird mein Gedächtnis schon besser?", completion = "Ja, ich glaube, es wird alles deutlicher.\n\nUnd ich glaube, dass Euer Eifer in dieser Angelegenheit mit mehr als nur den Informationen, die Ihr sucht, belohnt werden sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10113] = { id = 10113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwarys Safari", description = "\"Geht und sucht ein paar Vorräte\", hat er gesagt. Ich bin fast fünfzehn Mal getötet worden, bevor ich diesen Ort hier überhaupt gefunden habe! Diese Zerschlagenen sind vielleicht nicht das gastfreundlichste Volk, das ich kenne, aber immerhin haben sie nicht versucht, mir die Haut von den Knochen zu ziehen!\n\nWie auch immer, ich gehe nicht zurück. Meine Tage als Großwildjäger sind vorbei. Wenn ihr zufällig nach Nordosten Richtung Zangarmarschen geht und bei Nesingwarys Safari vorbeikommt, sagt dort Bescheid, dass \"die Flinte\" gekündigt hat.\n\nHey, vielleicht könnt Ihr ja meinen Platz einnehmen! Viel Glück, <Fremder/Fremde>.", sourceObjective = "\"Die Flinte\" Jones möchte, dass Ihr mit Hemet Nesingwary in Nesingwarys Safari am nordöstlichen Rand von Nagrand sprecht.", completion = "Ich schätze, wir müssen einen Ersatz für den Wasserträger finden. Nun, Ihr seht aus wie ein kräftiger {class}. Interesse an einem Job? Oder kommt Ihr wegen der Jagd?", sourceObjectiveStatus = "unverified-source-field" }
quests[10114] = { id = 10114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwarys Safari", description = "Diese Orcs haben noch nie zuvor einen Tauren gesehen, könnt Ihr das glauben? Wenn Hauptmann Kroghan nicht wäre, würden sie mich wahrscheinlich in diesem Moment zum Abendessen verschlingen!\n\nAber wo sind meine Manieren? Ich bin Ohlorn Fernreiser, herausragender Jäger! Ich gehöre zu Nesingwarys Expedition, die sich von Azeroth aus auf die Jagd nach Großwild hierher begeben hat. Wenn Ihr Euch für die Jagd interessiert, solltet Ihr meine Truppe in Nesingwarys Safari östlich von hier an den Grenzen zu den Zangarmarschen besuchen.", sourceObjective = "Ohlorn Fernreiser möchte, dass Ihr mit Shado 'Fitz' Fernreiser in Nesingwarys Safari in Nagrand sprecht.", completion = "Ich bin erleichtert zu hören, dass er in Sicherheit ist. Seid Ihr hier, um an der Jagd teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10115] = { id = 10115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolchfennkrise", description = "Die Kurenai und die Draenei sind nicht immer der gleichen Meinung, besonders nicht, wenn es um die Verirrten geht. Wir helfen den Verirrten, die sich an uns wenden, gerne, aber wir werden sie niemals verfolgen. Manche Draenei sind andererseits überzeugt davon, dass sie alle 'erlöst' werden müssen.\n\nEs gibt jedoch Zeiten, in denen sogar die Verirrten zu weit gehen, wie zum Beispiel der Dolchfennstamm. In ihrem Dorf im Westen hantieren sie mit Giften herum, lügen und betrügen, was für uns sehr unnatürlich ist.\n\nWir müssen dem ein Ende bereiten, bevor der bösartige Dolchfennstamm seinen Einfluss noch weiter ausbreiten kann.", sourceObjective = "Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn.", completion = "Ihr habt gute Arbeit geleistet, {name}. Keiner ist der Meinung, dass es noch Erlösung für den Dolchfennstamm gegeben hätte, aber ich glaube nicht, dass die Draenei in dieser Situation schnell genug gehandelt hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10116] = { id = 10116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Häuptling Mummaki", description = "Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamms der Verirrten, wegen seiner brutalen Angriffe auf die Oreborzuflucht.\n\nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Kurenai und Draenei auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.\n\nReisenden wird nahe gelegt, die Gegend um Dolchfenn westlich der Oreborzuflucht zu meiden.\n\nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Ikuti eingefordert werden.", sourceObjective = "Bringt Häuptling Mummakis Totem zu Ikuti in der Oreborzuflucht.", progress = "Ihr wollt also das Kopfgeld für Häuptling Mummaki einfordern?", completion = "Bemerkenswert! Es gab schon einige vor Euch, die das Kopfgeld gewinnen wollten, aber keiner von ihnen ist je zurückgekehrt. Es ist nicht schwer sich auszumalen, was ihnen wohl zugestoßen ist.\n\nIch bin sehr erleichtert, dass wir in Zukunft nichts mehr von Mummaki und seinem Gesindel zu befürchten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10117] = { id = 10117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Häuptling Mummaki", description = "Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamm der Verirrten, wegen seiner brutalen Angriffe auf Zabra'jin und seine Einwohner.\n\nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Späher und Boten auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.\n\nReisenden wird nahe gelegt, die Gegend um Dolchfenn nordwestlich von Zabra'jin zu meiden.\n\nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Schattenjäger Denjai eingefordert werden.", sourceObjective = "Bringt Häuptling Mummakis Totem zu Schattenjäger Denjai.", progress = "Ihr wollt also das Kopfgeld für Häuptling Mummaki einfordern?", completion = "Ihr habt meinen Dank, {name}. Ich hatte mir schon überlegt, einen Teil der Garnison dorthin zu schicken und Mummaki selbst zu erledigen. Welche Folgen das jedoch für Zabra'jin gehabt hätte, ist schwer zu sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10118] = { id = 10118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Dolchfenn", description = "Von allen Stämmen der Verirrten in den Zangarmarschen ist der Dolchfennstamm der gerissenste und aggressivste. Er ist sehr gut organisiert und macht keinen Hehl daraus, dass er gerne die Kontrolle über alle Verirrten in den Marschen hätte.\n\nIhren Angriffen sind schon viele meiner Späher und Boten zum Opfer gefallen. Ich kann es mir nicht leisten, noch mehr Männer zu verlieren.\n\nWenn wir nicht bald handeln, werden sie die komplette Kontrolle über alle Straßen erlangen und Zabra'jin einkesseln.", sourceObjective = "Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn und kehrt dann zu Schattenjäger Denjai in Zabra'jin zurück.", completion = "Ich glaube, Ihr habt ihnen eine ziemlich deutliche Botschaft zukommen lassen. Vielleicht haben meine Männer nun nicht mehr so viel Angst vor dem Dolchfennstamm. Oder sie schämen sich zumindest für ihren Mangel an Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[10119] = { id = 10119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: Durch das Dunkle Portal", description = "Zwanzig Jahre lang war es ruhig um das Dunkle Portal – es wurde zu einem Symbol längst vergangener Zeiten.\n\n<Reldorn sieht sich um.>\n\nIch habe nicht geglaubt, dass ich den heutigen Tag erleben würde, aber hier stehen wir nun und schauen tief in den Abgrund.\n\nAuf der anderen Seite des Portals sind wir in einem grausamen Krieg gefangen – ein Krieg, den wir nicht ohne Hilfe gewinnen können. Ihr müsst durch das Dunkle Portal reisen und unseren Truppen helfen, {class}.\n\nMeldet Euch umgehend bei Kommandant Duron. Er erwartet Euch in der Scherbenwelt...", sourceObjective = "Reist durch das Dunkle Portal und sucht Kommandant Duron. Er wartet auf der anderen Seite auf Eure Ankunft - in der Scherbenwelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10120] = { id = 10120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft in der Scherbenwelt", description = "Mit der Unterstützung der Allianz können meine Leute die Verteidigung hier aufrechterhalten, aber Ihr müsst dringend meinen Bericht zu General Krakork in Thrallmar bringen. Mit seiner Hilfe können wir diese Dämonen zurück in den Abgrund drängen, aus dem sie gekommen sind! Sprecht mit Vlagga Freyfeder. Sie wird Euch schnell auf den Weg dorthin bringen.", sourceObjective = "Generalleutnant Orion beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Orions Bericht zu Vlagga Freyfeder bringt.", progress = "Ich habe gesehen, wie Ihr mit Orion gesprochen habt - es muss eine wichtige Angelegenheit sein...", completion = "Ihr seid also Orions neuer Bote? Ich hoffe, es ergeht Euch besser als dem letzten, den er geschickt hat, {class}. Mit der vorrückenden Legion schafft Ihr es niemals zu Fuß nach Thrallmar. Sagt Bescheid und mein treuer Wyvern wird Euch sicher dorthin bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10121] = { id = 10121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brennende Legion ausrotten", description = "Auch wenn dieses Land voller neuer, unbekannter Feinde ist, ist die Brennende Legion immer noch die größte Bedrohung für unsere Expedition. Einer meiner vertrauenswürdigsten Krieger, Unteroffizier Schädelbrecher, hat die Taktiken der Legion untersucht und versucht, das wahre Ziel der Legion in diesem Land herauszufinden. Ihr findet ihn bei der Versorgungskarawane außerhalb des südlichen Walls.\n\nUnd {name}, hütet Euch vor der Legion. Ihre Bösartigkeit darf nicht unterschätzt werden.", sourceObjective = "Sprecht mit Unteroffizier Schädelbrecher bei der Versorgungskarawane außerhalb von Thrallmar im Osten.", completion = "Ihr habt sicher auf Eurem Flug vom Dunklen Portal die Krieger der Legion überall in der Landschaft gesehen. Auch wenn wir sie in der Schlacht am Berg Hyjal vor etwa 5 Jahren besiegt haben, haben diese verfluchten Dämonen immer noch nicht genug. Wenn sie auf eine Herausforderung aus sind, wird die Horde ihnen entsprechend antworten!\n\nWir Orcs haben mit der Legion mehr als nur eine Rechnung zu begleichen! Was ist mit Euch, {name}? Soll ich Euch von unserem Feind erzählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10122] = { id = 10122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erstreckung der Zitadelle", description = "Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Späher, Gefreiter Imarion, losgeschickt, um ihre Vorgehensweise zu erkunden, aber er ist noch nicht mit seinem Bericht zurückgekehrt.\n\nImarion sollte sich auf das nördlichste Lager entlang des Südlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet ihn, {name}. Ohne seinen Bericht sitzen wir hier hilflos herum.", sourceObjective = "Durchsucht das nördlichste Lager entlang des Südlichen Bollwerks nach einer Spur von Gefreiter Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10123] = { id = 10123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsfunkenklamm", description = "Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.\n\nSie haben Schreckenslords in der Teufelsfunkenklamm östlich von hier postiert. Sie sind für diese höllischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.", sourceObjective = "Unteroffizier Schädelbrecher bei der Versorgungskarawane östlich von Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.", completion = "Ausgezeichnete Arbeit, Soldat. Die Häufigkeit der Angriffe wird nun sicher nachlassen - zumindest bis sie neue Schreckenslords schicken.\n\nNun zu den schlechten Nachrichten: ich habe Eure neuen Befehle...", sourceObjectiveStatus = "unverified-source-field" }
quests[10124] = { id = 10124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorposten: Häschersturz", description = "Eure Fähigkeiten in der Schlacht sind dem Oberkommando aufgefallen, {class}. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 200 Schritte nach Osten und biegt bei der herstehenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To'arch.\n\nUnd jetzt weggetreten!", sourceObjective = "Meldet Euch bei Vorpostenkommandant To'arch im Häschersturz.", completion = "Ihr habt also die Teufelsfunkenklamm aufgeräumt, was? Gut zu hören - wir brauchen Soldaten wie Euch, die sich kopfüber in die Schlacht stürzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10125] = { id = 10125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Kommunikation unterbrechen", description = "Direkt im Osten liegt die Front der Legion. Die Front dient der Brennenden Legion als mobile Kommandobasis. Ihr könnt die Sender der Legion aus der Erde herausragen sehen. Mit ihrer Hilfe kommuniziert die Legion mit ihren Konstruktionslagern in der ganzen Scherbenwelt. Sie dienen ebenfalls als Schutzeinrichtung zur Verschlüsselung sämtlicher Übertragungen, sodass eine magische Überwachung nicht mehr möglich ist.\n\nIch möchte, dass Ihr diesen Sprengstoff nehmt und die Sender damit zerstört. Zerstört sie alle, {name}! Sie sind von Süden nach Norden an der Grenze der Front der Legion aufgereiht.", sourceObjective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr To'archs Sprengstoff benutzt, um den Sender der Legion: Bosheit, Sender der Legion: Zorn, Sender der Legion: Hass und Sender der Legion: Furcht zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[10126] = { id = 10126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsboss Nekroggs Befehle", description = "Die Anweisungen sind mit Kriegsboss Nekrogg unterzeichnet. Sie befehlen den Höllenorcs in diesem Lager, ihren menschlichen Gefangenen zum Verhör nach Süden zu bringen.\n\nLeutnant Amadi hat erwähnt, dass das Südliche Bollwerk über mehrere Höllenorclager verfügt. Vielleicht haben sie Gefreiter Imarion zum nächsten größeren Abschnitt des Walls Richtung Süden gebracht.\n\nDa dieser Befehl von Verhör spricht, scheint es den Höllenorcs wichtig zu sein, dass Gefreiter Imarion am Leben bleibt. Nehmt schnell ihre Spur auf, bevor sie es sich anders überlegen!", sourceObjective = "Reist entlang der westlichen Seite des Südlichen Bollwerks nach Süden und durchsucht das nächste Lager nach einer Spur von Gefreiter Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10127] = { id = 10127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Das Band zerreißen", description = "Es wäre Vernachlässigung meiner Pflicht, wenn ich Euch nicht befehlen würde, die Dämonen an der Front der Legion, östlich von dieser Basis, zu vernichten.\n\nBeide Seiten der Front sind nach demselben Muster aufgebaut: Teufelstreiber wandeln zwischen den Lagern der Legion hin und her, die von Zornwächtern bewacht werden. Die ganze Operation wird von einer Unterwerferin der Shivan beaufsichtigt. Tötet sie alle und überlasst Kazzak den Rest.\n\nUnd passt auf die patrouillierenden Teufelshäscher auf. Ich weiß, dass Ihr stark seid, aber diese Biester machen mit Euch kurzen Prozess.", sourceObjective = "Vorpostenkommandant To'arch am Häschersturz auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Shi'aziv tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10128] = { id = 10128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Soldat Imarion", description = "Die Spuren führen von Imarions Ausrüstung aus nach Süden, anscheinend entlang des Südlichen Bollwerks. Aus den Furchen lässt sich schließen, dass die Entführer es eilig hatten, ihn an den nächsten Ort zu bringen, aber warum?\n\nHat ihn dort jemand erwartet? Vielleicht Kriegsboss Nekrogg, der Anführer, der in den Befehlen, die Ihr weiter nördlich gefunden habt, erwähnt wurde?\n\nDas Schild und die Spuren werfen mehr Fragen auf, als sie beantworten, aber es scheint sicher, dass Ihr dort, wo Ihr Gefreiter Imarion findet, auch Kriegsboss Nekrogg finden werdet.", sourceObjective = "Setzt Euren Weg entlang des Südlichen Bollwerks fort und sucht nach dem Ort, an dem Kriegsboss Nekrogg Gefreiter Imarion gefangen hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[10129] = { id = 10129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Tore Murketh und Shaadraz", description = "Wir haben die beiden Haupttransporter, mit denen die Brennende Legion ihre Verstärkung herbeiholt, ausgemacht: Tor Murketh und Tor Shaadraz.\n\nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie beide in Stücke sprengt!\n\nHier sind die Bomben, die Ihr dafür benötigt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht mit Schwadronskommandant Brack - er wird Euch einen Wyvern zur Verfügung stellen.", sourceObjective = "Sprecht mit Schwadronskommandant Brack, bombardiert Tor Murketh und Tor Shaadrez und kehrt dann zu Vorpostenkommandant To'arch im Häschersturz zurück.", progress = "Wenn Ihr beim ersten Versuch verfehlt, startet einen neuen...", completion = "Das wird sie um Wochen zurückwerfen! Fantastische Arbeit, {name}. Die Legion hätte sicher nie mit so starkem Widerstand gerechnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10130] = { id = 10130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die westliche Flanke", description = "Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.\n\nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um die Ehrenfeste in die Zange zu nehmen.\n\nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Die Ehrenfeste kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.", sourceObjective = "Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Leutnant Amadi im westlichen Wachturm der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10131] = { id = 10131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluchtplan", description = "Wie ich schon gesagt habe, hier rauszukommen wird nicht leicht. Kriegsboss Nekrogg mag vielleicht wie ein übergroßer Schläger aussehen, aber er ist kein Dummkopf.\n\nEr wird den Käfigschlüssel nicht aus den Augen lassen und kommt nicht aus seinem Turm auf dieser massiven Mauer heraus, bis er bereit ist, mich oder diese Orcfrau, die er gefangen hat, zu verhören.\n\nWir brauchen schon etwas Besonderes, um ihn aus diesen Mauern zu locken, aber ich habe einen Plan. Sucht einen der Grenadiere, die am Südlichen Bollwerk entlang patrouillieren, und bringt mir etwas von seinem Sprengstoff.", sourceObjective = "Tötet einen Grenadier des Lachenden Schädels und bringt seine primitive Sprengladung zu Gefreiter Imarion im Außenposten von Gor'gaz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10132] = { id = 10132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kolossale Bedrohung", description = "Seht Ihr diesen riesigen roten Kristall im Norden? Er ist vor Kurzem vom Himmel gefallen und hat dabei ein großes Erdbeben ausgelöst.\n\nAls wir hierher kamen, um den Grund für den Aufruhr zu erforschen, haben wir all die Kolosse hier gesehen, die zuvor noch nicht da waren.\n\nEs ist eindeutig etwas faul an dem Kristall und den Energien, die er ausstrahlt, aber ich habe keine Zeit dafür. Ich muss mich zuerst um diese Bergriesen kümmern.\n\nIch möchte, dass Ihr zum Himmelssturzgrat geht und Euch um sie kümmert.", sourceObjective = "Tötet 5 tobende Kolosse und kehrt dann zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", completion = "Gute Arbeit.\n\nWenn Ihr mich fragt, müssen wir einfach genug von diesen Kolossen töten, dann brauchen wir uns nicht mehr um diese merkwürdigen Kristall in der Mitte kümmern.\n\nHier, nehmt eines hiervon als Belohnung der Expedition des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[10133] = { id = 10133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Tötet den Boten", description = "Euer Geschick bereitet der Legion große Schwierigkeiten, {name}. Meine Späher haben mich informiert, dass die Legion Kuriere benutzt, um untereinander zu kommunizieren. Wir haben es geschafft, ihre Truppen vom Hauptlager abzuschneiden!\n\nWorum ich Euch nun bitte ist mehr, als ich von einem normalen Soldaten verlangen würde.\n\nDer Kurier der Legion reist zwischen den Teichen von Aggonar und dem Konstruktionsbasis: Mageddon, nördlich von hier, hin und her. Ihr müsst den Kurier bei Mageddon abfangen, ihn erledigen und mit dem Schriftwechsel der Legion zu mir zurückkehren.", sourceObjective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr Arix'maladish findet und tötet und den Schriftwechsel der Legion besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10134] = { id = 10134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise des purpurnen Kristalls", description = "Als der Koloss Eurem Angriff zum Opfer fällt, bemerkt Ihr, dass er ein rotes Kristallfragment in der Hand hält.\n\nIn der Hand des Riesen schien es sehr klein und unauffällig, aber für Euch ist das Stück sehr schwer zu tragen. Es sieht sehr verdächtig nach einem Stück des riesigen roten Kristalls in der Mitte des Grats aus.\n\nDies ist ganz sicher ein Hinweis auf die merkwürdigen Dinge, die hier geschehen. Ihr seid Euch sicher, dass die Druiden beim Posten des Cenarius im Süden den Splitter sehen wollen.", sourceObjective = "Bringt den Purpurkristallsplitter zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel.", progress = "Das ist ein ganz schön großer Kristall, den Ihr da habt. Habt Ihr ihn von den Kolossen im Grat?\n\nLasst mich ihn anschauen.", completion = "Hm, für mich sieht es einfach wie ein großer Klumpen ungeschliffenen Kristalls aus.\n\nZugegeben, ich fühle eine kranke, böse Aura, die von ihm ausgeht, aber das ist nicht gerade mein Spezialgebiet. Ich bin nur hier, um die Bedrohung durch die Bergriesen aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10135] = { id = 10135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Seid der Bote", description = "Ich bin nur ein Feldkommandeur, {class}. Die Befugnis, auf solche Informationen hin zu handeln, fällt nur unserem Anführer, Nazgrel, zu. Ihr müsst den Schriftwechsel nach Thrallmar zu ihm bringen. Reitet schnell wie der Wind, Soldat. Lasst Euch durch nichts aufhalten!", sourceObjective = "Bringt den Schriftwechsel der Legion zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10136] = { id = 10136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausame Pläne", description = "Magister Blutfalke hat endlich den Schriftwechsel der Legion, den Ihr gefunden habt, entziffert. Wie es aussieht, handelt es sich dabei um Angriffspläne, die von einem Leutnant des Hochlords Kazzak geschickt wurden – Arazzius der Grausame. Offensichtlich hat Arazzius den Befehl über die Bodentruppen auf der Höllenfeuerhalbinsel. Es ist an der Zeit, dass wir seinen Befehl beenden, {name}. Vernichtet ihn mit größter Vorsicht.\n\nBegebt Euch zu den Teichen von Aggonar im Westen und setzt dem so genannten 'Legionslord' ein Ende. Heute fordert die Horde die Höllenfeuerhalbinsel zurück. Die Legion möge verdammt sein.", sourceObjective = "Tötet Arazzius den Grausamen und kehrt danach zu Nazgrel in Thrallmar zurück.", completion = "Alle kommenden Generation werden diesen Tag bejubeln, {name}. Sie werden von Eurem Heldenmut singen. Ich wünschte, Thrall wäre hier, um diesen Sieg mit uns zu feiern. Die Legion liegt am Boden, und die Höllenfeuerhalbinsel gehört wieder der Horde! Vielleicht besteht doch noch Hoffnung für diese verwüstete Welt und unser Volk auf ihr.\n\nLok'tar ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10137] = { id = 10137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kriegsboss provozieren", description = "Der Erfolg des Plans hängt von der Qualität des Sprengstoffs ab...\n\nSo ungern ich mich auch auf etwas verlasse, das von einem Orc hergestellt wurde, ist dies meine einzige Möglichkeit hier rauszukommen. Nehmt dies und werft es gegen das Banner, das vom Turm da oben weht.\n\nWenn es explodiert wird Kriegsboss Nekrogg es sich nicht nehmen lassen, ein Exempel an dem Störenfried zu statuieren. Tötet ihn und nehmt den Schlüssel, um meinen Käfig zu öffnen. Viel Erfolg, {name}.", sourceObjective = "Benutzt die primitiven Sprengladungen um einen Tumult zu veranstalten und Kriegsboss Nekrogg aus seinem Turm zu locken. Tötet ihn, besorgt Nekroggs Schlüssel und öffnet damit Gefreiter Imarions Käfig. Wenn Ihr Gefreiter Imarion befreit habt, meldet Euch bei Leutnant Amadi.", sourceObjectiveStatus = "unverified-source-field" }
